DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating payment.idx_period_id...';END$$;
CREATE INDEX idx_period_id ON payment.balance_group USING btree (period_id DESC) INCLUDE (in_balance, current_calc, recalc, pay, account_id);


