DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating house.info...';END$$;
CREATE MATERIALIZED VIEW house.info (district_id, district_name, address_parser_guid, settlement_id, settlement_name, street_book_id, street_book_name, street_id, street_name, number, house_kind_name, inner_city_district_id, inner_city_district_name, korpus, short_adress, house_id, work_id, work_counting_id, organization_id, organization_counting_id, order_id) AS SELECT ss.district_id,
    ad.name AS district_name,
    ah.address_parser_guid,
    ss.id AS settlement_id,
    (((st.short_name)::text || ' '::text) || (ss.name)::text) AS settlement_name,
    "as".street_book_id,
    asb.short_name AS street_book_name,
    ah.street_id,
    "as".name AS street_name,
    ah.number,
    ahk.short_name AS house_kind_name,
    ah.inner_city_district_id,
    acd.name AS inner_city_district_name,
    ah.korpus,
    concat(
        CASE
            WHEN (acd.id = 0) THEN ''::text
            ELSE ((acd.name)::text || ', '::text)
        END,
        CASE
            WHEN ((COALESCE(asb.short_name, ''::character varying))::text <> ''::text) THEN ((asb.short_name)::text || ' '::text)
            ELSE ''::text
        END,
        CASE
            WHEN ((COALESCE("as".name, ''::character varying))::text <> ''::text) THEN "as".name
            ELSE ''::character varying
        END,
        CASE
            WHEN (((COALESCE("as".name, ''::character varying))::text <> ''::text) AND ((COALESCE(ah.number, ''::character varying))::text <> ''::text)) THEN ', '::text
            ELSE ''::text
        END,
        CASE
            WHEN (((COALESCE(aht.short_name, ''::character varying))::text <> ''::text) AND ((COALESCE(ah.number, ''::character varying))::text <> ''::text)) THEN ((COALESCE(aht.short_name, ''::character varying))::text || ' '::text)
            ELSE ''::text
        END,
        CASE
            WHEN ((COALESCE(ah.number, ''::character varying))::text <> ''::text) THEN COALESCE(ah.number, ''::character varying)
            ELSE ''::character varying
        END,
        CASE
            WHEN (((COALESCE(ah.korpus, ''::character varying))::text <> ''::text) AND (((COALESCE(ah.number, ''::character varying))::text <> ''::text) OR ((COALESCE("as".name, ''::character varying))::text <> ''::text))) THEN ', '::text
            ELSE ''::text
        END,
        CASE
            WHEN ((COALESCE(ah.korpus, ''::character varying))::text <> ''::text) THEN (((COALESCE(ahk.short_name, ''::character varying))::text || ' '::text) || (COALESCE(ah.korpus, ''::character varying))::text)
            ELSE ''::text
        END) AS short_adress,
    ah.id AS house_id,
    ah.work_id,
    ah.work_counting_id,
    ah.organization_id,
    ah.organization_counting_id,
    ah.order_id
   FROM ((((((((adress.house ah
     JOIN adress.house_type aht ON ((aht.id = ah.house_type_id)))
     JOIN adress.house_kind ahk ON ((ahk.id = ah.house_kind_id)))
     JOIN adress.street "as" ON (("as".id = ah.street_id)))
     JOIN adress.street_book asb ON ((asb.id = "as".street_book_id)))
     JOIN adress.settlement ss ON ((ss.id = "as".settlement_id)))
     JOIN adress.settlement_type st ON ((st.id = ss.type_id)))
     JOIN adress.district ad ON ((ad.id = ss.district_id)))
     JOIN adress.inner_city_district acd ON ((acd.id = ah.inner_city_district_id)));
ALTER MATERIALIZED VIEW house.info OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating house.info...';END$$;
COMMENT ON MATERIALIZED VIEW house.info IS ' =============================================
 Author:		Глещинский Д.В.
 Create date: 04.02.2016
 Modified date: 19.03.2021 Юркин Е.Ю., подчистил от избыточных данных в Short_Adress
 Description:	Информация о доме
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating payment.pay_for_1c_v2...';END$$;
CREATE MATERIALIZED VIEW payment.pay_for_1c_v2 (organization_inn, organization_kpp, batch_date, batch_id, account_name, district_name, payment_date, batch_from_name, rs, sublist_name, sublist_id, detail_sum, rs_type, payment_id, per_pay, payment_comiss, contract_inn, district_id, house_id, contract_id, customer_type, payment_type, adjustment_type, check_type, cashless_payment, group_id, is_kp, number_pp, date_pp) AS SELECT oll.inn AS organization_inn,
    oll.kpp AS organization_kpp,
    pb.date AS batch_date,
    pb.id AS batch_id,
    ai.account_name,
    ai.district_name,
    pl.date AS payment_date,
    b.name AS batch_from_name,
    oc.rs,
    us.name AS sublist_name,
    us.id AS sublist_id,
    pd.sum AS detail_sum,
        CASE
            WHEN ((oc.rs)::text = '00000000000000000000'::text) THEN true
            ELSE false
        END AS rs_type,
    pl.id AS payment_id,
    pr.date_end AS per_pay,
    COALESCE(br.fee, (0)::numeric) AS payment_comiss,
        CASE
            WHEN (pc.contract_id IS NOT NULL) THEN
            CASE
                WHEN (ltrim(rtrim((pc.inn)::text)) = ''::text) THEN NULL::text
                ELSE ltrim(rtrim((pc.inn)::text))
            END
            ELSE NULL::text
        END AS contract_inn,
    ('МО-'::text || ((hi.district_id)::character varying(10))::text) AS district_id,
    ('Д-'::text || ((ai.house_id)::character varying(5))::text) AS house_id,
    pc.contract_id,
    pc.type AS customer_type,
    pl.type_id AS payment_type,
        CASE
            WHEN ((b.number)::integer = 19) THEN 1
            WHEN ((b.number)::integer = 5) THEN 2
            WHEN ((b.number)::integer = 99) THEN 3
            ELSE 0
        END AS adjustment_type,
    pl.check_type,
    pl.cashless_payment,
    COALESCE(kp.group_id, 1) AS group_id,
    COALESCE(kp.is_kp, 0) AS is_kp,
    pp.number_pp,
    pp.date_pp
   FROM ((((((((((((((payment.batch pb
     JOIN payment.list pl ON ((pl.batch_id = pb.id)))
     JOIN payment.detal pd ON ((pd.payment_id = pl.id)))
     LEFT JOIN period.list pr ON ((pr.id = pl.payment_period_id)))
     JOIN adress.info ai ON ((ai.account_id = pl.account_id)))
     JOIN house.info hi ON ((hi.house_id = ai.house_id)))
     JOIN organization.list ol ON ((ol.id = ai.organization_id)))
     JOIN organization.counting oc ON ((oc.id = pb.counting_id)))
     JOIN utility.sublist us ON ((us.id = pd.sublist_id)))
     JOIN parametr.book b ON ((b.id = pb.bank_id)))
     JOIN organization.list oll ON ((oll.id = oc.list_id)))
     LEFT JOIN bank.registry_payment br ON ((br.payment_id = pl.id)))
     LEFT JOIN LATERAL ( SELECT cl.inn,
            c.id AS contract_id,
            cl.surname,
            cl.name,
            cl.middlename,
            cl.type,
            cl.full_name,
            ca.id AS person_id
           FROM ((((contragent.account ca
             JOIN adress.account aa ON ((aa.id = ca.account_id)))
             JOIN contragent.owner_documents od ON ((od.contragent_account_id = ca.id)))
             JOIN contragent.list cl ON ((cl.id = ca.contragent_id)))
             LEFT JOIN LATERAL ( SELECT cc.id
                   FROM (contragent.contract cc
                     JOIN contragent.contract_account ac ON ((ac.contract_id = cc.id)))
                  WHERE ((ac.account_id = ca.account_id) AND (cc.date_end IS NULL))) c ON (true))
          WHERE ((ca.is_responsible = true) AND (od.date_end IS NULL) AND (ca.account_id = ai.account_id))
          ORDER BY cl.id
         LIMIT 1) pc ON (true))
     LEFT JOIN ( SELECT aa.id AS account_id,
            cgs.group_id,
            max(COALESCE((us_1.is_kp)::integer, 0)) AS is_kp
           FROM ((utility.contragent_group_sublist cgs
             JOIN utility.sublist us_1 ON (((us_1.id = cgs.sublist_id) AND (cgs.date_end IS NULL))))
             JOIN adress.account aa ON ((aa.group_id = cgs.group_id)))
          GROUP BY aa.id, cgs.group_id) kp ON ((kp.account_id = pd.account_id)))
     LEFT JOIN ( SELECT be.batch_id,
            de.number AS number_pp,
            (de.date)::date AS date_pp
           FROM (bank.bank_exchange_to_batch be
             JOIN bank.document_exchange de ON ((be.bank_exchange_document_id = de.id)))) pp ON ((pp.batch_id = pb.id)));
ALTER MATERIALIZED VIEW payment.pay_for_1c_v2 OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating payment.calc_for_1c_v2...';END$$;
CREATE MATERIALIZED VIEW payment.calc_for_1c_v2 (organization_inn, organization_kpp, date_end, date_calc, account_name, district_name, district_id, utility_name, sublist_id, calc, type_calc, tarif, volume, unit_name, okei, contract_inn, house_id, contract_id, customer_type, group_id, is_kp) AS SELECT ol.inn AS organization_inn,
    ol.kpp AS organization_kpp,
    pl.date_end,
    pl.date_end AS date_calc,
    ai.account_name,
    ai.district_name,
    ('МО-'::text || ((hi.district_id)::character varying(10))::text) AS district_id,
    us.name AS utility_name,
    us.id AS sublist_id,
    pb.current_calculate AS calc,
    false AS type_calc,
        CASE
            WHEN (pb.sublist_id = ANY (ARRAY[32, 34, 37])) THEN 0.00
            ELSE COALESCE(pb.tarif, (0)::numeric)
        END AS tarif,
        CASE
            WHEN (pb.sublist_id = ANY (ARRAY[32, 34, 37])) THEN 0.00
            ELSE COALESCE(pb.volume, (0)::numeric)
        END AS volume,
    uu.name AS unit_name,
    uu.code AS okei,
        CASE
            WHEN (pc.person_id IS NOT NULL) THEN
            CASE
                WHEN (ltrim(rtrim((pc.inn)::text)) = ''::text) THEN NULL::text
                ELSE ltrim(rtrim((pc.inn)::text))
            END
            ELSE NULL::text
        END AS contract_inn,
    ('Д-'::text || ((ai.house_id)::character varying(6))::text) AS house_id,
    pc.contract_id,
    pc.type AS customer_type,
    COALESCE((aa.group_id)::integer, 1) AS group_id,
    COALESCE(kp.is_kp, 0) AS is_kp
   FROM (((((((((payment.balance pb
     JOIN period.list pl ON ((pl.id = pb.period_id)))
     JOIN adress.info ai ON ((ai.account_id = pb.account_id)))
     JOIN house.info hi ON ((hi.house_id = ai.house_id)))
     JOIN organization.list ol ON ((ol.id = ai.work_id)))
     JOIN utility.sublist us ON ((us.id = pb.sublist_id)))
     JOIN utility.unit uu ON ((uu.id = us.unit_id)))
     JOIN adress.account aa ON ((aa.id = ai.account_id)))
     LEFT JOIN ( SELECT cg.group_id,
            max(COALESCE((su.is_kp)::integer, 0)) AS is_kp
           FROM (utility.contragent_group_sublist cg
             JOIN utility.sublist su ON ((su.id = cg.sublist_id)))
          GROUP BY cg.group_id) kp ON ((kp.group_id = aa.group_id)))
     LEFT JOIN LATERAL ( SELECT cl.inn,
            c.id AS contract_id,
            cl.surname,
            cl.name,
            cl.middlename,
            cl.type,
            cl.full_name,
            ca.id AS person_id
           FROM ((((contragent.account ca
             JOIN adress.account aa_1 ON ((aa_1.id = ca.account_id)))
             JOIN contragent.owner_documents od ON ((od.contragent_account_id = ca.id)))
             JOIN contragent.list cl ON ((cl.id = ca.contragent_id)))
             LEFT JOIN LATERAL ( SELECT cc.id
                   FROM (contragent.contract cc
                     JOIN contragent.contract_account ac ON ((ac.contract_id = cc.id)))
                  WHERE ((ac.account_id = ca.account_id) AND (cc.date_end IS NULL))) c ON (true))
          WHERE ((ca.is_responsible = true) AND (od.date_end IS NULL) AND (ca.account_id = ai.account_parent_id))
          ORDER BY cl.id
         LIMIT 1) pc ON (true))
  WHERE (pb.current_calculate <> (0)::numeric)
UNION ALL
 SELECT ol.inn AS organization_inn,
    ol.kpp AS organization_kpp,
    pl.date_end,
    pll.date_end AS date_calc,
    ai.account_name,
    ai.district_name,
    (hi.district_id)::character varying(10) AS district_id,
    us.name AS utility_name,
    us.id AS sublist_id,
    pb.calc,
    true AS type_calc,
        CASE
            WHEN (pb.sublist_id = ANY (ARRAY[32, 34, 37])) THEN 0.00
            ELSE COALESCE(pb.tarif, (0)::numeric)
        END AS tarif,
        CASE
            WHEN (pb.sublist_id = ANY (ARRAY[32, 34, 37])) THEN 0.00
            ELSE COALESCE(pb.volume, (0)::numeric)
        END AS volume,
    uu.name AS unit_name,
    uu.code AS okei,
        CASE
            WHEN (pc.person_id IS NOT NULL) THEN
            CASE
                WHEN (ltrim(rtrim((pc.inn)::text)) = ''::text) THEN NULL::text
                ELSE ltrim(rtrim((pc.inn)::text))
            END
            ELSE NULL::text
        END AS contract_inn,
    (ai.house_id)::character varying(6) AS house_id,
    pc.contract_id,
    pc.type AS customer_type,
    COALESCE((aa.group_id)::integer, 1) AS group_id,
    COALESCE(kp.is_kp, 0) AS is_kp
   FROM ((((((((((( SELECT re.account_id,
            re.account_parent_id,
                CASE
                    WHEN (ro.type = ANY (ARRAY[3, 5])) THEN ro.period_end
                    ELSE re.period_id
                END AS period_id,
            ro.period_id AS calc_period,
            re.sublist_id,
            max(
                CASE
                    WHEN (ro.type = 3) THEN abs(COALESCE(re.diff_tarif, (0)::numeric))
                    ELSE
                    CASE
                        WHEN (abs(COALESCE(re.recalc_tarif, (0)::numeric)) = (0)::numeric) THEN abs(COALESCE(re.calc_tarif, (0)::numeric))
                        ELSE abs(COALESCE(re.recalc_tarif, (0)::numeric))
                    END
                END) AS tarif,
            sum(COALESCE(re.diff_volume, (0)::numeric)) AS volume,
            sum(COALESCE(re.diff_result, (0)::numeric)) AS calc
           FROM (recalculation.root ro
             JOIN recalculation.result re ON ((re.root_id = ro.id)))
          GROUP BY re.account_id, re.account_parent_id,
                CASE
                    WHEN (ro.type = ANY (ARRAY[3, 5])) THEN ro.period_end
                    ELSE re.period_id
                END, re.sublist_id, ro.period_id) pb
     JOIN period.list pl ON ((pl.id = pb.period_id)))
     JOIN period.list pll ON ((pll.id = pb.calc_period)))
     JOIN adress.info ai ON ((ai.account_id = pb.account_id)))
     JOIN house.info hi ON ((hi.house_id = ai.house_id)))
     JOIN organization.list ol ON ((ol.id = ai.work_id)))
     JOIN utility.sublist us ON ((us.id = pb.sublist_id)))
     JOIN utility.unit uu ON ((uu.id = us.unit_id)))
     JOIN adress.account aa ON ((aa.id = ai.account_id)))
     LEFT JOIN ( SELECT cg.group_id,
            max(COALESCE((su.is_kp)::integer, 0)) AS is_kp
           FROM (utility.contragent_group_sublist cg
             JOIN utility.sublist su ON ((su.id = cg.sublist_id)))
          GROUP BY cg.group_id) kp ON ((kp.group_id = aa.group_id)))
     LEFT JOIN LATERAL ( SELECT cl.inn,
            c.id AS contract_id,
            cl.surname,
            cl.name,
            cl.middlename,
            cl.type,
            cl.full_name,
            ca.id AS person_id
           FROM ((((contragent.account ca
             JOIN adress.account aa_1 ON ((aa_1.id = ca.account_id)))
             JOIN contragent.owner_documents od ON ((od.contragent_account_id = ca.id)))
             JOIN contragent.list cl ON ((cl.id = ca.contragent_id)))
             LEFT JOIN LATERAL ( SELECT cc.id
                   FROM (contragent.contract cc
                     JOIN contragent.contract_account ac ON ((ac.contract_id = cc.id)))
                  WHERE ((ac.account_id = ca.account_id) AND (cc.date_end IS NULL))) c ON (true))
          WHERE ((ca.is_responsible = true) AND (od.date_end IS NULL) AND (ca.account_id = ai.account_parent_id))
          ORDER BY cl.id
         LIMIT 1) pc ON (true))
  WHERE (pb.calc <> 0.0);
ALTER MATERIALIZED VIEW payment.calc_for_1c_v2 OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating gis.house_characteristic...';END$$;
CREATE MATERIALIZED VIEW gis.house_characteristic (settlement_name, short_adress, unique_number, fias_house_guid, cadastral_number, oktmo, year_of_construction, year_begin, floor_count_max, floor_underground_count, living_count_flat, non_residential_count_flat, area, living_area, non_residential_area, common_propery_water, common_propery_el, lift, podezd) AS SELECT hi.settlement_name,
    hi.short_adress,
    hc.unique_number,
    hc.fias_house_guid,
    hc.cadastral_number,
    hc.oktmo,
    hc.year_of_construction,
    hc.year_begin,
    hc.floor_count_max,
    hc.floor_underground_count,
    hc.living_count_flat,
    hc.non_residential_count_flat,
    hc.area,
    hc.living_area,
    hc.non_residential_area,
    hc.common_propery_water,
    hc.common_propery_el,
    hl.lift,
    ha.podezd
   FROM (((house.characteristic hc
     JOIN house.info hi ON ((hi.house_id = hc.house_id)))
     LEFT JOIN ( SELECT hll.house_id,
            count(hll.house_id) AS lift
           FROM house.lift hll
          GROUP BY hll.house_id) hl ON ((hl.house_id = hc.house_id)))
     LEFT JOIN ( SELECT haa.house_id,
            count(haa.house_id) AS podezd
           FROM house.access haa
          GROUP BY haa.house_id) ha ON ((ha.house_id = hc.house_id)))
  WHERE (hc.is_export = true);
ALTER MATERIALIZED VIEW gis.house_characteristic OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating gis.flat_info...';END$$;
CREATE MATERIALIZED VIEW gis.flat_info (house_id, house_type, fias, fias_house_guid, flat_id, city, street, house, access_number, flat_type, number, cadaster_flat_name, area, gross_area, cadastral_number, unique_number, state, error_text) AS SELECT ai.house_id,
    hc.house_type,
    hc.fias,
    hc.fias_house_guid,
    ai.flat_id,
    ai.city,
    ai.street_name AS street,
        CASE
            WHEN ((hi.korpus IS NULL) OR ((hi.korpus)::text = '0'::text)) THEN (hi.number)::text
            ELSE (((hi.number)::text || ' '::text) || (hi.korpus)::text)
        END AS house,
    hf.access_number,
    ai.flat_book_short_name AS flat_type,
    ai.flat_name AS number,
    hf.cadaster_flat_name,
    hf.area,
    hf.gross_area,
    hf.cadastral_number,
    hf.unique_number,
        CASE
            WHEN ((hf.unique_number IS NULL) AND (ge.error_text IS NULL)) THEN 0
            WHEN ((hf.unique_number IS NOT NULL) AND (ge.error_text IS NULL)) THEN 1
            WHEN ((hf.unique_number IS NOT NULL) AND (ge.error_text IS NOT NULL)) THEN 2
            WHEN ((hf.unique_number IS NULL) AND (ge.error_text IS NOT NULL)) THEN 2
            ELSE NULL::integer
        END AS state,
    ge.error_text
   FROM ((((((( SELECT account.flat_id,
            account.parent_id,
            min(account.id) AS account_id
           FROM adress.account
          GROUP BY account.flat_id, account.parent_id
         HAVING (account.parent_id IS NULL)) aa
     JOIN adress.info ai ON ((aa.account_id = ai.account_id)))
     JOIN house.info hi ON ((ai.house_id = hi.house_id)))
     JOIN house.flat hf ON ((ai.flat_id = hf.flat_id)))
     JOIN house.characteristic hc ON ((ai.house_id = hc.house_id)))
     LEFT JOIN ( SELECT account.flat_id
           FROM house.account
          WHERE (account.close_date IS NULL)
          GROUP BY account.flat_id) ha ON ((ha.flat_id = ai.flat_id)))
     LEFT JOIN gis.entity_queue ge ON (((ge.entity_id = ai.house_id) AND (lower((ge.type_name)::text) = 'flat'::text) AND (ge.id = ( SELECT max(ge2.id) AS max
           FROM gis.entity_queue ge2
          WHERE (((ge2.type_name)::text = 'flat'::text) AND (ge2.entity_id = ai.house_id)))))))
  WHERE ((ai.account_parent_id IS NULL) AND (hc.is_export = true) AND (ha.flat_id IS NOT NULL));
ALTER MATERIALIZED VIEW gis.flat_info OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating tests.payment_without_service_id(jsonb)...';END$$;
CREATE FUNCTION tests.payment_without_service_id(IN _batch jsonb)
RETURNS TABLE(account_name character varying, adress text)
LANGUAGE sql
AS $_$

	select 
		a.account_name,
		i.street || ',' || i.house || ',' || i.flat_type || i."number" as adress
	from payment.list pl 
		inner join payment.batch pb on pl.batch_id = pb.id
		inner join house.account a on a.account_id = pl.account_id
		inner join gis.flat_info i on i.flat_id = a.flat_id
		inner join "period".list l on l.id = pl.period_id
		inner join jsonb_populate_recordset(null::payment.batch_list, _batch) b on b.batch_id = pb.id
	where 
		a.service_id is null
		and pl.guid is null
		and pl.status = 0
		and pl.sum > 0
		and pb.sum > 0;

$_$;
ALTER FUNCTION tests.payment_without_service_id(IN _batch jsonb) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating tests.payment_without_service_id(jsonb)...';END$$;
COMMENT ON FUNCTION tests.payment_without_service_id(jsonb) IS '=============================================
 Author:	Ильющенко Денис
 Create date: 16.05.2018
 Description:	Тест перед выгрузкой платежей по кассе, проверка не размещенных л/с
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating gis.address_info...';END$$;
CREATE MATERIALIZED VIEW gis.address_info (house_id, house_type, settlement_name, short_adress, fias_house_guid, unique_number, is_upload, modification_date, is_export, error_text, order_id) AS SELECT hi.house_id,
    hc.house_type,
    hi.settlement_name,
    hi.short_adress,
    hc.fias_house_guid,
    hc.unique_number,
    hc.is_upload,
    hc.modification_date,
    hc.is_export,
    r.error_text,
    hi.order_id
   FROM ((house.info hi
     LEFT JOIN house.characteristic hc ON ((hi.house_id = hc.house_id)))
     LEFT JOIN LATERAL ( SELECT ge.error_text
           FROM gis.entity_queue ge
          WHERE ((ge.entity_id = hi.house_id) AND (lower((ge.type_name)::text) = 'house'::text) AND (ge.message_id = ( SELECT max(ge2.message_id) AS max
                   FROM gis.entity_queue ge2
                  WHERE ((lower((ge2.type_name)::text) = 'house'::text) AND (ge2.entity_id = hi.house_id)))))) r ON (true));
ALTER MATERIALIZED VIEW gis.address_info OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating gis.contracts...';END$$;
CREATE MATERIALIZED VIEW gis.contracts (id, house_id, fias_house_guid, guid, doc_type, type_name, date_begin, date_end, description, status, short_adress, number) AS SELECT dc.id,
    hc.house_id,
    hi.fias_house_guid,
    dc.contract_guid AS guid,
    1 AS doc_type,
    'Договор управления'::text AS type_name,
    dc.date_begin,
    dc.date_end,
    gb.description,
    dc.contract_status AS status,
    hi.short_adress,
    dc.number
   FROM (((documents.contract dc
     JOIN gis.book gb ON ((gb.id = dc.contract_base_id)))
     LEFT JOIN documents.contracts_houses hc ON ((hc.contract_id = dc.id)))
     LEFT JOIN gis.address_info hi ON ((hi.house_id = hc.house_id)))
UNION
 SELECT dc.id,
    hc.house_id,
    hi.fias_house_guid,
    dc.guid,
    0 AS doc_type,
    'Устав'::text AS type_name,
    dc.date_begin,
    dc.date_end,
    dc.reason AS description,
    dc.status,
    hi.short_adress,
    NULL::character varying AS number
   FROM ((documents.charter dc
     LEFT JOIN documents.charters_houses hc ON ((hc.charter_id = dc.id)))
     LEFT JOIN gis.address_info hi ON ((hi.house_id = hc.house_id)))
UNION
 SELECT dc.id,
    hc.house_id,
    hi.fias_house_guid,
    dc.guid,
    2 AS doc_type,
    'ДРСО'::text AS type_name,
    dc.date_begin,
    dc.date_end,
    ''::text AS description,
    dc.status,
    hi.short_adress,
    dc.number
   FROM ((documents.supply_contract dc
     LEFT JOIN documents.supply_contract_houses hc ON ((hc.contract_id = dc.id)))
     LEFT JOIN gis.address_info hi ON ((hi.house_id = hc.house_id)));
ALTER MATERIALIZED VIEW gis.contracts OWNER TO postgres;


