DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating gis.account_info...';END$$;
CREATE MATERIALIZED VIEW gis.account_info (order_id, account_id, flat_id, house_id, house_type, city, street, house, flat_type, flat_name, account_name, total_square, unique_number, close_date, state, error_text, is_special_kp) AS SELECT ai.order_id,
    ai.account_id,
    ai.flat_id,
    hi.house_id,
    hc.house_type,
    ai.city,
    ai.street_name AS street,
        CASE
            WHEN ((hi.korpus IS NULL) OR ((hi.korpus)::text = '0'::text)) THEN (hi.number)::text
            ELSE (((hi.number)::text || ' '::text) || (hi.korpus)::text)
        END AS house,
    ai.flat_book_short_name AS flat_type,
    COALESCE(hf.cadaster_flat_name, ai.flat_name) AS flat_name,
    ai.account_name,
    ha.total_square,
    ha.unique_number,
    ha.close_date,
        CASE
            WHEN ((ha.unique_number IS NULL) AND (ge.error_text IS NULL)) THEN 0
            WHEN ((ha.unique_number IS NOT NULL) AND (ge.error_text IS NULL)) THEN 1
            WHEN ((ha.unique_number IS NOT NULL) AND (ge.error_text IS NOT NULL)) THEN 2
            WHEN ((ha.unique_number IS NULL) AND (ge.error_text IS NOT NULL)) THEN 2
            ELSE NULL::integer
        END AS state,
    ge.error_text,
    ha.is_special_kp
   FROM (((((adress.info ai
     JOIN house.info hi ON ((ai.house_id = hi.house_id)))
     JOIN house.flat hf ON ((hf.flat_id = ai.flat_id)))
     JOIN house.account ha ON ((ai.account_id = ha.account_id)))
     JOIN house.characteristic hc ON ((ai.house_id = hc.house_id)))
     LEFT JOIN gis.entity_queue ge ON (((ge.entity_id = ai.account_id) AND (lower((ge.type_name)::text) = 'account'::text) AND (ge.id = ( SELECT max(ge2.id) AS max
           FROM gis.entity_queue ge2
          WHERE ((lower((ge2.type_name)::text) = 'account'::text) AND (ge2.entity_id = ai.account_id)))))))
  WHERE (hc.is_export = true);
ALTER MATERIALIZED VIEW gis.account_info OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating adress.info_1c_v2...';END$$;
CREATE MATERIALIZED VIEW adress.info_1c_v2 (account_name, organization_inn, organization_kpp, district_name, district_id, adress, house_id, flat_type, flat_number, full_name, customer_type, customer_inn, contract_inn, contract_id) AS SELECT ai.account_name,
    ol.inn AS organization_inn,
    ol.kpp AS organization_kpp,
    ai.district_name,
    ('МО-'::text || ((hi.district_id)::character varying(10))::text) AS district_id,
    ai.short_name AS adress,
    ('Д-'::text || ((ai.house_id)::character varying(5))::text) AS house_id,
    ai.flat_book_short_name AS flat_type,
    ai.flat_name AS flat_number,
        CASE
            WHEN ((pc.person_id IS NULL) OR (pc.surname IS NULL)) THEN ('Собственник ЛС '::text || (ai.account_name)::text)
            ELSE ltrim(rtrim((pc.full_name)::text))
        END AS full_name,
    pc.type AS customer_type,
        CASE
            WHEN (ltrim(rtrim((pc.inn)::text)) = ''::text) THEN NULL::text
            ELSE ltrim(rtrim((pc.inn)::text))
        END AS customer_inn,
        CASE
            WHEN (pc.contract_id IS NOT NULL) THEN
            CASE
                WHEN (ltrim(rtrim((pc.inn)::text)) = ''::text) THEN NULL::text
                ELSE ltrim(rtrim((pc.inn)::text))
            END
            ELSE NULL::text
        END AS contract_inn,
    pc.contract_id
   FROM (((adress.info ai
     JOIN house.info hi ON ((hi.house_id = ai.house_id)))
     JOIN organization.list ol ON ((ol.id = ai.organization_id)))
     LEFT JOIN LATERAL ( SELECT cl.inn,
            c.id AS contract_id,
            cl.surname,
            cl.name,
            cl.middlename,
            cl.type,
            cl.full_name,
            ca.id AS person_id
           FROM ((((contragent.account ca
             JOIN adress.account aa ON ((aa.id = ca.account_id)))
             JOIN contragent.owner_documents od ON ((od.contragent_account_id = ca.id)))
             JOIN contragent.list cl ON ((cl.id = ca.contragent_id)))
             LEFT JOIN LATERAL ( SELECT cc.id
                   FROM (contragent.contract cc
                     JOIN contragent.contract_account ac ON ((ac.contract_id = cc.id)))
                  WHERE ((ac.account_id = ca.account_id) AND (cc.date_end IS NULL))) c ON (true))
          WHERE ((ca.is_responsible = true) AND (od.date_end IS NULL) AND (ca.account_id = ai.account_id))
          ORDER BY cl.id
         LIMIT 1) pc ON (true))
  WHERE (ai.account_parent_id IS NULL)
UNION
 SELECT ai.account_name,
    ol.inn AS organization_inn,
    ol.kpp AS organization_kpp,
    ai.district_name,
    ('МО-'::text || ((hi.district_id)::character varying(10))::text) AS district_id,
    ai.short_name AS adress,
    ('Д-'::text || ((ai.house_id)::character varying(5))::text) AS house_id,
    ai.flat_book_short_name AS flat_type,
    ai.flat_name AS flat_number,
        CASE
            WHEN ((pc.person_id IS NULL) OR (pc.surname IS NULL)) THEN ('Собственник ЛС '::text || (ai.account_name)::text)
            ELSE ltrim(rtrim((pc.full_name)::text))
        END AS full_name,
    pc.type AS customer_type,
        CASE
            WHEN (ltrim(rtrim((pc.inn)::text)) = ''::text) THEN NULL::text
            ELSE ltrim(rtrim((pc.inn)::text))
        END AS customer_inn,
        CASE
            WHEN (pc.contract_id IS NOT NULL) THEN
            CASE
                WHEN (ltrim(rtrim((pc.inn)::text)) = ''::text) THEN NULL::text
                ELSE ltrim(rtrim((pc.inn)::text))
            END
            ELSE NULL::text
        END AS contract_inn,
    pc.contract_id
   FROM (((adress.info ai
     JOIN house.info hi ON ((hi.house_id = ai.house_id)))
     JOIN organization.list ol ON ((ol.id = ai.work_id)))
     LEFT JOIN LATERAL ( SELECT cl.inn,
            c.id AS contract_id,
            cl.surname,
            cl.name,
            cl.middlename,
            cl.type,
            cl.full_name,
            ca.id AS person_id
           FROM ((((contragent.account ca
             JOIN adress.account aa ON ((aa.id = ca.account_id)))
             JOIN contragent.owner_documents od ON ((od.contragent_account_id = ca.id)))
             JOIN contragent.list cl ON ((cl.id = ca.contragent_id)))
             LEFT JOIN LATERAL ( SELECT cc.id
                   FROM (contragent.contract cc
                     JOIN contragent.contract_account ac ON ((ac.contract_id = cc.id)))
                  WHERE ((ac.account_id = ca.account_id) AND (cc.date_end IS NULL))) c ON (true))
          WHERE ((ca.is_responsible = true) AND (od.date_end IS NULL) AND (ca.account_id = ai.account_id))
          ORDER BY cl.id) pc ON (true))
  WHERE (ai.account_parent_id IS NULL);
ALTER MATERIALIZED VIEW adress.info_1c_v2 OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating tests.check_fill_house_characteristics(jsonb)...';END$$;
CREATE FUNCTION tests.check_fill_house_characteristics(IN _account jsonb)
RETURNS TABLE(adress text)
LANGUAGE plpgsql
AS $_$
begin

	return query
	with recursive cte as 
	(
		select 
			ph.*, 
			pl.parent_id, 
			case 
				when ph.value is null 
				then true 
				else false 
			end as is_error
		from parametr.list pl
			inner join parametr.house ph on ph.parametr_id = pl.id
		where is_characteristic = true 
			and pl.parent_id is null 
			and ph.date_end is null
	union all
		select 
			ph.*, 
			c.id, 
			case 
				when coalesce(c.value, '0') = '0' 
				then false 
				else 
					case  
						when ph.value is null 
						then true 
						else false 
					end 
			end
		from parametr.list pl
			inner join parametr.house ph on ph.parametr_id = pl.id
			inner join cte c on c.parametr_id = pl.parent_id and c.house_id = ph.house_id
		where is_characteristic = true 
			and pl.parent_id is not null 
			and ph.date_end is null
	)
	
	select settlement_name || ' ' || short_adress as adress
	from house.info hi
	join (
			select distinct ct.house_id
			from cte ct
			where ct.is_error = true
		) c on c.house_id = hi.house_id
	where not exists(select ac.account_id from jsonb_populate_recordset(null::account.list, _account) ac ) 
		or hi.house_id in (
								select a.account_id
								from adress.account aa
									join jsonb_populate_recordset(null::account.list, _account) a on aa.id = a.account_id
							)
	order by hi.order_id;

end;
$_$;
ALTER FUNCTION tests.check_fill_house_characteristics(IN _account jsonb) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating tests.check_fill_house_characteristics(jsonb)...';END$$;
