 Create date:		20.09.2017
 Modified date:	10.12.2020, Трофимов Б.И. - добавил фильтр по лс для автоматического запуска тестов
 Description:		Проверка на корректное заполнение характеристик дома
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating test_gis.missing_house_paramertr(integer)...';END$$;
CREATE FUNCTION test_gis.missing_house_paramertr(IN _house_id integer)
RETURNS TABLE(object_id integer, location text, "Не указан статус дома" boolean, "Не указана временная зона" boolean, "Не указан ОКТМО" boolean, "Не указан тип управления МКД" boolean, "Не указана общая площадь здания" boolean, "Не указан год ввода в эксплуатацию" boolean, "Не указано кол-во этажей" boolean, "Отсутствует ФИАС" boolean, "Не указан год постройки" boolean)
LANGUAGE plpgsql
AS $_$
declare 
	_access_count int; 
begin
	
	_access_count = (select count(*) from house.access ha where ha.house_id = _house_id);

	return query
	select 
		 hi.house_id as object_id
		,hi.short_adress as "location"
		,case when status_id is null then true else false end
		,case when time_zone_id is null then true else false end
		,case when oktmo is null then true else false end
		,case when house_management_type is null then true else false end
		,case when coalesce(area,0.0) = 0.0  then true else false end
		,case when coalesce(year_begin,0) = 0 then true else false end
		,case when floor_count_max > 0 then false else true end
		,case when fias_house_guid is not null then false else true end
		,case when year_begin is not null then false else true end
	from house.info hi 
		left join house.characteristic hc on hc.house_id = hi.house_id
	where hc.house_id = _house_id and is_export = true;

end;
$_$;
