DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating utility.view_sublist_for_1cv3...';END$$;
CREATE MATERIALIZED VIEW utility.view_sublist_for_1cv3 (id, name, type_name, type_id, is_kp, unit_name, okei, is_vat_applies, vat_type) AS SELECT us.id,
    us.name,
    ut.name AS type_name,
    ut.id AS type_id,
    COALESCE(us.is_kp, false) AS is_kp,
    uu.name AS unit_name,
    uu.code AS okei,
    COALESCE(sv.is_vat_applies, false) AS is_vat_applies,
    COALESCE(us.vat_type, 32) AS vat_type
   FROM (((utility.sublist us
     JOIN utility.unit uu ON ((uu.id = us.unit_id)))
     JOIN utility.type ut ON ((ut.id = us.type)))
     LEFT JOIN utility.sublist_vat sv ON (((sv.sublist_id = us.id) AND (sv.end_period_id IS NULL))));
ALTER MATERIALIZED VIEW utility.view_sublist_for_1cv3 OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating utility.view_sublist_1c...';END$$;
CREATE MATERIALIZED VIEW utility.view_sublist_1c (sublist_id, sublist_name, type_id, type_name, is_kp, unit_name, okei) AS SELECT us.id AS sublist_id,
    us.name AS sublist_name,
    ut.id AS type_id,
    ut.name AS type_name,
    COALESCE(us.is_kp, false) AS is_kp,
    uu.name AS unit_name,
    uu.code AS okei
   FROM ((utility.sublist us
     JOIN utility.unit uu ON ((uu.id = us.unit_id)))
     JOIN utility.type ut ON ((ut.id = us.type)));
ALTER MATERIALIZED VIEW utility.view_sublist_1c OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating utility.sublist_vat_1c...';END$$;
CREATE MATERIALIZED VIEW utility.sublist_vat_1c (sublist_id, period_id, is_vat_applies, vat_type, organization_id) AS SELECT us.id AS sublist_id,
    pl.id AS period_id,
    COALESCE(
        CASE
            WHEN ((us.id = 6) AND (COALESCE(ot.vat_type, 32) <> 32)) THEN true
            ELSE sv.is_vat_applies
        END, false) AS is_vat_applies,
    COALESCE(
        CASE
            WHEN (COALESCE(
            CASE
                WHEN ((us.id = 6) AND (COALESCE(ot.vat_type, 32) <> 32)) THEN true
                ELSE sv.is_vat_applies
            END, false) = true) THEN ot.vat_type
            ELSE us.vat_type
        END, 32) AS vat_type,
    ot.organization_id
   FROM ((((utility.sublist us
     JOIN period.list pl ON ((pl.is_open = true)))
     JOIN period.list pw ON ((pw.is_working = true)))
     LEFT JOIN utility.sublist_vat sv ON (((us.id = sv.sublist_id) AND ((pl.id >= sv.start_period_id) AND (pl.id <= COALESCE(sv.end_period_id, pw.id))))))
     LEFT JOIN organization.tax ot ON (((pl.id >= ot.period_start_id) AND (pl.id <= COALESCE(ot.period_end_id, pw.id)))));
ALTER MATERIALIZED VIEW utility.sublist_vat_1c OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating utility.active_sublist_for_1cv3...';END$$;
CREATE MATERIALIZED VIEW utility.active_sublist_for_1cv3 (house_id, id, name, type_name, type_id, is_kp, unit_name, okei, is_vat_applies, vat_type) AS SELECT ('Д-'::text || ((pp.house_id)::character varying(6))::text) AS house_id,
    us.id,
    us.name,
    ut.name AS type_name,
    ut.id AS type_id,
    COALESCE(us.is_kp, false) AS is_kp,
    uu.name AS unit_name,
    uu.code AS okei,
    COALESCE(sv.is_vat_applies, false) AS is_vat_applies,
    COALESCE(us.vat_type, 32) AS vat_type
   FROM ((((utility.sublist us
     JOIN utility.unit uu ON ((uu.id = us.unit_id)))
     JOIN utility.type ut ON ((ut.id = us.type)))
     JOIN ( SELECT pb.house_id,
            pb.sublist_id,
            max(pb.period_id) AS period_id
           FROM (payment.balance pb
             JOIN period.list pl ON (((pl.is_working = true) AND ((pb.period_id >= (pl.id - 1)) AND (pb.period_id <= pl.id)))))
          WHERE ((pb.in_balance <> (0)::numeric) OR (pb.current_calculate <> (0)::numeric) OR (pb.recalculate <> (0)::numeric) OR (pb.pay <> (0)::numeric) OR (pb.volume <> (0)::numeric))
          GROUP BY pb.house_id, pb.sublist_id) pp ON ((us.id = pp.sublist_id)))
     LEFT JOIN utility.sublist_vat sv ON (((sv.sublist_id = us.id) AND ((pp.period_id >= sv.start_period_id) AND (pp.period_id <= COALESCE(sv.end_period_id, pp.period_id))))));
ALTER MATERIALIZED VIEW utility.active_sublist_for_1cv3 OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating payment.pay_for_1cv3...';END$$;
CREATE MATERIALIZED VIEW payment.pay_for_1cv3 (organization_inn, organization_kpp, batch_date, batch_id, account_name, district_name, payment_date, batch_from_name, bank_id, rs, sublist_name, sublist_id, sublist_type, detail_sum, detail_period, detail_period_sum, rs_type, payment_id, per_pay, payment_comiss, contract_inn, district_id, house_id, contract_id, customer_type, payment_type, adjustment_type, check_type, cashless_payment, group_id, is_kp, number_pp, date_pp, vat_type, is_vat_applies) AS SELECT oll.inn AS organization_inn,
    oll.kpp AS organization_kpp,
    pb.date AS batch_date,
    pb.id AS batch_id,
    ai.account_name,
    ai.district_name,
    pl.date AS payment_date,
    b.name AS batch_from_name,
    pb.bank_id,
    oc.rs,
    us.name AS sublist_name,
    us.id AS sublist_id,
    us.type AS sublist_type,
    pd.sum AS detail_sum,
    COALESCE(dp.detail_period, pd.period_id) AS detail_period,
    COALESCE(dp.detail_period_sum, pd.sum) AS detail_period_sum,
        CASE
            WHEN ((oc.rs)::text = '00000000000000000000'::text) THEN 1
            ELSE 0
        END AS rs_type,
    pl.id AS payment_id,
    pr.date_end AS per_pay,
    COALESCE(br.fee, (0)::numeric) AS payment_comiss,
        CASE
            WHEN (pc.contract_id IS NOT NULL) THEN
            CASE
                WHEN (TRIM(BOTH FROM pc.inn) = ''::text) THEN NULL::text
                ELSE TRIM(BOTH FROM pc.inn)
            END
            ELSE NULL::text
        END AS contract_inn,
    ('МО-'::text || ((hi.district_id)::character varying(10))::text) AS district_id,
    ('Д-'::text || ((ai.house_id)::character varying(5))::text) AS house_id,
    pc.contract_id,
    pc.type AS customer_type,
    pl.type_id AS payment_type,
        CASE
            WHEN ((b.number)::integer = 19) THEN 1
            WHEN ((b.number)::integer = 5) THEN 2
            WHEN ((b.number)::integer = 99) THEN 3
            ELSE 0
        END AS adjustment_type,
    pl.check_type,
    pl.cashless_payment,
    COALESCE(kp.group_id, 1) AS group_id,
    COALESCE(kp.is_kp, false) AS is_kp,
    pp.number_pp,
    pp.date_pp,
        CASE
            WHEN (COALESCE(v.is_vat_applies, false) = true) THEN COALESCE(us.vat_type, 32)
            ELSE 32
        END AS vat_type,
    COALESCE(v.is_vat_applies, false) AS is_vat_applies
   FROM ((((((((((((((((payment.batch pb
     JOIN payment.list pl ON ((pl.batch_id = pb.id)))
     JOIN payment.detal pd ON ((pd.payment_id = pl.id)))
     LEFT JOIN period.list pr ON ((pr.id = pl.payment_period_id)))
     JOIN adress.info ai ON ((ai.account_id = pl.account_id)))
     JOIN house.info hi ON ((hi.house_id = ai.house_id)))
     JOIN organization.list ol ON ((ol.id = ai.organization_id)))
     JOIN organization.counting oc ON ((oc.id = pb.counting_id)))
     JOIN utility.sublist us ON ((us.id = pd.sublist_id)))
     JOIN parametr.book b ON ((b.id = pb.bank_id)))
     JOIN organization.list oll ON ((oll.id = oc.list_id)))
     LEFT JOIN bank.registry_payment br ON ((br.payment_id = pl.id)))
     LEFT JOIN LATERAL ( SELECT cl.inn,
            c.id AS contract_id,
            cl.surname,
            cl.name,
            cl.middlename,
            cl.type,
            cl.full_name,
            ca.id AS person_id
           FROM ((((contragent.account ca
             JOIN adress.account aa ON ((aa.id = ca.account_id)))
             JOIN contragent.owner_documents od ON ((od.contragent_account_id = ca.id)))
             JOIN contragent.list cl ON ((cl.id = ca.contragent_id)))
             LEFT JOIN LATERAL ( SELECT cc.id
                   FROM (contragent.contract cc
                     JOIN contragent.contract_account ac ON ((ac.contract_id = cc.id)))
                  WHERE ((ac.account_id = ca.account_id) AND (cc.date_end IS NULL))) c ON (true))
          WHERE ((ca.is_responsible = true) AND (od.date_end IS NULL) AND (ca.account_id = ai.account_id))
          ORDER BY cl.id
         LIMIT 1) pc ON (true))
     LEFT JOIN ( SELECT aa.id AS account_id,
            cgs.group_id,
            (max(COALESCE((us_1.is_kp)::integer, 0)))::boolean AS is_kp
           FROM ((utility.contragent_group_sublist cgs
             JOIN utility.sublist us_1 ON (((us_1.id = cgs.sublist_id) AND (cgs.date_end IS NULL))))
             JOIN adress.account aa ON ((aa.group_id = cgs.group_id)))
          GROUP BY aa.id, cgs.group_id) kp ON ((kp.account_id = pd.account_id)))
     LEFT JOIN ( SELECT be.batch_id,
            de.number AS number_pp,
            (de.date)::date AS date_pp
           FROM (bank.bank_exchange_to_batch be
             JOIN bank.document_exchange de ON ((be.bank_exchange_document_id = de.id)))) pp ON ((pp.batch_id = pb.id)))
     LEFT JOIN ( SELECT sv.sublist_id,
            pl_1.id AS period_id,
            sv.is_vat_applies
           FROM ((utility.sublist_vat sv
             JOIN period.list w ON ((w.is_working = true)))
             JOIN period.list pl_1 ON (((pl_1.id >= sv.start_period_id) AND (pl_1.id <= COALESCE(sv.end_period_id, w.id)))))) v ON (((v.sublist_id = us.id) AND (v.period_id = pd.period_id))))
     LEFT JOIN ( SELECT cbd.payment_id,
            dhd.account_id,
            dhd.source_sublist_id AS sublist_id,
            cd.period_id AS detail_period,
            sum((- dhd.sum)) AS detail_period_sum
           FROM (((payment.document_history dh
             JOIN payment.document_history_detail dhd ON ((dhd.history_id = dh.id)))
             JOIN payment.document cd ON ((cd.id = dh.closed_document_id)))
             JOIN payment.document cbd ON ((cbd.id = dh.closed_by_document_id)))
          GROUP BY cbd.payment_id, dhd.account_id, dhd.source_sublist_id, cd.period_id
        UNION
         SELECT dd.payment_id,
            dd.account_id,
            dd.sublist_id,
            dd.period_id AS detail_period,
            (dd.sum - sum((- dhd.sum))) AS detail_period_sum
           FROM ((((payment.document_history dh
             JOIN payment.document_history_detail dhd ON ((dhd.history_id = dh.id)))
             JOIN payment.document cd ON ((cd.id = dh.closed_document_id)))
             JOIN payment.document cbd ON ((cbd.id = dh.closed_by_document_id)))
             JOIN payment.detal dd ON (((dd.payment_id = cbd.payment_id) AND (dd.account_id = dhd.account_id) AND (dd.sublist_id = dhd.source_sublist_id))))
          GROUP BY dd.payment_id, dd.account_id, dd.sublist_id, dd.period_id, dd.sum
         HAVING ((dd.sum - sum((- dhd.sum))) <> 0.0)) dp ON (((dp.payment_id = pd.payment_id) AND (dp.account_id = pd.account_id) AND (dp.sublist_id = pd.sublist_id))));
ALTER MATERIALIZED VIEW payment.pay_for_1cv3 OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating payment.fine_for_1c...';END$$;
CREATE MATERIALIZED VIEW payment.fine_for_1c (organization_inn, organization_kpp, account_id, fine_begin, fine_end, period_begin, period_end, debt, fine, count_day, account_name, district_name, district_id, contract_inn, house_id, contract_id) AS SELECT ol.inn AS organization_inn,
    ol.kpp AS organization_kpp,
    fc.account_id,
    fc.date_begin AS fine_begin,
    fc.date_end AS fine_end,
    pl.date_begin AS period_begin,
    pl.date_end AS period_end,
        CASE
            WHEN (fc.date_end = pl.date_end) THEN ((fc.sum_for_fine31 + fc.sum_for_fine60) + fc.sum_for_fine91)
            ELSE (0)::numeric
        END AS debt,
    fc.fine,
    fc.count_day,
    ai.account_name,
    ai.district_name,
    ('МО-'::text || ((hi.district_id)::character varying(10))::text) AS district_id,
        CASE
            WHEN (pc.person_id IS NOT NULL) THEN
            CASE
                WHEN (TRIM(BOTH FROM pc.inn) = ''::text) THEN NULL::text
                ELSE TRIM(BOTH FROM pc.inn)
            END
            ELSE NULL::text
        END AS contract_inn,
    ('Д-'::text || ((ai.house_id)::character varying(6))::text) AS house_id,
    pc.contract_id
   FROM (((((fine.calculation fc
     JOIN adress.info ai ON ((ai.account_id = fc.account_id)))
     JOIN house.info hi ON ((hi.house_id = ai.house_id)))
     JOIN organization.list ol ON ((ol.id = ai.work_id)))
     JOIN period.list pl ON ((pl.id = fc.period_id)))
     LEFT JOIN LATERAL ( SELECT cl.inn,
            c.id AS contract_id,
            cl.surname,
            cl.name,
            cl.middlename,
            cl.type,
            cl.full_name,
            ca.id AS person_id
           FROM ((((contragent.account ca
             JOIN adress.account aa ON ((aa.id = ca.account_id)))
             JOIN contragent.owner_documents od ON ((od.contragent_account_id = ca.id)))
             JOIN contragent.list cl ON ((cl.id = ca.contragent_id)))
             LEFT JOIN LATERAL ( SELECT cc.id
                   FROM (contragent.contract cc
                     JOIN contragent.contract_account ac ON ((ac.contract_id = cc.id)))
                  WHERE ((ac.account_id = ca.account_id) AND (cc.date_end IS NULL))) c ON (true))
          WHERE ((ca.is_responsible = true) AND (od.date_end IS NULL) AND (ca.account_id = ai.account_parent_id))
          ORDER BY cl.id
         LIMIT 1) pc ON (true))
  WHERE (fc.fine <> (0)::numeric);
ALTER MATERIALIZED VIEW payment.fine_for_1c OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating payment.calc_for_1c_v3...';END$$;
CREATE MATERIALIZED VIEW payment.calc_for_1c_v3 (organization_inn, organization_kpp, date_end, date_calc, account_name, district_name, district_id, utility_name, sublist_id, calc, type_calc, tarif, volume, unit_name, okei, contract_inn, house_id, contract_id, customer_type, group_id, is_kp, vat_type, is_vat_applies) AS SELECT ol.inn AS organization_inn,
    ol.kpp AS organization_kpp,
    pl.date_end,
    pl.date_end AS date_calc,
    ai.account_name,
    ai.district_name,
    ('МО-'::text || ((hi.district_id)::character varying(10))::text) AS district_id,
    us.name AS utility_name,
    us.id AS sublist_id,
    pb.current_calculate AS calc,
    0 AS type_calc,
    COALESCE(pb.tarif, (0)::numeric) AS tarif,
    COALESCE(pb.volume, (0)::numeric) AS volume,
    uu.name AS unit_name,
    uu.code AS okei,
        CASE
            WHEN (pc.person_id IS NOT NULL) THEN
            CASE
                WHEN (TRIM(BOTH FROM pc.inn) = ''::text) THEN NULL::text
                ELSE TRIM(BOTH FROM pc.inn)
            END
            ELSE NULL::text
        END AS contract_inn,
    ('Д-'::text || ((ai.house_id)::character varying(6))::text) AS house_id,
    pc.contract_id,
    pc.type AS customer_type,
    COALESCE((aa.group_id)::integer, 1) AS group_id,
    COALESCE(kp.is_kp, false) AS is_kp,
    COALESCE(us.vat_type, 32) AS vat_type,
    COALESCE(v.is_vat_applies, false) AS is_vat_applies
   FROM ((((((((((payment.balance pb
     JOIN period.list pl ON ((pl.id = pb.period_id)))
     JOIN adress.info ai ON ((ai.account_id = pb.account_id)))
     JOIN house.info hi ON ((hi.house_id = ai.house_id)))
     JOIN organization.list ol ON ((ol.id = ai.work_id)))
     JOIN utility.sublist us ON ((us.id = pb.sublist_id)))
     JOIN utility.unit uu ON ((uu.id = us.unit_id)))
     JOIN adress.account aa ON ((aa.id = ai.account_id)))
     LEFT JOIN ( SELECT cg.group_id,
            (max(COALESCE((su.is_kp)::integer, 0)))::boolean AS is_kp
           FROM (utility.contragent_group_sublist cg
             JOIN utility.sublist su ON ((su.id = cg.sublist_id)))
          GROUP BY cg.group_id) kp ON ((kp.group_id = aa.group_id)))
     LEFT JOIN ( SELECT sv.sublist_id,
            pl_1.id AS period_id,
            sv.is_vat_applies
           FROM ((utility.sublist_vat sv
             JOIN period.list w ON ((w.is_working = true)))
             JOIN period.list pl_1 ON (((pl_1.id >= sv.start_period_id) AND (pl_1.id <= COALESCE(sv.end_period_id, w.id)))))) v ON (((v.sublist_id = us.id) AND (v.period_id = pb.period_id))))
     LEFT JOIN LATERAL ( SELECT cl.inn,
            c.id AS contract_id,
            cl.surname,
            cl.name,
            cl.middlename,
            cl.type,
            cl.full_name,
            ca.id AS person_id
           FROM ((((contragent.account ca
             JOIN adress.account aa_1 ON ((aa_1.id = ca.account_id)))
             JOIN contragent.owner_documents od ON ((od.contragent_account_id = ca.id)))
             JOIN contragent.list cl ON ((cl.id = ca.contragent_id)))
             LEFT JOIN LATERAL ( SELECT cc.id
                   FROM (contragent.contract cc
                     JOIN contragent.contract_account ac ON ((ac.contract_id = cc.id)))
                  WHERE ((ac.account_id = ca.account_id) AND (cc.date_end IS NULL))) c ON (true))
          WHERE ((ca.is_responsible = true) AND (od.date_end IS NULL) AND (ca.account_id = ai.account_parent_id))
          ORDER BY cl.id
         LIMIT 1) pc ON (true))
  WHERE (pb.current_calculate <> (0)::numeric)
UNION ALL
 SELECT ol.inn AS organization_inn,
    ol.kpp AS organization_kpp,
    pl.date_end,
    pll.date_end AS date_calc,
    ai.account_name,
    ai.district_name,
    ('МО-'::text || ((hi.district_id)::character varying(10))::text) AS district_id,
    us.name AS utility_name,
    us.id AS sublist_id,
    pb.calc,
        CASE
            WHEN ((pl.date_end = pll.date_end) AND (COALESCE(pb.tarif, (0)::numeric) <> (0)::numeric)) THEN 0
            ELSE 1
        END AS type_calc,
    COALESCE(pb.tarif, (0)::numeric) AS tarif,
    COALESCE(pb.volume, (0)::numeric) AS volume,
    uu.name AS unit_name,
    uu.code AS okei,
        CASE
            WHEN (pc.person_id IS NOT NULL) THEN
            CASE
                WHEN (TRIM(BOTH FROM pc.inn) = ''::text) THEN NULL::text
                ELSE TRIM(BOTH FROM pc.inn)
            END
            ELSE NULL::text
        END AS contract_inn,
    ('Д-'::text || ((ai.house_id)::character varying(6))::text) AS house_id,
    pc.contract_id,
    pc.type AS customer_type,
    COALESCE((aa.group_id)::integer, 1) AS group_id,
    COALESCE(kp.is_kp, false) AS is_kp,
    COALESCE(us.vat_type, 32) AS vat_type,
    COALESCE(v.is_vat_applies, false) AS is_vat_applies
   FROM (((((((((((( SELECT re.account_id,
            re.account_parent_id,
                CASE
                    WHEN (ro.type = ANY (ARRAY[3, 5])) THEN ro.period_end
                    ELSE re.period_id
                END AS period_id,
            ro.period_id AS calc_period,
            re.sublist_id,
            max(
                CASE
                    WHEN (ro.type = 3) THEN abs(COALESCE(re.diff_tarif, (0)::numeric))
                    ELSE
                    CASE
                        WHEN (abs(COALESCE(re.recalc_tarif, (0)::numeric)) = (0)::numeric) THEN abs(COALESCE(re.calc_tarif, (0)::numeric))
                        ELSE abs(COALESCE(re.recalc_tarif, (0)::numeric))
                    END
                END) AS tarif,
            sum(COALESCE(re.diff_volume, (0)::numeric)) AS volume,
            sum(COALESCE(re.diff_result, (0)::numeric)) AS calc
           FROM (recalculation.root ro
             JOIN recalculation.result re ON ((re.root_id = ro.id)))
          GROUP BY re.account_id, re.account_parent_id,
                CASE
                    WHEN (ro.type = ANY (ARRAY[3, 5])) THEN ro.period_end
                    ELSE re.period_id
                END, re.sublist_id, ro.period_id) pb
     JOIN period.list pl ON ((pl.id = pb.period_id)))
     JOIN period.list pll ON ((pll.id = pb.calc_period)))
     JOIN adress.info ai ON ((ai.account_id = pb.account_id)))
     JOIN house.info hi ON ((hi.house_id = ai.house_id)))
     JOIN organization.list ol ON ((ol.id = ai.work_id)))
     JOIN utility.sublist us ON ((us.id = pb.sublist_id)))
     JOIN utility.unit uu ON ((uu.id = us.unit_id)))
     JOIN adress.account aa ON ((aa.id = ai.account_id)))
     LEFT JOIN ( SELECT cg.group_id,
            (max(COALESCE((su.is_kp)::integer, 0)))::boolean AS is_kp
           FROM (utility.contragent_group_sublist cg
             JOIN utility.sublist su ON ((su.id = cg.sublist_id)))
          GROUP BY cg.group_id) kp ON ((kp.group_id = aa.group_id)))
     LEFT JOIN ( SELECT sv.sublist_id,
            pl_1.id AS period_id,
            sv.is_vat_applies
           FROM ((utility.sublist_vat sv
             JOIN period.list w ON ((w.is_working = true)))
             JOIN period.list pl_1 ON (((pl_1.id >= sv.start_period_id) AND (pl_1.id <= COALESCE(sv.end_period_id, w.id)))))) v ON (((v.sublist_id = us.id) AND (v.period_id = pb.period_id))))
     LEFT JOIN LATERAL ( SELECT cl.inn,
            c.id AS contract_id,
            cl.surname,
            cl.name,
            cl.middlename,
            cl.type,
            cl.full_name,
            ca.id AS person_id
           FROM ((((contragent.account ca
             JOIN adress.account aa_1 ON ((aa_1.id = ca.account_id)))
             JOIN contragent.owner_documents od ON ((od.contragent_account_id = ca.id)))
             JOIN contragent.list cl ON ((cl.id = ca.contragent_id)))
             LEFT JOIN LATERAL ( SELECT cc.id
                   FROM (contragent.contract cc
                     JOIN contragent.contract_account ac ON ((ac.contract_id = cc.id)))
                  WHERE ((ac.account_id = ca.account_id) AND (cc.date_end IS NULL))) c ON (true))
          WHERE ((ca.is_responsible = true) AND (od.date_end IS NULL) AND (ca.account_id = ai.account_parent_id))
          ORDER BY cl.id
         LIMIT 1) pc ON (true))
  WHERE (pb.calc <> 0.0);
ALTER MATERIALIZED VIEW payment.calc_for_1c_v3 OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating organization.info_for_1c...';END$$;
CREATE MATERIALIZED VIEW organization.info_for_1c (house_id, organization_inn, organization_kpp, tax_type, vat_type, date_begin, date_end) AS SELECT DISTINCT ai.house_id,
    ol.inn AS organization_inn,
    ol.kpp AS organization_kpp,
    COALESCE((ot.tax_type)::integer, 0) AS tax_type,
    COALESCE(ot.vat_type, 32) AS vat_type,
    COALESCE(pls.date_begin, pl.date_begin) AS date_begin,
    COALESCE(ple.date_end, '3999-12-31'::date) AS date_end
   FROM (((((adress.info ai
     JOIN organization.list ol ON ((ol.id = ai.work_id)))
     JOIN period.list pl ON ((pl.is_active = true)))
     LEFT JOIN organization.tax ot ON (((ot.organization_id = ol.id) AND (ot.period_end_id IS NULL))))
     LEFT JOIN period.list pls ON ((pls.id = ot.period_start_id)))
     LEFT JOIN period.list ple ON ((ple.id = ot.period_end_id)));
ALTER MATERIALIZED VIEW organization.info_for_1c OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating adress.info_1c_v3...';END$$;
CREATE MATERIALIZED VIEW adress.info_1c_v3 (account_name, work_id, recipient_id, district_name, district_id, adress, house_id, flat_type, flat_number) AS SELECT ai.account_name,
    ai.work_id,
    ai.organization_id AS recipient_id,
    ai.district_name,
    ('МО-'::text || hi.district_id) AS district_id,
    ai.short_name AS adress,
    ('Д-'::text || ai.house_id) AS house_id,
    ai.flat_book_short_name AS flat_type,
    ai.flat_name AS flat_number
   FROM (adress.info ai
     JOIN house.info hi ON ((hi.house_id = ai.house_id)))
  WHERE (ai.account_parent_id IS NULL);
ALTER MATERIALIZED VIEW adress.info_1c_v3 OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating utility.active_sublist_1c(integer)...';END$$;
CREATE FUNCTION utility.active_sublist_1c(IN _period_id integer)
RETURNS TABLE(period_id integer, house_id character varying, sublist_id integer)
LANGUAGE plpgsql
AS $_$
begin
	
	return query
	select 
		_period_id as period_id,
		('Д-' || pb.house_id)::varchar(10) as house_id,
		pb.sublist_id
	from payment.balance pb
	where (pb.in_balance != 0 or pb.current_calculate != 0 or pb.recalculate != 0 or pb.pay != 0 or pb.volume != 0)
		and pb.period_id between _period_id-1 and _period_id
	group by pb.house_id, pb.sublist_id;

end;
$_$;
ALTER FUNCTION utility.active_sublist_1c(IN _period_id integer) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating utility.active_sublist_1c(integer)...';END$$;
COMMENT ON FUNCTION utility.active_sublist_1c(integer) IS '=============================================
 Author:		Юркин Е.Ю
 Create date: 18.04.2025
