DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating report.planned_work(integer)...';END$$;
CREATE FUNCTION report.planned_work(IN _year_plan_id integer)
RETURNS TABLE(house_id integer, work_name text, main_parent text, middle_parent text, law_parent text, m1 integer, m2 integer, m3 integer, m4 integer, m5 integer, m6 integer, m7 integer, m8 integer, m9 integer, m10 integer, m11 integer, m12 integer)
LANGUAGE plpgsql
AS $_$
declare 
	_sql 				text = '';
	_year 				int;
	_period_id 			int;
	_start_period_id	int; 
	_period_end_id 		int; 
	_year_start 		int;
begin

	_year = (select work_year from eco.year_plan where id = _year_plan_id);

	select period_id, period_end_id 
	into _start_period_id, _period_end_id
	from eco.year_plan 
	where id = _year_plan_id;

	_year_start = (
					select  pl1."year"
					from period.list pl1
						inner join "period".list pl2 on pl1."year" = pl2."year"
					where pl1.id = _start_period_id and pl2.id = _period_end_id
				);

	if _year_start > 0
		then
			begin
				_period_id = (select id from "period".list where "year" = _year_start and month_id = 1);
			end;
		else
			_period_id = _start_period_id;
	end if;

	_sql = '
	with parent as   
	(
		select 
			aw.id as approved_work_id, 
			yp.house_id, 
			null::text as main_parent, 
			null::text as middle_parent, 
			null::text as law_parent, 
			ow.id as id, 
			0 as num,
			ow.parent_id
		from eco.organization_work ow
			inner join eco.approved_work aw on ow.id = aw.organization_work_id
			inner join eco.year_plan yp on aw.year_plan_id = yp.id
		where (not exists(select 1 from eco.organization_work eo2 where eo2.parent_id = ow.id) or ow.parent_id is not null)
			and yp.work_year = ' || _year || ' 
		and yp.id = ' || _year_plan_id || '

		union all  

		select  
			p.approved_work_id, 
			p.house_id, 
			cast (eo2.name as text) as main_parent, 
			p.main_parent as middle_parent, 
			p.middle_parent as law_parent, 
			p.id, 
			p.num + 1 
			,eo2.parent_id
		from  eco.organization_work eo2 
		 inner join parent as p
			on eo2.id = p.parent_id
	)  

	select 
		house_id
		,ow.name as work_name
		, p.main_parent
		, p.middle_parent 
		, p.law_parent';

	_sql = _sql || 	( 
						select string_agg(d,' ')
						from (
								select '
								,max(case when pw.month = ' || month_id || ' then pw.freq end) as "m' || row_number() over(order by id) || '"' as d
								from period.list 
								where id between _period_id and _period_id + 11
							) as f
					);

	_sql = _sql || '
	from eco.planned_work pw 
		inner join parent p on  p.approved_work_id = pw.approved_work_id
		inner join (select p.id, max(p.num) as num  from parent p group by p.id ) pp on pp.num = p.num and pp.id = p.id
		inner join eco.organization_work ow on ow.id = p.id
	group by house_id
		,ow.name 
		,ow.parent_id 
		,p.main_parent 
		,p.middle_parent 
		,p.law_parent';

	if _sql is not null and _sql<>''
		then
			return query
			execute (_sql);
	end if;
end;
$_$;
ALTER FUNCTION report.planned_work(IN _year_plan_id integer) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating report.planned_work(integer)...';END$$;
