 Description:	<Description,,>
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating report.nds_for_1с(integer, jsonb, jsonb)...';END$$;
CREATE FUNCTION report.nds_for_1с(IN _period_id integer, IN _house jsonb, IN _sublist jsonb)
RETURNS TABLE("Период" character varying, "№" integer, "Адрес" text, "Контрагент" text, "Л/счет" character varying, "Периоды" character varying, "Пени нач." numeric, "Пени пересчет" numeric, "Пени оплата" numeric, "Пени корр.оплата" numeric, "Начисления без НДС" numeric, "Перерасчеты без НДС" numeric, "Начисления с НДС" numeric, "Перерасчеты с НДС" numeric, "Платежи без НДС" numeric, "Платежи аванса" numeric, "Платежи с НДС" numeric, "Корр.платежи без НДС" numeric, "Корр.платежи аванса" numeric, "Корр.платежи с НДС" numeric)
LANGUAGE plpgsql
AS $_$
declare 
	_date_end 	date; 
	_date_begin date; 
	_period 	varchar(20);
begin
	
	select date_begin, date_end, name_month || ' ' || cast(year as char(4)) 
	into _date_begin, _date_end, _period
	from period.list 
	where id = _period_id;

	drop table if exists _vat;	
	
	create temp table _vat 
	(
		vat_type int, 
		vat_name varchar(30), 
		nominator numeric(4,1), 
		denominator numeric(4,1)
	);
	
	insert into _vat 
	values 
		(1, 'НДС 20%', 20.0, 100.0),
		(2, 'НДС 10%', 10.0, 100.0),
		(4, 'НДС расч. 20/120', 20.0, 120.0),
		(8, 'НДС расч. 10/110', 10.0, 110.0),
		(16, 'НДС 0%', 0.0, 100.0),	
		(32, 'Без НДС', null, 0.0),
		(64, 'ставка НДС 5', 5.0, 100.0),
		(128, 'ставка НДС 7', 7.0, 100.0),
		(256, 'ставка НДС расч. 5/105', 5.0, 105.0),
		(512, 'НДС расч. 7/107', 7.0, 107.0);

	drop table if exists _owner_1с;
	
	create temp table _owner_1с 
	(
		period_id int, 
		work_id int, 
		house_id int, 
		account_parent_id int, 
		account_id int, 
		account_name varchar(15), 
		full_name varchar(200), 
		customer_type bool
	);
	
	insert into _owner_1с
		select 
			_period_id as period_id
			,ai.work_id
			,ai.house_id
			,ai.account_parent_id
			,ai.account_id
			,ai.account_name
			,case when pc.account_id is null or nullif(pc.surname, '') is null then 'Собственник ЛС ' || ai.account_name else trim(pc.short_name) end as full_name
			,pc.customer_type
		from adress.info ai  
			inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = ai.house_id
			left join
			(select row_number () over (partition by aa.name order by coalesce(is_responsible,false ) desc, cl.type, cl.id) as rn
				,cl.surname
				,cl.type as customer_type
				,cl.short_name
				,ca.account_id
			from contragent.account ca
			inner join adress.account aa on aa.id = ca.account_id
			inner join contragent.owner_documents od on od.contragent_account_id = ca.id
			inner join contragent.list cl on cl.id = ca.contragent_id
			where od.date_begin <= _date_begin and coalesce(od.date_end, _date_end) >= _date_end
		) pc on pc.account_id = ai.account_parent_id and pc.rn = 1;

	drop table if exists _calc_1c;
	
	create temp table _calc_1c 
	(
		period_id int, 
		account_id int, 
		sublist_id int, 
		calc numeric(15,2)
	);
	
	insert into _calc_1c
	select 
		_period_id as period_id
		,pb.account_id
		,pb.sublist_id
		,pb.current_calculate as calc
	from payment.balance pb
		inner join adress.account aa on aa.id = pb.account_id
		inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = aa.house_id
		inner join jsonb_populate_recordset(null::report.sublist, _sublist) s on s.sublist_id = pb.sublist_id
		where pb.period_id = _period_id 
		and pb.current_calculate != 0;

	drop table if exists _recalc_1c;
	
	create temp table _recalc_1c 
	(
		period_id int, 
		account_id int, 
		recalc_period_id int, 
		sublist_id int, 
		recalc_tarif numeric(15,2), 
		diff_result numeric(15,2)
	);
	
	insert into _recalc_1c
	select 
		_period_id as period_id,
		re.account_id, 
		pl.id as recalc_period_id,
		re.sublist_id, 
		max(coalesce(re.diff_tarif, re.recalc_tarif,0)) as recalc_tarif,
		sum(coalesce(re.diff_result, 0)) as diff_result
	from recalculation.root ro
		inner join recalculation.result re on re.root_id = ro.id
		inner join adress.account aa on aa.id = re.account_id
		inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = aa.house_id
		inner join jsonb_populate_recordset(null::report.sublist, _sublist) s on s.sublist_id = re.sublist_id
		inner join "period".list pl on re.date_end between pl.date_begin and pl.date_end
	where ro.period_id = _period_id
	group by re.account_id, ro.period_id, pl.id, re.sublist_id
	having sum(coalesce(re.diff_result,0)) != 0;

	drop table if exists _pay_1c;
	
	create temp table _pay_1c 
	(
		period_id int, 
		account_id int, 
		sublist_id int, 
		detail_sum numeric(15,2), 
		detail_period_id int, 
		detail_period_sum numeric(15,2), 
		adjustment_type int, 
		check_type int
	);
	
	insert into _pay_1c
	select
		_period_id as period_id,
		pd.account_id,
		pd.sublist_id,
		pd.sum as detail_sum,
		coalesce(dp.detail_period,pd.period_id) as detail_period_id,
		coalesce(dp.detail_period_sum,pd.sum) as detail_period_sum,
		case
			when b.number::int = 19 then 1	--корректировка
			when b.number::int = 5 then 2	--корректировка авансов
			when b.number::int = 99 then 3	--корректировка (без выгрузки 1с)
			else 0
		end as adjustment_type,
		pl.check_type
	from payment.batch pb 
		inner join payment.list pl on pl.batch_id = pb.id
		inner join payment.detal pd on pd.payment_id = pl.id 
		inner join parametr.book b on b.id = pb.bank_id 
		inner join adress.account aa on aa.id = pl.account_id
		inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = aa.house_id
		inner join jsonb_populate_recordset(null::report.sublist, _sublist) s on s.sublist_id = pd.sublist_id
		left join 
				(select cbd.payment_id, dhd.account_id, dhd.source_sublist_id as sublist_id, cd.period_id as detail_period, sum(-dhd.sum) as detail_period_sum
					from payment.document_history dh
					inner join payment.document_history_detail dhd on dhd.history_id = dh.id
					inner join payment.document cd on cd.id = dh.closed_document_id
					inner join payment.document cbd on cbd.id = dh.closed_by_document_id
				group by cbd.payment_id, dhd.account_id, dhd.source_sublist_id, cd.period_id
				union 
				select dd.payment_id, dd.account_id, dd.sublist_id, dd.period_id as detail_period, dd.sum - sum(-dhd.sum) as detail_period_sum
					from payment.document_history dh
					inner join payment.document_history_detail dhd on dhd.history_id = dh.id
					inner join payment.document cd on cd.id = dh.closed_document_id
					inner join payment.document cbd on cbd.id = dh.closed_by_document_id
					inner join payment.detal dd on dd.payment_id = cbd.payment_id and dd.account_id = dhd.account_id and dd.sublist_id = dhd.source_sublist_id
				group by dd.payment_id, dd.account_id, dd.sublist_id, dd.period_id, dd.sum
				having dd.sum - sum(-dhd.sum) <> 0.0
				) dp on dp.payment_id = pd.payment_id and dp.account_id = pd.account_id and dp.sublist_id = pd.sublist_id
		where pb.date between _date_begin and _date_end 
				and b.number::int != 99;

	drop table if exists _table_1c;
	
	create temp table _table_1c 
	(
		account_id int, 
		period_id int, 
		sublist_id int, 
		peny_calc numeric(15,2), 
		peny_recalc numeric(15,2), 
		peny_pay numeric(15,2), 
		peny_pay_korr numeric(15,2), 
		calc numeric(15,2), 
		recalc numeric(15,2), 
		pay numeric(15,2), 
		pay_avance numeric(15,2), 
		pay_avance_korr numeric(15,2), 
		pay_korr numeric(15,2)
	);

	insert into _table_1c
	select 
		account_id,
		c.period_id,
		c.sublist_id,
		case when c.sublist_id = 7 then calc else 0.0 end as peny_calc,
		0.0 as peny_recalc,
		0.0 as peny_pay,
		0.0 as peny_pay_korr,
		case when c.sublist_id = 7 then 0.0 else calc end as calc,
		0.0 as recalc,
		0.0 as pay,
		0.0 as pay_avance,
		0.0 as pay_avance_korr,
		0.0 as pay_korr
	from _calc_1c c
		union all
	select 
		account_id, 
		recalc_period_id,
		r.sublist_id,
		0.0 as peny_calc,
		case when r.sublist_id = 7 then diff_result else 0.0 end as peny_recalc,
		0.0 as peny_pay,
		0.0 as peny_pay_korr,
		case when r.sublist_id != 7 and recalc_tarif != 0 and recalc_period_id = _period_id then diff_result else 0.0 end as calc,
		case when r.sublist_id != 7 and (recalc_tarif = 0 or recalc_period_id != _period_id) then diff_result else 0.0 end as recalc,
		0.0 as pay,
		0.0 as pay_avance,
		0.0 as pay_avance_korr,
		0.0 as pay_korr
	from _recalc_1c r
		union all
	select 
		account_id, 
		case when p.sublist_id = 7 then p.period_id else p.detail_period_id end as detail_period_id,
		p.sublist_id,
		0.0 as peny_calc,
		0.0 as peny_recalc,
		case when p.check_type != 3 and p.sublist_id = 7 then p.detail_period_sum else 0.0 end as peny_pay,
		case when p.check_type = 3 and p.sublist_id = 7 then p.detail_period_sum else 0.0 end as peny_pay_korr,
		0.0 as calc,
		0.0 as recalc,
		case when p.check_type != 3 and p.sublist_id not in (6,7) then p.detail_period_sum else 0.0 end as pay,
		case when p.check_type != 3 and p.sublist_id = 6 then p.detail_period_sum else 0.0 end as pay_avance,
		case when p.check_type = 3 and p.sublist_id = 6 then p.detail_period_sum else 0.0 end as pay_avance_korr,
		case when p.check_type = 3 and p.sublist_id not in (6,7) then p.detail_period_sum else 0.0 end as pay_korr
	from _pay_1c p
		where p.adjustment_type != 2;

	return query
	select 
		_period as "период",
		hi.house_id as "№",
		hi.short_adress as "адрес",
		case when o.customer_type = true then 'Юр.лицо: ' || o.full_name else 'Физические лица' end as "контрагент",
		o.account_name as "л/счет", 
		to_char(pl.date_begin, 'yyyy.MM')::varchar(30) as "периоды",
		sum(t.peny_calc) as "пени нач.",
		sum(t.peny_recalc) as "пени пересчет",
		sum(t.peny_pay) as "пени оплата",
		sum(t.peny_pay_korr) as "пени корр.оплата",
		sum(case when sv.is_vat_applies = false then calc else 0.0 end) as "начисления без ндс",
		sum(case when sv.is_vat_applies = false then recalc else 0.0 end) as "перерасчеты без ндс",
		sum(case when sv.is_vat_applies = true then calc else 0.0 end) as "начисления с ндс",
		sum(case when sv.is_vat_applies = true then recalc else 0.0 end) as "перерасчеты с ндс",
		sum(case when sv.is_vat_applies = false then pay else 0.0 end) as "платежи без ндс",
		sum(pay_avance) as "платежи аванса",
		sum(case when sv.is_vat_applies = true then pay else 0.0 end) as "платежи с ндс",
		sum(case when sv.is_vat_applies = false then pay_korr else 0.0 end) as "корр.платежи без ндс",
		sum(pay_avance_korr) as "корр.платежи аванса",
		sum(case when sv.is_vat_applies = true then pay_korr else 0.0 end) as "корр.платежи с ндс"
	from _owner_1с o
		inner join house.info hi on hi.house_id = o.house_id
		inner join _table_1c t on o.account_id = t.account_id
		inner join utility.sublist_vat_1c sv on sv.sublist_id = t.sublist_id and sv.period_id = t.period_id and o.work_id = sv.organization_id
		inner join _vat v on v.vat_type = sv.vat_type
		inner join period.list pl on pl.id = t.period_id
	group by hi.house_id, hi.short_adress, o.customer_type, o.full_name, o.account_parent_id, o.account_name, pl.date_begin;

	drop table if exists _calc_1c;
	drop table if exists _owner_1с;
	drop table if exists _pay_1c;
	drop table if exists _recalc_1c;
	drop table if exists _table_1c;
	drop table if exists _vat;

end;
$_$;
