DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating report.nds_for_1с(integer, jsonb, jsonb)...';END$$;
COMMENT ON FUNCTION report.nds_for_1с(integer, jsonb, jsonb) IS '=============================================
