DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating report.by_pass_list(jsonb)...';END$$;
CREATE FUNCTION report.by_pass_list(IN _house jsonb)
RETURNS TABLE(street_name character varying, adress text, fio character varying, in_balance numeric, cpr smallint, br1 smallint, out_balance numeric, count_month smallint)
LANGUAGE plpgsql
AS $_$
declare
	_period_id 		int;
	_period_begin 	int;
begin

	_period_id = (select id from period.list where is_working = true);
	_period_begin = (select min(id) from period.list where is_open = true); 

	create temp table _table (account_id int, debt numeric(18, 2)); 
	
	insert into _table 
	select pb.account_parent_id, sum(pb.in_balance - pb.pay) as dolg
	from payment.balance_group pb
		inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = pb.house_id
	where pb.period_id = _period_id
	group by pb.account_parent_id;	

	return query
	select 
		 ai.street_name
		,ai.street_book_name || ' ' || ai.street_name || ' ' || ai.house_number || coalesce(' ' || ai.korpus, '') || ' ' || ai.flat_book_name || ' ' || ai.flat_name as adress
		,ppa.fio
		,pb.in_balance as in_balance
		,cp.cpr
		,cp.br1
		,pb.out_balance as out_balance
		,sum(case when cc.debt > 0.0 then 1 else 0 end)::int2 as count_month
		from adress.light_info ai
			inner join calculation.parametr_transporate cp on cp.account_id = ai.account_id
			inner join payment.balance_group pb on pb.account_parent_id = cp.account_id
				and pb.period_id = _period_id
			left join lateral
			(
				select ca.account_id, cl.full_name as fio
				from contragent.list cl 
					inner join contragent.account ca on ca.contragent_id = cl.id
					inner join contragent.owner_documents od on od.contragent_account_id = ca.id
				where ca.account_id = ai.account_id and od.date_end is null and ca.is_responsible = true
				limit 1
			) ppa on true
			left join lateral 
			(
				select 
					c.account_id, 
					c.period_id, 
					c.current_calc, 
					case
       					when t.debt - sum (c.current_calc) over (partition by c.account_id order by c.period_id desc) > 0 then c.current_calc 	
						else 
							case when c.current_calc - (sum (c.current_calc) over (partition by c.account_id order by c.period_id desc) - t.debt) < 0 then 0 
							else c.current_calc -(sum (c.current_calc) over (partition by c.account_id order by c.period_id desc) - t.debt) 
						end 
					end as debt, 
					t.debt as full_debt
  				from (
						select pb.account_parent_id as account_id, pb.period_id, sum(pb.in_balance) as in_balance, sum(pb.current_calc) as current_calc, sum(pb.recalc) as recalc, sum(pb.pay) as pay, sum(pb.in_balance + pb.current_calc + pb.recalc - pb.pay) as out_balance 
						from payment.balance_group pb   
						where pb.period_id between _period_begin and _period_id
						group by pb.account_parent_id, pb.period_id
					) c
					inner join _table t on t.account_id = c.account_id
 				where t.debt > 0.0 and ai.account_id = c.account_id
			) cc on true    	
	where ai.house_id in (select house_id from jsonb_populate_recordset(null::house.list, _house) h)
	group by ai.order_id, ai.street_name, ai.street_book_name, ai.street_name, ai.house_number, ai.korpus, ai.flat_book_name, ai.flat_name, ppa.fio, cp.cpr, cp.br1, flat_book_id, account_name, ai.account_order_id
		,pb.in_balance, pb.out_balance
	order by ai.order_id, ai.account_order_id;

	drop table if exists _table;

end;
$_$;
ALTER FUNCTION report.by_pass_list(IN _house jsonb) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating report.by_pass_list(jsonb)...';END$$;
COMMENT ON FUNCTION report.by_pass_list(jsonb) IS '=============================================
