 Description:	Обходной лист для Крымска (мусор)
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating report.batch_payment(date, date, jsonb, jsonb, jsonb, smallint)...';END$$;
CREATE FUNCTION report.batch_payment(IN _date_begin date, IN _date_end date, IN _house jsonb, IN _counting_list jsonb, IN _sublist jsonb, IN _is_detail smallint DEFAULT 0)
RETURNS TABLE(adress text, account_name text, owners text, batch_date date, number_batch integer, sublist_id integer, sublist_name character varying, bank_name character varying, payment_sum numeric, order_id integer, house_id integer, group_name character varying)
LANGUAGE plpgsql
AS $_$
declare 
	_sql 				text = '';
	_inn 				varchar(12);
	_organization_name 	varchar(150);
begin


	if (_is_detail in (0, 1, 2, 3, 4))
		then
			begin

				 _sql = (select '
									select distinct
										' || case when _is_detail = 2 or _is_detail = 3 then 'hi.short_adress ' else '''''' end || ' as adress,
										' || case when _is_detail = 1 or _is_detail = 4 then 'al.account_name,' else ''''' as account_name,' end
										  || case when _is_detail = 4 then '
											(select string_agg(cl.full_name,'', '') as full_name
											 from contragent.list cl
													inner join contragent.account ca on ca.contragent_id = cl.id
													inner join contragent.owner_documents od on ca.id = od.contragent_account_id
												where ca.account_id = al.account_id and od.date_end is null and ca.is_responsible = true
											) as owners, ' else '
										'''' as owners,' end || '
										pb.date as batch_date,
										' || case when _is_detail != 2 then 'pb.number as number_batch,' else 'null::int as number_batch,' end || '
										us.id as sublist_id,
										us.name as sublist_name,
										' || case when _is_detail != 2 then 'pbk.name as bank_name,' else ''''' as bank_name,' end ||'
										sum(pd.sum) as payment_sum,
										al.order_id,
										al.house_id,
										coalesce(uc.name, ''Услуги'') as group_name
									from adress.light_info al 
										inner join house.info hi on hi.house_id = al.house_id
										inner join jsonb_populate_recordset(null::house.list,''' || _house || ''') h on h.house_id = al.house_id
										inner join payment.list pl on pl.account_id = al.account_id
										inner join payment.batch pb on pb.id = pl.batch_id
										inner join jsonb_populate_recordset(null::special.objects,''' || _counting_list || ''')  c on c.object_id = pb.counting_id
										inner join parametr.book pbk on pbk.id = pb.bank_id
										inner join payment.detal pd on pd.payment_id = pl.id
										left join adress.account aa on aa.id = pd.account_id
										left join utility.contragent_group uc on uc.id = aa.group_id
										inner join utility.sublist us on us.id = pd.sublist_id
										inner join jsonb_populate_recordset(null::report.sublist,''' || _sublist || ''')  s on s.sublist_id = us.id
									where pb.date between ''' || _date_begin || ''' and ''' ||_date_end || ''' and pd.sum <> 0.0
									group by aa.group_id, uc.name, al.house_id, al.order_id,' || 
										case 
											when _is_detail != 2 then ' pb.id, ' 
											else '' 
										end || 'pb.date, ' || 
										case 
											when _is_detail != 2 then ' pb.number, ' 
											else '' 
											end || 
										case 
											when _is_detail = 1 or _is_detail = 4 then 'al.account_id, al.account_name,'
											when _is_detail = 2 or _is_detail = 3 then 'hi.short_adress,'
											else ''
										end || 'us.id, us.name' ||
										case 
											when _is_detail != 2 then ', pbk.name'
											else ''
										end
							);

				return query
				execute (_sql);

			end;
	end if;

	if (_is_detail = 5) 
		then
			begin

				_inn = (select inn from organization.list where is_owner = true);
		
				return query
				select *
				from (
						select 
							'' as adress,
							'' as account_name,
							'' as owners,			
							pb.date as batch_date,
							pb.number as number_batch,
							pd.sublist_id,
							(us.name || ' ' || coalesce (up.name, 'Поставщик неизвестен'))::varchar(100) as sublist_name,			
							pbk.name as bank_name,
							sum(pd.sum) payment_sum,		
							null::int as order_id,	
							null::int as house_id,	
							coalesce(uc.name, 'Без группы') as group_name				
						from payment.list pl 
							inner join payment.batch pb on pb.id = pl.batch_id
							inner join jsonb_populate_recordset(null::special.objects, _counting_list) c on c.object_id = pb.counting_id
							inner join parametr.book pbk on pbk.id = pb.bank_id
							inner join payment.detal pd on pd.payment_id = pl.id
							left join adress.account aa on aa.id = pd.account_id
							left join utility.contragent_group uc on uc.id = aa.group_id
							inner join adress.light_info al on al.account_id = pd.account_id
							inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = al.house_id
							left join utility.sublist_provider usp on usp.sublist_id = pd.sublist_id
								and usp.house_id = al.house_id
							left join utility.provider up on up.id = usp.provider_id
							inner join utility.sublist us on us.id = pd.sublist_id
							inner join jsonb_populate_recordset(null::report.sublist, _sublist) s on s.sublist_id = us.id
						where pb.date between _date_begin and _date_end
							and pd.sum <> 0.0
							and (usp.date_begin = (
								select max(uspp.date_begin)
								from utility.sublist_provider uspp
								where uspp.sublist_id = pd.sublist_id
									and uspp.house_id = al.house_id) or usp.date_begin is null) 
							and pd.sublist_id <> 6 
							and pd.sublist_id <> 7
						group by pl.batch_id, pb.date, pb.number, pbk.name, us.name || ' ' || coalesce (up.name, 'Поставщик неизвестен'), up.inn, us.name, pd.sublist_id, uc.name, up.name
						union all
						select 									
							'' as adress,
							'' as account_name,
							'' as owners,	
							pb.date as batch_date,
							pb.number as number_batch,
							7 as sublist_id,
							' Пени'::varchar(100) as sublist_name,
							pbk.name as bank_name,
							sum(pd.sum) as payment_sum,
							null::int as order_id,
							null::int as house_id,
							coalesce(uc.name, 'Без группы') group_name
						from payment.list pl 
							inner join payment.batch pb on pb.id = pl.batch_id
							inner join jsonb_populate_recordset(null::special.objects, _counting_list) c on c.object_id = pb.counting_id
							inner join parametr.book pbk on pbk.id = pb.bank_id 
							inner join payment.detal pd on pd.payment_id = pl.id
							left join adress.account aa on aa.id = pd.account_id
							left join utility.contragent_group uc on uc.id = aa.group_id
							inner join adress.light_info al on al.account_id = pl.account_id
							inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = al.house_id
							inner join jsonb_populate_recordset(null::report.sublist, _sublist) s on s.sublist_id = pd.sublist_id
						where pd.sublist_id = 7 and pb.date between _date_begin and _date_end
						group by pl.batch_id, pb.date, pb.number, pbk.name, pd.sublist_id, uc.name					
						union all
						select 
							'' as adress,
							'' as account_name,
							'' as owners,
							pb.date as batch_date,
							pb.number as number_batch,
							6 as sublist_id,
							' Аванс'::varchar(100)  as sublist_name,
							pbk.name as bank_name,
							sum(pd.sum) as payment_sum,
							null::int as order_id,
							null::int as house_id,							
							coalesce(uc.name, 'Без группы') group_name
						from payment.list pl 
							inner join payment.batch pb on pb.id = pl.batch_id
							inner join jsonb_populate_recordset(null::special.objects, _counting_list) c on c.object_id = pb.counting_id
							inner join parametr.book pbk on pbk.id = pb.bank_id
							inner join payment.detal pd on pd.payment_id = pl.id
							left join adress.account aa on aa.id = pd.account_id
							left join utility.contragent_group uc on uc.id = aa.group_id
							inner join adress.light_info al on al.account_id = pl.account_id
							inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = al.house_id
							inner join jsonb_populate_recordset(null::report.sublist, _sublist) s on s.sublist_id = pd.sublist_id
						where pd.sublist_id = 6 and pb.date between _date_begin and _date_end
						group by pl.batch_id, pb.date, pb.number, pbk.name, pd.sublist_id, uc.name
					) as d;
		
			end;
	end if;

	if (_is_detail = 6)
		then
			begin
		
				_organization_name = (
										select up.name
										from utility.provider up
											inner join organization.list ol on ol.inn = up.inn
										where ol.is_owner = true
									);

				return query
				select 
					'' as adress,
					'' as account_name,
					'' as owners,
					pb.date as batch_date,
					pb.number as number_batch,
					null::int as sublist_id,
					coalesce (up.name, case when pd.sublist_id = 6 or pd.sublist_id = 7 then _organization_name else 'Поставщик неизвестен' end) as sublist_name,
					pbk.name as bank_name,
					sum(pd.sum) payment_sum, 
					null::int as order_id,
					null::int as house_id,
					coalesce(uc.name, 'Без группы') as group_name
				from payment.list pl 
					inner join payment.batch pb on pb.id = pl.batch_id
					inner join jsonb_populate_recordset(null::special.objects, _counting_list) c on c.object_id = pb.counting_id
					inner join parametr.book pbk on pbk.id = pb.bank_id
					inner join payment.detal pd on pd.payment_id = pl.id
					left join adress.account aa on aa.id = pd.account_id
					left join utility.contragent_group uc on uc.id = aa.group_id
					inner join adress.light_info al on al.account_id = pl.account_id
					inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = al.house_id
					left join utility.sublist_provider usp on usp.sublist_id = pd.sublist_id and usp.date_end is null
						and usp.house_id = al.house_id
					left join utility.provider up on up.id = usp.provider_id
					inner join jsonb_populate_recordset(null::report.sublist, _sublist) s on s.sublist_id = pd.sublist_id
				where pb.date between _date_begin and _date_end
					and pd.sum <> 0.0
					and (usp.date_begin = (
						select max(uspp.date_begin)
						from utility.sublist_provider uspp
						where uspp.sublist_id = pd.sublist_id
							and uspp.house_id = al.house_id) or usp.date_begin is null) 
				group by pl.batch_id, pb.date, pb.number, pbk.name, up.name, up.inn, pd.sublist_id, uc.name;

			end;
	end if;

end;
$_$;
ALTER FUNCTION report.batch_payment(IN _date_begin date, IN _date_end date, IN _house jsonb, IN _counting_list jsonb, IN _sublist jsonb, IN _is_detail smallint) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating report.batch_payment(date, date, jsonb, jsonb, jsonb, smallint)...';END$$;
