DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering utility.transfer_sublist_tariffs(integer, integer)...';END$$;
CREATE OR REPLACE PROCEDURE utility.transfer_sublist_tariffs(IN _new_group_id integer, IN _period_id integer)
LANGUAGE plpgsql
AS $_$
declare 
	_date_begin 			date;
	_date_end 				date;
	_previous_date_begin 	timestamp;
	_provider_owner_id 		int default null::int;
	err_code 				text;
	msg_text 				text;
	exc_context 			text;
begin
	begin
		--формируется список услуг, по которым есть вх.сальдо или перерасчеты или платежи
		drop table if exists _sublist_have_debt;
		create temp table _sublist_have_debt (sublist_id int, house_id int, territory_id int);

		insert into _sublist_have_debt (house_id, sublist_id, territory_id)
		select pb.house_id, pb.sublist_id, ah.territory_id
		from payment.balance pb
			inner join adress.house ah on ah.id = pb.house_id
		where pb.period_id = _period_id
				and (pb.re_calculate <> 0
					or pb.in_balance <> 0
					or pb.pay <> 0)
				and pb.sublist_id not in (6,7)
		group by pb.house_id, pb.sublist_id, ah.territory_id;

		--формируется список новых поставщиков по группе
		_date_begin = (	
						select date_begin
						from "period".list 
						where id = _period_id
						);

		select date_begin, date_end
		into _previous_date_begin, _date_end
		from "period".list
		where id = _period_id - 1;

		_provider_owner_id = (
								select up.id
								from organization.list ol
									inner join utility.provider up on ol.inn = up.inn
								where ol.is_owner = true
								limit 1
							);

		if (_provider_owner_id is null) 
			then
				_provider_owner_id = (
										select id 
										from utility.provider
										limit 1
									);
		end if;
	
		drop table if exists _sublist_provider_for_insert;
		create temp table _sublist_provider_for_insert (id int, territory_id int, provider_id int, sublist_id int, house_id int, date_begin date, date_end date);

		insert into _sublist_provider_for_insert (id, territory_id, provider_id, sublist_id, house_id, date_begin, date_end)
		select	usp.id
				,coalesce(usp.territory_id, hb.territory_id)
				,coalesce(usp.provider_id, _provider_owner_id)
				,coalesce(usp.sublist_id, hb.sublist_id)
				,coalesce(usp.house_id, hb.house_id)
				,case when usp.sublist_id is null then _previous_date_begin else usp.date_begin end
				,case when usp.sublist_id is null then _previous_date_begin else usp.date_end end
		from utility.sublist_provider usp
			left join utility.contragent_group_sublist ugs on ugs.sublist_provider_id = usp.id
			full join _sublist_have_debt hb on hb.sublist_id = usp.sublist_id and hb.house_id = usp.house_id
		where ugs.id is null
			and (usp.date_end is null or usp.date_end >= _date_begin);

		drop table if exists _sublist_have_debt;

		--использую merge т.к. необходимо было старое и новое значение id для sublist_provider
		drop table if exists _new_sublist_provider;
		create temp table _new_sublist_provider (id int, territory_id int, provider_id int, sublist_id int, house_id int, date_begin date, date_end date, old_id int);

		with cte as 
		(
			insert into utility.sublist_provider as up (sublist_id, provider_id, territory_id, house_id, date_begin, date_end)
			select ui.sublist_id, ui.provider_id, ui.territory_id, ui.house_id,
				case 
					when _date_begin >= ui.date_begin and ui.id is not null 
					then _date_begin 
					else ui.date_begin 
				end as date_begin
				,ui.date_end
			from _sublist_provider_for_insert ui
			returning 
					up.id, 
					up.territory_id, 
					up.provider_id, 
					up.sublist_id, 
					up.house_id, 
					up.date_begin, 
					up.date_end
		)
		insert into _new_sublist_provider
		select ct.*, ui.id
		from cte ct
			inner join _sublist_provider_for_insert ui on 	ui.sublist_id = ct.sublist_id and 
															ui.provider_id = ct.provider_id and 
															ui.territory_id = ct.territory_id and
															ui.house_id = ct.house_id;

		--обновляем дату окончания действия поставщика по услуге
		update utility.sublist_provider as usp
			set date_end = 	case 
								when _date_begin > usp.date_begin 
								then _date_end 
								else usp.date_begin  
							end
		from _sublist_provider_for_insert sp
		where sp.id = usp.id;

		--привязка поставщиков услуг к группе
		insert into utility.contragent_group_sublist (sublist_provider_id, group_id, sublist_id, house_id, date_begin, date_end)
		select us.id, _new_group_id, us.sublist_id, us.house_id,  us.date_begin, us.date_end
		from _new_sublist_provider us;

		--перенос документов
		create temp table _utility_documents_id (object_id int);

		insert into _utility_documents_id
		select ud.id
		from utility.documents ud
			inner join  _new_sublist_provider  sl on sl.old_id = ud.sublist_provider_id
		where ud.period_end is null
			or ud.period_end >= _period_id;

		insert into utility.documents (sublist_provider_id, document_id, period_begin, period_end)
		select sl.id, ud.document_id, ud.period_begin, ud.period_end 
		from _utility_documents_id id
			inner join utility.documents ud on ud.id = id.object_id
			inner join _new_sublist_provider sl on sl.old_id = ud.sublist_provider_id;

		update utility.documents ud
			set period_end = _period_id - 1
		from _utility_documents_id id
		where ud.id= id.object_id;

		--перенос тарифов
		drop table if exists _house_tarif_id;
		create temp table _house_tarif_id (id int);
		
		insert into _house_tarif_id
		select thl.id
		from tarif.list tl
			inner join _new_sublist_provider nsp on nsp.provider_id = tl.provider_id
													and nsp.sublist_id = tl.sublist_id
													and nsp.territory_id = tl.territory_id
			inner join tarif.house_tarif thl on thl.tarif_id = tl.id
		where thl.date_end is null
			or thl.date_end >= _date_begin
			or nsp.old_id is not null;

		insert into tarif.house_tarif (house_id, tarif_id, "number", date_begin, date_end)
		select thl.house_id
			  ,thl.tarif_id
			  ,thl.number
			  ,case when _date_begin >= date_begin then _date_begin else date_begin end
			  ,thl.date_end
		from tarif.house_tarif thl
			 inner join _house_tarif_id  ht on thl.id = ht.id;

		update tarif.house_tarif thl
			set date_end = 	case 
								when _date_begin > thl.date_begin 
								then _date_end  
								else thl.date_begin 
							end 
		from _house_tarif_id  ht
		where thl.id = ht.id;

		drop table if exists _sublist_have_debt;
		drop table if exists _house_tarif_id;
		drop table if exists _new_sublist_provider;
		drop table if exists _sublist_provider_for_insert;
		drop table if exists _utility_documents_id;

		exception 
			when others
				then 
	
					get stacked diagnostics
	    			err_code = returned_sqlstate,
					msg_text = message_text,
	    			exc_context = pg_context;
	
	   				raise notice 'error code: % message text: % context: %', 
	   				err_code, msg_text, exc_context;
	end;
	
end
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating utility.transfer_sublist_tariffs(integer, integer)...';END$$;
COMMENT ON PROCEDURE utility.transfer_sublist_tariffs(integer, integer) IS '=============================================
 Author:	Макарова Е.А.
 Create date: 24.09.2020
 Description:	Процедура для переноса тарифов в группу
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering utility.sublist__house_create(integer, integer, date, date, integer, integer, jsonb, integer, integer)...';END$$;
CREATE OR REPLACE PROCEDURE utility.sublist__house_create(IN _sublist_id integer, IN _provider_id integer, IN _date_begin date, IN _date_end date, IN _document_id integer, IN _group_id integer, IN _house jsonb, IN _period_begin integer DEFAULT NULL::integer, IN _period_end integer DEFAULT NULL::integer)
LANGUAGE plpgsql
AS $_$
declare 
	_message text;
begin

	drop table if exists __house;
	create temp table __house (house_id int not null primary key);

	insert into __house
	select h.house_id 
	from jsonb_populate_recordset(null::house.list, _house) h;

	if exists(
				select * 
				from utility.sublist_provider us
					inner join __house h on h.house_id = us.house_id
				where us.sublist_id = _sublist_id 
					and us.provider_id = _provider_id
					and ((_date_begin between us.date_begin and coalesce(us.date_end, _date_end,'9999-12-31'))
						or (_date_begin < us.date_begin and coalesce(_date_end, '9999-12-31') >= us.date_begin))
			)
		then
			begin
				raise exception 'Невозможно привязать услугу и поставщика к одному или нескольким домам, т.к. у выбранных домов уже существует привязка услуги и поставщика за указанный период';	
				return;
			end;
	end if;

	begin

		drop table if exists __house_territory;
		create temp table __house_territory (house_id int not null primary key, territory_id int);

		insert into __house_territory
		select ah.id, ah.territory_id 
		from adress.house ah
			inner join __house h on h.house_id = ah.id;

		drop table if exists _table;
		create temp table _table (id int not null primary key);

		with cte as 
		(
			insert into utility.sublist_provider(sublist_id, provider_id, territory_id, house_id, date_begin, date_end)
			select _sublist_id, _provider_id, territory_id, house_id, _date_begin, _date_end
			from __house_territory
			where _sublist_id not in (32,34,37)
			returning id
		)
		insert into _table
		select id
		from cte;	
		
		with cte as 
		( 
			insert into utility.sublist_provider(sublist_id, provider_id, territory_id, house_id, date_begin, date_end)
			select _sublist_id + 10, _provider_id, h.territory_id, h.house_id, _date_begin, _date_end
			from __house_territory h
			inner join utility.sublist us on us.id = _sublist_id+10
				left join utility.sublist_provider sp on sp.sublist_id = _sublist_id + 10 
														and sp.provider_id = _provider_id 
														and sp.territory_id = h.territory_id 
														and sp.house_id = h.house_id 
														and sp.date_end is null
			where _sublist_id in (22,24,27) and sp.id is null
			returning id
		)
		insert into _table
		select id
		from cte;	

		with cte as 
		( 
			insert into utility.sublist_provider(sublist_id, provider_id, territory_id, house_id, date_begin, date_end)
			select _sublist_id, _provider_id, h.territory_id, h.house_id, _date_begin, _date_end
			from __house_territory h
			inner join utility.sublist_provider sp on sp.sublist_id = _sublist_id-10 and sp.provider_id = _provider_id and sp.territory_id = h.territory_id and sp.house_id = h.house_id and sp.date_end is null
			where _sublist_id in (32,34,37) 
		returning id
		)
		insert into _table
		select id
		from cte;	

		if (_document_id is not null)
			then
				begin
					insert into utility.documents (sublist_provider_id, document_id, period_begin, period_end)
					select id, _document_id, _period_begin, _period_end 
					from _table;
		
					update utility.documents ud2 
						set	period_end = ud.period_begin - 1 
					from utility.documents ud
						inner join _table t on t.id = ud.sublist_provider_id
					where ud2.period_end is null and ud2.sublist_provider_id = ud.sublist_provider_id and ud2.period_begin < ud.period_begin;
				end;
		end if;

		if (_group_id is not null)
			then
				begin
					insert into utility.contragent_group_sublist(sublist_provider_id, group_id, sublist_id, house_id, date_begin, date_end)
					select us.id, _group_id, us.sublist_id, us.house_id,  us.date_begin, us.date_end
					from _table t
						inner join utility.sublist_provider us on us.id = t.id;
				end;
		end if;

	drop table if exists _table;
	drop table if exists __house_territory;
	drop table if exists __house;

	exception 
	when others
		then
			get stacked diagnostics
				_message = message_text;

			raise notice '%', _message using errcode = '0F000';

		end;

end;
$_$;


