DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering utility.create_sort()...';END$$;
CREATE OR REPLACE FUNCTION utility.create_sort()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
declare 
	_sort smallint;
begin

	_sort = (select  max(sort) from utility.list);
	_sort = _sort + 1;

	if (_sort is null) 
		then 
			_sort = 1;
	end if;
		
	update utility.list 
		set	sort = _sort 
	where id = (select max(ul.id) from utility.list ul);

	return null;

end;
$_$;


