DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering tests.counters_with_not_full_recalc(jsonb)...';END$$;
CREATE OR REPLACE FUNCTION tests.counters_with_not_full_recalc(IN _account jsonb)
RETURNS TABLE(severity character varying, account_name character varying)
LANGUAGE plpgsql
AS $_$
declare 
	_period_id int;
begin

	_period_id = (select pl.id from "period".list pl where pl.is_working = true);

	return query
	select
		'wrn'::varchar(3) as severity,
		aa."name" as account_name
	from counter.flow cf
		inner join counter.account ca on ca.counter_id = cf.counter_id
		inner join adress.account aa on aa.id = ca.account_id
		left join lateral (
							select sum(f.flow) as sum_flow
							from counter.flow f
							where f.counter_id = cf.counter_id 
								and f.period_id >= (select min(cpa.period_id) from calculation.parametr_transporate_arch cpa where cpa.account_id = ca.account_id)
						) fo on true
	where cf.period_id = _period_id 
		and cf.c_value <> 0.0 
		and cf.c_value > fo.sum_flow 
		and (not exists(select ac.account_id from jsonb_populate_recordset(null::account.list, _account) as ac) or ca.account_id in (select a.account_id from jsonb_populate_recordset(null::account.list, _account) a));

end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating tests.counters_with_not_full_recalc(jsonb)...';END$$;
COMMENT ON FUNCTION tests.counters_with_not_full_recalc(jsonb) IS '=============================================
 Author:			Поляков Павел
 Create date:		13.09.2017
 Modified date:	10.12.2020, Трофимов Б.И. - добавил фильтр по лс для автоматического запуска тестов
 Description:		Проверка на возможное не полное распределение корректировочного объема 
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering tests.counters_with_missing_first_value(jsonb)...';END$$;
CREATE OR REPLACE FUNCTION tests.counters_with_missing_first_value(IN _account jsonb)
RETURNS TABLE(severity character varying, account_name character varying)
LANGUAGE sql
AS $_$

	select
		'wrn'::varchar(3) as severity,
		aa."name" as account_name
	from counter.account ca
		inner join counter.list cl on cl.id = ca.counter_id 
		inner join adress.account aa on aa.id = ca.account_id
	where
		not exists (select c.* from counter.flow c where c.counter_id = ca.counter_id and c.flow_type_id = 5)
		and (not exists(select ac.account_id from jsonb_populate_recordset(null::account.list, _account) as ac) or ca.account_id in (select a.account_id from jsonb_populate_recordset(null::account.list, _account) as a))
		and cl.active = true and cl.date_end is null
	group by ca.account_id, aa."name";

$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating tests.counters_with_missing_first_value(jsonb)...';END$$;
COMMENT ON FUNCTION tests.counters_with_missing_first_value(jsonb) IS '=============================================
 Author:			Поляков Павел
 Create date:		13.09.2017
 Modified date:	10.12.2020, Трофимов Б.И. - добавил фильтр по лс для автоматического запуска тестов
 Modified date:	20.01.2021, Юркин Е.Ю. - добавил в выборку только открытые счетчики
 Description:		Проверка на наличие счетчиков без первоначальных показаний
