DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering special.create_parametr(character varying, character varying, character varying)...';END$$;
CREATE OR REPLACE PROCEDURE special.create_parametr(IN _node character varying, IN _parametr_name character varying, IN _default_value character varying)
LANGUAGE plpgsql
AS $_$
declare 
		_xml	xml;
		_sql	text;
begin
	
	_xml = (select xml_data from special.parametr);

	_sql = '
	update special.parametr
	set 
		xml_data =xml(replace(lower(''' || _xml::text || '''),''</' || _node || '>'',	''  <' || _parametr_name || '>' || _default_value || '</' || _parametr_name || '>
  </' || _node || '>''));';
	
	execute(_sql);
end
$_$;


