DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering report.certificate_of_completion_in_range(integer, integer, integer, jsonb, jsonb, jsonb, boolean, integer)...';END$$;
CREATE OR REPLACE FUNCTION report.certificate_of_completion_in_range(IN _period_begin integer, IN _period_end integer, IN _table_type integer, IN _contragent jsonb, IN _house jsonb, IN _contract jsonb, IN _show_full_address boolean DEFAULT false, IN _group_id integer DEFAULT NULL::integer)
RETURNS TABLE(person_id integer, house_id integer, short_name_adress text, utility_name character varying, sublist_name character varying, unit_name character varying, tarif numeric, volume numeric, calc numeric, recalc numeric, sublist_id integer, period_id integer, date_begin text, order_id integer, account_order_id integer, organization_counting_id integer, contract_id integer)
LANGUAGE plpgsql
AS $_$
declare 
	_date_begin date;
	_date_end 	date;
begin

	create temp table _contract_filter (contract_id int, period_id int);
	_date_begin = (select pl.date_begin from "period".list pl where pl.id = _period_begin);
	_date_end = (select pl.date_end from "period".list pl where pl.id = _period_end);

	create temp table _house_filter (house_id int);
	create temp table _accounts (account_id int);

	if exists(select * from jsonb_populate_recordset(null::house.list, _house) h)
		then
			begin
				insert into _house_filter 
				select h.house_id 
				from jsonb_populate_recordset(null::house.list, _house) h;
			end; 
		else 
			begin
				insert into _house_filter
				select al.house_id
				from contragent.account ca
					inner join jsonb_populate_recordset(null::special.objects ,_contragent) c on c.object_id = ca.contragent_id
					inner join adress.light_info al on al.account_id = ca.account_id
				group by al.house_id;				
			end;
	end if;
	
	if exists(select * from jsonb_populate_recordset(null::special.objects ,_contract) c)
		then
			begin
				insert into _accounts
				select distinct cca.account_id 
				from contragent.contract_account cca
					inner join contragent.contract cc on cc.id = cca.contract_id
					inner join jsonb_populate_recordset(null::special.objects, _contract) c on c.object_id = cca.contract_id;
				
				insert into _contract_filter 
				select c.object_id, pl.id
				from jsonb_populate_recordset(null::special.objects, _contract) c
					join contragent.contract cc on cc.id = c.object_id
					join "period".list pl on true
				where ((cc.date_begin between pl.date_begin and pl.date_end) 
					or (cc.date_begin < pl.date_begin and (cc.date_end is null or cc.date_end > pl.date_begin)))
					and pl.id between _period_begin and _period_end;

			end; 
		else
			begin
				insert into _accounts
				select distinct ca.account_id
				from contragent.account ca
					join jsonb_populate_recordset(null::special.objects ,_contragent) c on c.object_id = ca.contragent_id;

				insert into _contract_filter
				select cc.id, pl.id
				from contragent.contract cc
					join jsonb_populate_recordset(null::special.objects, _contragent) c on c.object_id = cc.contragent_id
					join "period.list" pl on true
				where ((cc.date_begin between pl.date_begin and pl.date_end) 
					or (cc.date_begin < pl.date_begin and (cc.date_end is null or cc.date_end > pl.date_begin)))
					and pl.id between _period_begin and _period_end;

			end;
	end if;

	create temp table __sublist (sublist_id int);

	if (_table_type = 0)
		then
			begin 
				insert into __sublist
				select 7;
			end;
	elsif (_table_type = 1)
		then
			begin
				insert into __sublist
				select id 
				from utility.sublist 
				where id != 7;
			end;
	elsif (_table_type not in (0, 1))
		then
			begin
				insert into __sublist
				select id 
				from utility.sublist;		
			end;
	end if;

	return query
	select
		 cl.id as person_id
		,pb.house_id
		,case when _show_full_address = true then ai.short_name_flat else ai.short_name end as short_name_adress
		,ul.name as utility_name
		,us.name as sublist_name
		,uu.name as unit_name
		,pb.tarif
		,coalesce(sum(pb.volume),0) as volume
		,sum(pb.current_calculate) as calc
		,sum(pb.recalculate) as recalc 
		,us.id as sublist_id
		,pl.id as period_id
		,lower(to_char(pl.date_begin, 'tmmonth yyyy')) as date_begin
		,ai.order_id
		,case when _show_full_address = true then ai.account_order_id else 0 end as account_order_id
		,ai.counting_id as organization_counting_id
		,cca.object_id as contract_id
	from contragent.list cl
		inner join jsonb_populate_recordset(null::special.objects ,_contragent) c on c.object_id = cl.id
		inner join contragent.account ca on ca.contragent_id = cl.id
		inner join contragent.owner_documents od on od.contragent_account_id = ca.id
		inner join payment.balance pb on pb.account_parent_id = ca.account_id
		inner join adress.account aa on aa.id = pb.account_id
		inner join __sublist s on s.sublist_id = pb.sublist_id
		inner join _house_filter h on h.house_id = pb.house_id
		inner join adress.info ai on ai.account_id = ca.account_id
		left join (
					select cc.contract_id as object_id, cca.account_id, cc.period_id
					from contragent.contract_account cca 
						inner join _contract_filter cc on cc.contract_id = cca.contract_id
				  )cca on cca.account_id = aa.parent_id and cca.period_id = pb.period_id
		inner join utility.sublist us on us.id = pb.sublist_id
		inner join utility.list ul on ul.id = us.list_id
		inner join utility.unit uu on uu.id = us.unit_id
		inner join "period".list pl on pl.id = pb.period_id
		inner join _accounts a on a.account_id = ca.account_id
	where cl."type" = true 
	and pb.period_id between _period_begin and _period_end 
	and od.date_end is null 
	and pb.print = 1
	and coalesce(aa.group_id, 0) = coalesce(_group_id, 0) 
	group by 
		cl.id, 
		pb.house_id, 
		ai.order_id,
		case when _show_full_address = true then ai.short_name_flat else ai.short_name end, 
		case when _show_full_address = true then ai.account_order_id else 0 end,
		pb.sublist_id, 
		pb.tarif, 
		ul.name, 
		us.name, 
		uu.name, 
		us.id, 
		pl.date_begin,
		ai.counting_id,
		cca.object_id,
		pl.id;

	drop table if exists _house_filter;
	drop table if exists _accounts;
	drop table if exists __sublist;
	drop table if exists _contract_filter;

end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating report.certificate_of_completion_in_range(integer, integer, integer, jsonb, jsonb, jsonb, boolean, integer)...';END$$;
COMMENT ON FUNCTION report.certificate_of_completion_in_range(integer, integer, integer, jsonb, jsonb, jsonb, boolean, integer) IS '=============================================
 Author:		Глещинский Д.В.
 Create date: 08.06.2016
 Description:	Данные для таблицы акта выполненных работ
 Modyfied date: 01.03.2018
 Modyfied description: Добавлен параметр _Table_Type - 0: формировать только по пени. 1: формировать по всем услугам, кроме пени. 2: формировать по всем услугам
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering report.certificate_of_completion_group(integer, jsonb, jsonb, integer)...';END$$;
CREATE OR REPLACE FUNCTION report.certificate_of_completion_group(IN _period_id integer, IN _contragent jsonb, IN _house jsonb, IN _group_id integer DEFAULT NULL::integer)
RETURNS TABLE(person_id integer, sublist_name text, volume numeric, calc numeric, re_calc numeric)
LANGUAGE plpgsql
AS $_$
begin
	
	create temp table _house_filter (house_id int);

	if exists(select * from jsonb_populate_recordset(null::house.list, _house) h) 
		then
			insert into _house_filter 
			select h.house_id
			from jsonb_populate_recordset(null::house.list, _house) h;
		else 
			insert into _house_filter
			select al.house_id
			from contragent.account ca
				inner join jsonb_populate_recordset(null::special.objects, _contragent) c on c.object_id = ca.contragent_id
				inner join adress.light_info al on al.account_id = ca.account_id
			group by al.house_id;
	end if;

	return query
	select 
		cl.id as person_id
		,'Итого: ' || us."name" as sublist_name
		,coalesce(sum(pb.volume), 0) as volume
		,sum(pb.current_calculate) as calc
		,sum(pb.recalculate) as recalc 
	from contragent.list cl 
		inner join jsonb_populate_recordset(null::special.objects, _contragent) c on c.object_id = cl.id
		inner join contragent.account ca on ca.contragent_id = cl.id
		inner join contragent.owner_documents od on od.contragent_account_id = ca.id
		inner join payment.balance pb on pb.account_parent_id = ca.account_id
		inner join adress.account aa on aa.id = pb.account_id
		inner join _house_filter h on h.house_id = pb.house_id
		inner join utility.sublist us on us.id = pb.sublist_id
		inner join utility.list ul on ul.id = us.list_id
	where cl."type" = true 
		and pb.period_id = _period_id 
		and od.date_end is null 
		and pb.print = 1
		and coalesce(aa.group_id, 0) = coalesce(_group_id, 0)
	group by cl.id, pb.sublist_id, ul."name", us."name";

	drop table if exists _house_filter;
	
end;
$_$;


