DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering recalculation.preview(boolean, integer)...';END$$;
CREATE OR REPLACE FUNCTION recalculation.preview(IN _odn boolean, IN _root_id integer)
RETURNS TABLE(root_id integer, period_id integer, house_id integer, flat_id integer, account_id integer, adress text, flat_book_name character varying, flat_name character varying, account_name character varying, sublist_id integer, sublist_name character varying, date_begin date, date_end date, day smallint, calc_tarif numeric, recalc_tarif numeric, diff_tarif numeric, calc_volume numeric, recalc_volume numeric, diff_volume numeric, calc_result numeric, recalc_result numeric, diff_result numeric, account_parent_id integer)
LANGUAGE plpgsql
AS $_$
declare 
	_period_id	int;
	_date_begin	date;
	_date_end	date;
	_type		int;
	_diff 		numeric(5,2);
begin

	create temp table _sublist (sublist_id int);

	select pl.id, pl.date_begin, pl.date_end
	into _period_id, _date_begin, _date_end
	from "period".list pl
	where pl.is_working = true;
	
	_type = (select rr."type" from recalculation.root rr where rr.id = _root_id);

	_diff =(case when _type in (0,5) then 0.0 else 0.04 end);

	if (_odn = false)
		then
			insert into _sublist
			select us.id 
			from utility.sublist us
			where us.is_odn = false;
		else
			insert into _sublist
			select us.id 
			from utility.sublist us;
	end if;
	
	return query
	with cte as
	(
		
		select 
			 t.root_id
			,t.period_id
			,t.house_id
			,t.flat_id
			,t.account_id
			,t.sublist_id
			,t.date_begin
			,t.date_end
			,t."day"
			,t.tarif_value as recalc_tarif
			,case when _type = 5 then 0.0 else  coalesce(p.tarif, 0) end calc_tarif
			,case when _type = 5 then 0.0 else  coalesce(t.tarif_value, 0) - coalesce(p.tarif, 0) end diff_tarif
			,coalesce(t.volume_value,0) as recalc_volume
			,case when _type = 5 then 0.0 else  coalesce(p.volume, 0) end calc_volume 
			,case when _type = 5 then 0.0 else  coalesce(t.volume_value, 0) - coalesce(p.volume, 0) end diff_volume
			,(coalesce(t."result", 0)) recalc_result
			,case when _type = 5 then 0.0 else  (coalesce(p.current_calculate, 0)) end calc_result
			,case 
				when _type = 5 
				then 0.0 
				else  sum(coalesce(p.volume, 0)) 
					over (partition by t.root_id, t.period_id, t.house_id, t.flat_id, t.account_id, t.sublist_id) - sum(coalesce(t.volume_value, 0)) 
					over (partition by t.root_id, t.period_id, t.house_id, t.flat_id, t.account_id, t.sublist_id) 
			end as sum_volume
			,sum(coalesce(p.current_calculate, 0)) 
					over (partition by t.root_id, t.period_id, t.house_id, t.flat_id, t.account_id, t.sublist_id) - sum(coalesce(t."result", 0)) 
					over (partition by t.root_id, t.period_id, t.house_id, t.flat_id, t.account_id, t.sublist_id) 
			as sum_result
			,t.account_parent_id
		from recalculation.list_preview t
			left join 	(
							select pb.*, pl.date_begin, pl.date_end
							from payment.balance pb
								inner join "period".list pl on pl.id = pb.period_id
						) p on t.period_id = p.period_id
							and t.account_id = p.account_id 
							and t.sublist_id = p.sublist_id 
							and t.date_begin = p.date_begin
		where t.root_id = _root_id
	) 

		select 
			 c.root_id
			,c.period_id
			,c.house_id
			,c.flat_id
			,c.account_id
			,ai.street_name || ' ' || ai.house_number || ' ' || coalesce(ai.korpus, '') as adress
			,ai.flat_book_name
			,ai.flat_name
			,ai.account_name
			,c.sublist_id
			,us."name" as sublist_name
			,c.date_begin
			,c.date_end
			,c."day"
			,c.calc_tarif
			,c.recalc_tarif
			,c.diff_tarif
			,c.calc_volume
			,c.recalc_volume
			,c.diff_volume
			,c.calc_result
			,c.recalc_result
			,c.recalc_result - c.calc_result as diff_result
			,c.account_parent_id
		from cte c
			inner join adress.light_info ai on ai.account_id = c.account_id
			inner join utility.sublist us on us.id = c.sublist_id
			inner join _sublist s on s.sublist_id = c.sublist_id
		where (sum_result not between -_diff and _diff) 
			or (abs(sum_volume) > 0.00001 and us."type" = 1)
		order by ai.order_id, ai.account_order_id;
		
		 drop table if exists _sublist;
		
end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating recalculation.preview(boolean, integer)...';END$$;
COMMENT ON FUNCTION recalculation.preview(boolean, integer) IS '=============================================
 author:		глещинский д.в.
 create date: 08.07.2016
 description:	формирование предпросмотра перерасчета
 Modify date: 02.10.2023
 Modify:      Юркин Е.Ю. - при сохранении отсеиваются данные, результат которых находится в промежутке от -0.04 до 0.04 
							(кроме типов "перерасчет по тарифу", "перерасчет по сумме")
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering recalculation.filter(integer, integer, text)...';END$$;
CREATE OR REPLACE FUNCTION recalculation.filter(IN _period_begin integer, IN _period_end integer, IN _where_expression text DEFAULT NULL::text)
RETURNS TABLE(house_id integer, flat_id integer, account_id integer, settlement_type_id integer, settlement_id integer, street_book_id integer, street_id integer, house_number character varying, korpus character varying, flat_book_id smallint, flat_name character varying, access_number integer, account_name character varying, order_id integer, account_order_id integer, owners text)
LANGUAGE plpgsql
AS $_$
declare 
		_period_id	int;
		_is_working	bool = false;
		_n_pod		int;
		_sql 		text;
begin
	
	_n_pod = (select id from parametr.list where lower(short_name) = 'n_pod');

	_period_id = (select id from period.list where is_working = true);

	if (_period_id = _period_begin or _period_id = _period_end)
		then
			_is_working = true;
	end if;

	_sql = '
	select 
		al.house_id,
		al.flat_id,
		al.account_id, 
		al.settlement_type_id, 
		al.settlement_id, 
		al.street_book_id, 
		al.street_id, 
		al.house_number, 
		al.korpus, 
		al.flat_book_id, 
		al.flat_name, ' || case when _n_pod is null then 'null::int as access_number' else 'p.access_number, ' end || '
		al.account_name,
		al.order_id,
		al.account_order_id,
		(
			select string_agg(cl.full_name, '', '') 
			from contragent.list cl
				inner join contragent.account ca on ca.contragent_id = cl.id
				inner join contragent.owner_documents od on ca.id = od.contragent_account_id
			where ca.account_id = al.account_id  and od.date_end is null and ca.is_responsible = true
		) as owners
		from adress.light_info al ' || case when _n_pod is null then '' else '
			inner join (
							select pf.flat_id, cast(pf.value as int) as access_number
							from parametr.flat pf 
							where parametr_id = ' || _n_pod || 'and pf.date_end is null
						) p on p.flat_id = al.flat_id' end || ' 
			inner join calculation.parametr_transporate' || case when _is_working = false then '_arch' else '' end || ' cp on cp.account_id = al.account_id
	' || case 
			when _is_working = false 
			then 'where cp.period_id between ' || _period_begin || ' and ' || _period_end  
			else '' 
		end 
	|| case 
			when coalesce(_where_expression, '') = '' 
			then '' 
			else 
				case 
					when _is_working = false 
					then 'and ' 
					else ' where ' 
				end || _where_expression 
		end || '
	group by al.house_id, al.flat_id, al.account_id, al.settlement_type_id, al.settlement_id, al.street_book_id, al.street_id, al.house_number, al.korpus, al.flat_book_id, al.flat_name, al.account_name, al.order_id, al.account_order_id' 
		|| case when _n_pod is null then '' else ', p.access_number' end || ';';

	execute (_sql);

end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating recalculation.filter(integer, integer, text)...';END$$;
