COMMENT ON FUNCTION payment.detal_changed_update() IS 'Object:  Trigger [Payment].[Detal_Changed]    
 Script Date: 01.11.2022 11:10:30';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering payment.detal_changed_insert()...';END$$;
CREATE OR REPLACE FUNCTION payment.detal_changed_insert()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
begin
	
	if  ((select count(1) from (select distinct period_id from inserted) q) > 1)
		then
			raise exception 'Вставка деталей из разных периодов запрещена';
	end if;
			
	insert into payment.balance as pb (period_id, sublist_id, house_id, flat_id, account_id, pay, account_parent_id)
	select i.period_id, i.sublist_id, aa.house_id, aa.flat_id, i.account_id, i."sum" as pay, aa.parent_id
	from (
			select ii.period_id, ii.account_id, ii.sublist_id, sum(ii."sum") as "sum"
			from inserted ii
			group by ii.period_id, ii.account_id, ii.sublist_id
		) i
		inner join adress.account aa on aa.id = i.account_id
	on conflict (account_id, sublist_id, period_id)
	do update 
		set pay = coalesce(pb.pay, 0) + coalesce(excluded.pay, 0);

	return null;
			
end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating payment.detal_changed_insert()...';END$$;
COMMENT ON FUNCTION payment.detal_changed_insert() IS 'Object:  Trigger [Payment].[Detal_Changed]    
 Script Date: 01.11.2022 11:10:30';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering payment.detal_changed_deleted()...';END$$;
CREATE OR REPLACE FUNCTION payment.detal_changed_deleted()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
declare 
	_i int; 
begin

	update payment.balance pb 
		set	pay  =  coalesce(pb.pay, 0) - d."sum"
	from (
			select de.period_id, de.account_id, de.sublist_id, sum(de."sum") as sum
			from deleted de
			group by de.period_id, de.account_id, de.sublist_id
		) d
	where pb.account_id = d.account_id 
		and pb.period_id = d.period_id 
		and pb.sublist_id = d.sublist_id;

	with cte as 
	(
		insert into payment.balance(period_id, sublist_id, house_id, flat_id, account_id, pay, account_parent_id)
		select d.period_id, d.sublist_id, aa.house_id, aa.flat_id, d.account_id, -d."sum", aa.parent_id
		from deleted d
			left join payment.balance pb on pb.period_id = d.period_id 
				and pb.account_id = d.account_id 
				and pb.sublist_id = d.sublist_id
			join adress.account aa on d.account_id = aa.id
		where pb.id is null
		returning *
	)
	
	select count(1) 
	into _i
	from (select distinct i.period_id from cte i) as q;
		
	if (_i > 1)
		then
			raise exception 'Вставка деталей из разных периодов запрещена';
	end if;
			
	return null;
			
end;
$_$;


