DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating tests.diapazon_tarif_ee(jsonb)...';END$$;
CREATE FUNCTION tests.diapazon_tarif_ee(IN _account jsonb)
RETURNS TABLE(severity character varying, ask text)
LANGUAGE plpgsql
AS $_$
begin
	
	create temp table _house (house_id int);

	if exists (select 1 from jsonb_populate_recordset(null::account.list,_account) a limit 1)
		then
			begin
				insert into _house
				select distinct aa.house_id
				from jsonb_populate_recordset(null::account.list, _account) a
					inner join adress.account aa on aa.id = a.account_id
				group by house_id;
			end;
		else
			begin
				insert into _house
				select distinct aa.house_id
				from adress.account aa
				where parent_id is null
				group by house_id;
			end;
	end if;

	if exists (
		select 1 
		from calculation.account_sublist cs 
			inner join utility.sublist us on us.id = cs.sublist_id where list_id = 1028
		limit 1)
	and exists (
		select 1
		from utility.sublist_provider usp
			inner join _house h on h.house_id = usp.house_id
		where usp.date_end is null and usp.sublist_id in (8,9,10,27,28,42,31,33,36)
		limit 1)
	and (select count(*) from utility.sublist where id in (31,33,36)) = 3
		then 
			begin
		
			drop table if exists __account_user_dt;
			create temp table __account_user_dt (account_id int primary key);
			insert into __account_user_dt 
			select * 
			from jsonb_populate_recordset(null::account.list, _account) a;
		
			drop table if exists __account_open_dt;
			create temp table __account_open_dt (account_id int primary key, account_open int);
		
			if exists (select * from __account_user_dt)
				then
					begin
						insert into __account_open_dt
						select p.account_id, 
								sum((case when p.value = '1' then 1 else 0 end) * 
									(
									(
										case when coalesce(p.date_end,pl.date_end) > pl.date_end then pl.date_end else coalesce(p.date_end,pl.date_end) end
										-
										case when p.date_begin < pl.date_begin then pl.date_begin else p.date_begin end
									) 
									+ 1)
									) as account_open
						from parametr.account p
							inner join __account_user_dt au on au.account_id = p.account_id
							inner join period.list pl on pl.is_working = true
						where parametr_id = 1362 
							and coalesce(p.date_end,pl.date_end) >= (case when p.date_begin < pl.date_begin then pl.date_begin else p.date_begin end)
							and p.date_begin <= (case when coalesce(p.date_end,pl.date_end) > pl.date_end then pl.date_end else coalesce(p.date_end,pl.date_end) end)
						group by p.account_id;
					end; 
				else
					begin
						insert into __account_open_dt
						select p.account_id, 
							sum(
									(case when p.value = '1' then 1 else 0 end) 
									* 
									(
										(
											case when coalesce(p.date_end,pl.date_end) > pl.date_end then pl.date_end else coalesce(p.date_end,pl.date_end) end	
											-
											case when p.date_begin < pl.date_begin then pl.date_begin else p.date_begin end
										)
									 + 1
									)
								) as account_open
						from parametr.account p
							inner join period.list pl on pl.is_working = true
						where parametr_id = 1362 
							and coalesce(p.date_end,pl.date_end) >= (case when p.date_begin < pl.date_begin then pl.date_begin else p.date_begin end)
							and p.date_begin <= (case when coalesce(p.date_end,pl.date_end) > pl.date_end then pl.date_end else coalesce(p.date_end,pl.date_end) end)
						group by p.account_id;
					end;
			end if;
		
			drop table if exists __account_dt;
		
			create temp table __account_dt (
												house_id 		int, 
												account_id 		int, 
												span_el1 		numeric(15,5), 
												span_el2 		numeric(15,5), 
												sumrasels 		numeric(15,5), 
												rasel 			numeric(12,5), 
												raselday 		numeric(12,5), 
												raselnight	 	numeric(12,5), 
												sublist1 		int, 
												sublist2 		int, 
												sublist3 		int
											);
		
			if exists (select * from __account_user_dt)
				then
					begin
						insert into __account_dt
						select house_id, account_id, span_el1, span_el2, sumrasels, rasel, raselday, raselnight
							,case when rasel > 0 then 27 else case when raselday > 0 then 42 else 28 end end as sublist1
							,case when rasel > 0 then 8 else case when raselday > 0 then 9 else 10 end end as sublist2
							,case when sumrasels > span_el2 then case when rasel > 0 then 31 else case when raselday > 0 then 33 else 36 end end end as sublist3
						from (select house_id, account_id, 
								case when coalesce(flat_house,0) > 0 then sumrasels else
									case 
										when ellgot = 1
										then sumrasels
										when period_id < 133 
										then
											case 
												when region in (1, 23)
												then
													case 
														when ep = 1 and hco_eu = 0
														then 16000.00 
														when ep = 1 and hco_eu = 1
														then case when otopsezon = 1 then 20000.00 else 16000.00 end
														when ep = 0 and hco_eu = 1
														then case when otopsezon = 1 then 20000.00 else 11000.00 end 
														when ep = 0 and hco_eu = 0
														then 11000.00
													end
												when region = 5
												then 10950.00
												when region = 25
												then 11160.00
												when region = 29
												then 7092.00
												when region = 30
												then
													case 
														when ep = 1 and hco_eu = 0
														then 10000.00 
														when ep = 1 and hco_eu = 1
														then case when otopsezon = 1 then 15000.00 else 10000.00 end
														when ep = 0 and hco_eu = 1
														then case when otopsezon = 1 then 15000.00 else 10000.00 end 
														when ep = 0 and hco_eu = 0
														then 10000.00
													end
												when region = 63
												then 3660.00
												else sumrasels	
											end
										else
											case 
												when region in (1, 23)
												then
													case 
														when ep = 1 and hco_eu = 0 then (case when house_type = 1 then 1100.00 else 1200.00 end) 
														when ep = 1 and hco_eu = 1 then (case when otopsezon = 1 then 3900.00 else (case when house_type = 1 then 1100.00 else 1200.00 end) end)
														when ep = 0 and hco_eu = 1 then (case when otopsezon = 1 then 3900.00 else (case when house_type = 1 then 1000.00 else 1100.00 end) end) 
														when ep = 0 and hco_eu = 0 then (case when house_type = 1 then 1000.00 else 1100.00 end)
														else (case when house_type = 1 then 1000.00 else 1100.00 end)
													end
												when region = 5
												then 
													case 
														when ep = 1 and hco_eu = 0 then (case when house_type = 1 then 2000.00 else 2400.00 end) 
														when ep = 1 and hco_eu = 1 then (case when otopsezon = 1 then (case when house_type = 1 then 3200.00 else 3900.00 end) else (case when house_type = 1 then 2000.00 else 2400.00 end) end)
														when ep = 0 and hco_eu = 1 then (case when otopsezon = 1 then (case when house_type = 1 then 3200.00 else 3900.00 end) else (case when house_type = 1 then 2000.00 else 2400.00 end) end) 
														when ep = 0 and hco_eu = 0 then (case when house_type = 1 then 1200.00 else 1500.00 end)
														else (case when house_type = 1 then 1200.00 else 1500.00 end)
													end
												when region = 25
												then 
													case 
														when ep = 1 and hco_eu = 0 then 3900.00 
														when ep = 1 and hco_eu = 1 then 3900.00
														when ep = 0 and hco_eu = 1 then 3900.00 
														when ep = 0 and hco_eu = 0 then 1200.00
														else 1200.00
													end
												when region = 29
												then 
													case 
														when ep = 1 and hco_eu = 0 then 1200.00 
														when ep = 1 and hco_eu = 1 then (case when otopsezon = 1 then 3900.00 else 1200.00 end)
														when ep = 0 and hco_eu = 1 then (case when otopsezon = 1 then 3900.00 else 1200.00 end) 
														when ep = 0 and hco_eu = 0 then 1200.00
														else 1200.00
													end
												when region = 30 then 1200.00
												when region in (63, 71)
												then 
													case 
														when ep = 1 and hco_eu = 0 then 1200.00 
														when ep = 1 and hco_eu = 1 then (case when otopsezon = 1 then 3900.00 else 1200.00 end)
														when ep = 0 and hco_eu = 1 then (case when otopsezon = 1 then 3900.00 else 1200.00 end) 
														when ep = 0 and hco_eu = 0 then 1200.00
														else 1200.00
													end
												when region in (72, 77, 86, 89) then 3900.0
												else sumrasels	
											end	
									end
								end	as span_el1,
								case when coalesce(flat_house,0) > 0 then sumrasels else
									case 
										when ellgot = 1
										then 0.0
										when period_id < 133 
										then 
											case 
												when region in (1, 23)
												then
													case 
														when ep = 1 and hco_eu = 0 
														then 25000.00
														when ep = 1 and hco_eu = 1
														then case when otopsezon = 1 then 30000.00 else 25000.00 end 
														when ep = 0 and hco_eu = 1
														then case when otopsezon = 1 then 30000.00 else 20000.00 end 
														when ep = 0 and hco_eu = 0 
														then 20000.00
													end
												when region = 5
												then 25000.00
												when region = 25
												then 11170.00
												when region = 29
												then 11160.00
												when region = 30
												then
													case 
														when ep = 1 and hco_eu = 0 
														then 15000.00
														when ep = 1 and hco_eu = 1
														then case when otopsezon = 1 then 20000.00 else 15000.00 end 
														when ep = 0 and hco_eu = 1
														then case when otopsezon = 1 then 20000.00 else 15000.00 end 
														when ep = 0 and hco_eu = 0 
														then 15000.00
													end
												when region = 63
												then 10980.00
												else 0.0	
											end
										else 
											case 
												when region in (1, 23)
												then
													case 
														when ep = 1 and hco_eu = 0 then (case when house_type = 1 then 1700.00 else 1850.00 end)
														when ep = 1 and hco_eu = 1 then (case when otopsezon = 1 then 6000.00 else (case when house_type = 1 then 1700.00 else 1850.00 end) end) 
														when ep = 0 and hco_eu = 1 then (case when otopsezon = 1 then 6000.00 else (case when house_type = 1 then 1550.00 else 1700.00 end) end) 
														when ep = 0 and hco_eu = 0 then (case when house_type = 1 then 1550.00 else 1700.00 end)
														else (case when house_type = 1 then 1550.00 else 1700.00 end)
													end
												when region = 5
												then 
													case 
														when ep = 1 and hco_eu = 0 then (case when house_type = 1 then 3200.00 else 3800.00 end)
														when ep = 1 and hco_eu = 1 then (case when otopsezon = 1 then (case when house_type = 1 then 5000.00 else 6000.00 end) else (case when house_type = 1 then 3200.00 else 3800.00 end) end) 
														when ep = 0 and hco_eu = 1 then (case when otopsezon = 1 then (case when house_type = 1 then 5000.00 else 6000.00 end) else (case when house_type = 1 then 3200.00 else 3800.00 end) end) 
														when ep = 0 and hco_eu = 0 then (case when house_type = 1 then 2000.00 else 2400.00 end)
														else (case when house_type = 1 then 2000.00 else 2400.00 end)
													end
												when region = 25 then 6000.00
												when region = 29 then 6000.00
												when region = 30 then 3000.00
												when region in (63, 71) then 6000.00
												when region in (72, 77, 86, 89) then 6000.0	
												else 0.0
											end	
									end
								end	as span_el2
								,sumrasels, rasel, raselday, raselnight
								from (select pl.id as period_id, lg.ellgot, coalesce(flat_house,0) as flat_house, coalesce(hc.house_type,1) as house_type, cast(rtrim(ltrim(coalesce(re.code,'0'))) as int) as region, cpt.account_id, cpt.house_id, coalesce(cpt.ep,0) as ep, coalesce(cpt.hco_eu,0) as hco_eu, coalesce(cpt.rasel,0) + coalesce(cpt.raselday,0) + coalesce(cpt.raselnight,0) as sumrasels, cpt.rasel, cpt.raselday, cpt.raselnight
									,case
										when coalesce(p.otopoff,0) = 1 
											then 0::int2
										when (pl.Month_Id >= coalesce(te.month_begin,10) or pl.Month_Id <= coalesce(te.month_end,4)) or coalesce(p.otopoff,0) > 1
											then 1::int2
										else 0::int2
									end as otopsezon
									from adress.region re
									inner join adress.territory te on te.region_id = re.id
									inner join adress.house ah on ah.territory_id = te.id
									inner join calculation.parametr_transporate cpt on cpt.territory_id = te.id and cpt.house_id = ah.id
									inner join __account_user_dt au on au.account_id = cpt.account_id
									inner join period.list pl on pl.is_working = true
									inner join __account_open_dt r on r.account_id = cpt.account_id
									left join (select ph.house_id, coalesce(ph.value,'0')::int2 as otopoff
												from parametr.house ph
												where ph.parametr_id = 201 and ph.date_end is null
											) p on p.house_id = ah.id
									left join (select ca.account_id, max(case when pb.number::int in (3,6) then 1 else 0 end) as ellgot
												from contragent.account ca 
												inner join __account_user_dt au on au.account_id = ca.account_id
												inner join contragent.parametr cp on cp.contragent_account_id = ca.id and cp.parametr_id = 1472
												inner join parametr.book pb on cp.book_id = pb.id and pb.parametr_id = cp.parametr_id 
												group by ca.account_id
											) lg on lg.account_id = cpt.account_id
									left join house.characteristic hc on hc.house_id = cpt.house_id
									left join (select house_id, min(flat_type) as flat_house from calculation.parametr_transporate where is_closed = 1 group by house_id) cс on cс.house_id = cpt.house_id
									where r.account_open > 0
										and exists (select c.flat_type from calculation.parametr_transporate c where c.house_id = cpt.house_id and c.flat_type = 0 and c.is_closed = 1 limit 1)
									) cp
						) c 
						where sumrasels > span_el1;
					end; 
				else
					begin 
						insert into __account_dt
						select house_id, account_id, span_el1, span_el2, sumrasels, rasel, raselday, raselnight
								,case when rasel > 0 then 27 else case when raselday > 0 then 42 else 28 end end as sublist1
								,case when rasel > 0 then 8 else case when raselday > 0 then 9 else 10 end end as sublist2
								,case when sumrasels > span_el2 then case when rasel > 0 then 31 else case when raselday > 0 then 33 else 36 end end end as sublist3
						from (
								select house_id, account_id, 
									case when coalesce(flat_house,0) > 0 then sumrasels else
										case 
											when ellgot = 1
											then sumrasels
											when period_id < 133 
											then
												case 
													when region in (1, 23)
													then
														case 
															when ep = 1 and hco_eu = 0
															then 16000.00 
															when ep = 1 and hco_eu = 1
															then case when otopsezon = 1 then 20000.00 else 16000.00 end
															when ep = 0 and hco_eu = 1
															then case when otopsezon = 1 then 20000.00 else 11000.00 end 
															when ep = 0 and hco_eu = 0
															then 11000.00
														end
													when region = 5
													then 10950.00
													when region = 25
													then 11160.00
													when region = 29
													then 7092.00
													when region = 30
													then
														case 
															when ep = 1 and hco_eu = 0
															then 10000.00 
															when ep = 1 and hco_eu = 1
															then case when otopsezon = 1 then 15000.00 else 10000.00 end
															when ep = 0 and hco_eu = 1
															then case when otopsezon = 1 then 15000.00 else 10000.00 end 
															when ep = 0 and hco_eu = 0
															then 10000.00
														end
													when region = 63
													then 3660.00
													else sumrasels	
												end
											else
												case 
													when region in (1, 23)
													then
														case 
															when ep = 1 and hco_eu = 0 then (case when house_type = 1 then 1100.00 else 1200.00 end) 
															when ep = 1 and hco_eu = 1 then (case when otopsezon = 1 then 3900.00 else (case when house_type = 1 then 1100.00 else 1200.00 end) end)
															when ep = 0 and hco_eu = 1 then (case when otopsezon = 1 then 3900.00 else (case when house_type = 1 then 1000.00 else 1100.00 end) end) 
															when ep = 0 and hco_eu = 0 then (case when house_type = 1 then 1000.00 else 1100.00 end)
															else (case when house_type = 1 then 1000.00 else 1100.00 end)
														end
													when region = 5
													then 
														case 
															when ep = 1 and hco_eu = 0 then (case when house_type = 1 then 2000.00 else 2400.00 end) 
															when ep = 1 and hco_eu = 1 then (case when otopsezon = 1 then (case when house_type = 1 then 3200.00 else 3900.00 end) else (case when house_type = 1 then 2000.00 else 2400.00 end) end)
															when ep = 0 and hco_eu = 1 then (case when otopsezon = 1 then (case when house_type = 1 then 3200.00 else 3900.00 end) else (case when house_type = 1 then 2000.00 else 2400.00 end) end) 
															when ep = 0 and hco_eu = 0 then (case when house_type = 1 then 1200.00 else 1500.00 end)
															else (case when house_type = 1 then 1200.00 else 1500.00 end)
														end
													when region = 25
													then 
														case 
															when ep = 1 and hco_eu = 0 then 3900.00 
															when ep = 1 and hco_eu = 1 then 3900.00
															when ep = 0 and hco_eu = 1 then 3900.00 
															when ep = 0 and hco_eu = 0 then 1200.00
															else 1200.00
														end
													when region = 29
													then 
														case 
															when ep = 1 and hco_eu = 0 then 1200.00 
															when ep = 1 and hco_eu = 1 then (case when otopsezon = 1 then 3900.00 else 1200.00 end)
															when ep = 0 and hco_eu = 1 then (case when otopsezon = 1 then 3900.00 else 1200.00 end) 
															when ep = 0 and hco_eu = 0 then 1200.00
															else 1200.00
														end
													when region = 30 then 1200.00
													when region in (63, 71)
													then 
														case 
															when ep = 1 and hco_eu = 0 then 1200.00 
															when ep = 1 and hco_eu = 1 then (case when otopsezon = 1 then 3900.00 else 1200.00 end)
															when ep = 0 and hco_eu = 1 then (case when otopsezon = 1 then 3900.00 else 1200.00 end) 
															when ep = 0 and hco_eu = 0 then 1200.00
															else 1200.00
														end
													when region in (72, 77, 86, 89) then 3900.0
													else sumrasels	
												end	
										end
									end	as span_el1,
									case when coalesce(flat_house,0) > 0 then sumrasels else
										case 
											when ellgot = 1
											then 0.0
											when period_id < 133 
											then 
												case 
													when region in (1, 23)
													then
														case 
															when ep = 1 and hco_eu = 0 
															then 25000.00
															when ep = 1 and hco_eu = 1
															then case when otopsezon = 1 then 30000.00 else 25000.00 end 
															when ep = 0 and hco_eu = 1
															then case when otopsezon = 1 then 30000.00 else 20000.00 end 
															when ep = 0 and hco_eu = 0 
															then 20000.00
														end
													when region = 5
													then 25000.00
													when region = 25
													then 11170.00
													when region = 29
													then 11160.00
													when region = 30
													then
														case 
															when ep = 1 and hco_eu = 0 
															then 15000.00
															when ep = 1 and hco_eu = 1
															then case when otopsezon = 1 then 20000.00 else 15000.00 end 
															when ep = 0 and hco_eu = 1
															then case when otopsezon = 1 then 20000.00 else 15000.00 end 
															when ep = 0 and hco_eu = 0 
															then 15000.00
														end
													when region = 63
													then 10980.00
													else 0.0	
												end
											else 
												case 
													when region in (1, 23)
													then
														case 
															when ep = 1 and hco_eu = 0 then (case when house_type = 1 then 1700.00 else 1850.00 end)
															when ep = 1 and hco_eu = 1 then (case when otopsezon = 1 then 6000.00 else (case when house_type = 1 then 1700.00 else 1850.00 end) end) 
															when ep = 0 and hco_eu = 1 then (case when otopsezon = 1 then 6000.00 else (case when house_type = 1 then 1550.00 else 1700.00 end) end) 
															when ep = 0 and hco_eu = 0 then (case when house_type = 1 then 1550.00 else 1700.00 end)
															else (case when house_type = 1 then 1550.00 else 1700.00 end)
														end
													when region = 5
													then 
														case 
															when ep = 1 and hco_eu = 0 then (case when house_type = 1 then 3200.00 else 3800.00 end)
															when ep = 1 and hco_eu = 1 then (case when otopsezon = 1 then (case when house_type = 1 then 5000.00 else 6000.00 end) else (case when house_type = 1 then 3200.00 else 3800.00 end) end) 
															when ep = 0 and hco_eu = 1 then (case when otopsezon = 1 then (case when house_type = 1 then 5000.00 else 6000.00 end) else (case when house_type = 1 then 3200.00 else 3800.00 end) end) 
															when ep = 0 and hco_eu = 0 then (case when house_type = 1 then 2000.00 else 2400.00 end)
															else (case when house_type = 1 then 2000.00 else 2400.00 end)
														end
													when region = 25 then 6000.00
													when region = 29 then 6000.00
													when region = 30 then 3000.00
													when region in (63, 71) then 6000.00
													when region in (72, 77, 86, 89) then 6000.0	
													else 0.0
												end	
										end
									end	as span_el2
									, sumrasels, rasel, raselday, raselnight
									from (select pl.id as period_id, lg.ellgot, coalesce(flat_house,0) as flat_house, coalesce(hc.house_type,1) as house_type, cast(rtrim(ltrim(coalesce(re.code,'0'))) as int) as region, cpt.account_id, cpt.house_id, coalesce(cpt.ep,0) as ep, coalesce(cpt.hco_eu,0) as hco_eu, coalesce(cpt.rasel,0) + coalesce(cpt.raselday,0) + coalesce(cpt.raselnight,0) as sumrasels, cpt.rasel, cpt.raselday, cpt.raselnight
										,case
											when coalesce(p.otopoff,0) = 1 
												then 0::int2
											when (pl.month_id >= coalesce(te.month_begin,10) or pl.month_id <= coalesce(te.month_end,4)) or coalesce(p.otopoff,0) > 1
												then 1::int2
											else 0::int2
										end as otopsezon
										from adress.region re
										inner join adress.territory te on te.region_id = re.id
										inner join adress.house ah on ah.territory_id = te.id
										inner join calculation.parametr_transporate cpt on cpt.territory_id = te.id and cpt.house_id = ah.id
										inner join period.list pl on pl.is_working = true
										inner join __account_open_dt r on r.account_id = cpt.account_id
										left join (select ph.house_id, coalesce(ph.value,'0')::int2 as otopoff
													from parametr.house ph
													where ph.parametr_id = 201 and ph.date_end is null) p on p.house_id = ah.id
										left join (select ca.account_id, max(case when pb.number::int2 in (3,6) then 1 else 0 end) as ellgot
													from contragent.account ca 
													inner join contragent.parametr cp on cp.contragent_account_id = ca.id and cp.parametr_id = 1472 
													inner join parametr.book pb on cp.book_id = pb.id and pb.parametr_id = cp.parametr_id 
													group by ca.account_id) lg on lg.account_id = cpt.account_id
										left join house.characteristic hc on hc.house_id = cpt.house_id
										left join (select house_id, min(flat_type) as flat_house from calculation.parametr_transporate where is_closed = 1 group by house_id) cс on cс.house_id = cpt.house_id
										where r.account_open > 0
											and exists (select c.flat_type from calculation.parametr_transporate c where c.house_id = cpt.house_id and c.flat_type = 0 and c.is_closed = 1 limit 1)
										) cp
						) c where sumrasels > span_el1;
					end;
			end if;
		
			insert into __account_dt
			select house_id, account_id, span_el1, span_el2, sumrasels, rasel, raselday, raselnight
				,case when raselnight > 0 then 28 end as sublist1
				,case when raselnight > 0 then 10 end as sublist2
				,case when sumrasels > span_el2 then case when raselnight > 0 then 36 end end as sublist3
			from __account_dt
			where sublist1 = 42;
			
			drop table if exists __house_dt;
			create temp table __house_dt (house_id int primary key);
			
			insert into __house_dt
			select house_id
			from __account_dt
			group by house_id;
		
			drop table if exists __tarif_dt;
			create temp table __tarif_dt (sublist_id int, house_id int, provider int, tarif int);
		
			insert into __tarif_dt
			select usp.sublist_id, usp.house_id, max(case when usp.provider_id is not null then 1 end) as provider, max(case when ht.value > 0 then 1 end) as tarif 
			from utility.sublist_provider usp
				inner join __house_dt h on h.house_id = usp.house_id
			left join (select th.house_id, th.number, tl.provider_id, tl.sublist_id, tl.territory_id, tl.value
						from tarif.house_tarif th 
							inner join tarif.list tl on tl.id = th.tarif_id
						where th.date_end is null
						) ht on ht.house_id = usp.house_id and ht.provider_id = usp.provider_id and ht.sublist_id = usp.sublist_id and ht.territory_id = usp.territory_id
			where usp.date_end is null and usp.sublist_id in (8,9,10,27,28,42,31,33,36)
			group by usp.sublist_id, usp.provider_id, usp.territory_id, usp.house_id;
		
			return query
			with cte as 
			(
				select a.house_id, a.account_id, a.span_el1, a.span_el2, a.sumrasels, a.rasel, a.raselday, a.raselnight, a.sublist1, a.sublist2, a.sublist3,
					max(t1.provider) as provider1, max(t1.tarif) as tarif1, max(t2.provider) as provider2, max(t2.tarif) as tarif2, max(t3.provider) as provider3, max(t3.tarif) as tarif3
				from __account_dt a
					left join __tarif_dt t1 on t1.sublist_id = a.sublist1 and t1.house_id = a.house_id
					left join __tarif_dt t2 on t2.sublist_id = a.sublist2 and t2.house_id = a.house_id
					left join __tarif_dt t3 on t3.sublist_id = a.sublist3 and t3.house_id = a.house_id
				group by a.house_id, a.account_id, a.span_el1, a.span_el2, a.sumrasels, a.rasel, a.raselday, a.raselnight, a.sublist1, a.sublist2, a.sublist3
			)
			,cte2 as 
			(
				select 
				case 
					when tarif1 is not null and provider2 is null and tarif2 is null then 'Отсутствует поставщик и тариф на ' || hi.short_adress || ' для расчета ' || us.name || ' по лс №' || ao.account_name
					when tarif1 is not null and tarif2 is null then 'Отсутствует тариф на ' || hi.short_adress || ' для расчета ' || us.name || ' по лс №' || ao.account_name 
					when provider1 is not null and provider2 is null then 'Отсутствует поставщик на ' || hi.short_adress || ' для учета объема ' || us.name || ' по лс №' || ao.account_name
				end as ask
				from cte c
					inner join house.info hi on hi.house_id = c.house_id
					inner join utility.sublist us on us.id = c.sublist2
					inner join adress.owners ao on ao.account_id = c.account_id
				where provider1 is not null and (provider2 is null or tarif2 is null)
				union all
				select 
				case 
					when tarif1 is not null and provider3 is null and tarif3 is null then 'Отсутствует поставщик и тариф на ' || hi.short_adress || ' для расчета ' || us.name || ' по лс №' || ao.account_name
					when tarif1 is not null and tarif3 is null then 'Отсутствует тариф на ' || hi.short_adress || ' для расчета ' || us.name || ' по лс №' || ao.account_name 
					when provider1 is not null and provider3 is null then 'Отсутствует поставщик на ' || hi.short_adress || ' для учета объема ' || us.name || ' по лс №' || ao.account_name
				end as ask
				from cte c
					inner join house.info hi on hi.house_id = c.house_id
					inner join utility.sublist us on us.id = c.sublist3
					inner join adress.owners ao on ao.account_id = c.account_id
				where provider1 is not null and (provider3 is null or tarif3 is null)
				union all
				select 
				case 
					when tarif2 is not null and provider1 is null and tarif1 is null then 'Отсутствует поставщик и тариф на ' || hi.short_adress || ' для расчета ' || us.name || ' по лс №' || ao.account_name
					when tarif2 is not null and tarif1 is null then 'Отсутствует тариф на ' || hi.short_adress || ' для расчета ' || us.name || ' по лс №' || ao.account_name 
					when provider2 is not null and provider1 is null then 'Отсутствует поставщик на ' || hi.short_adress || ' для учета объема ' || us.name || ' по лс №' || ao.account_name
				end as ask
				from cte c
					inner join house.info hi on hi.house_id = c.house_id
					inner join utility.sublist us on us.id = c.sublist2
					inner join adress.owners ao on ao.account_id = c.account_id
				where provider1 is null and provider2 is not null
			)

			select distinct 'wrn'::varchar(3) as severity, c.ask
			from cte2 c;

		end;
	end if;

	drop table if exists __tarif_dt;
	drop table if exists __house_dt;
	drop table if exists __account_dt;
	drop table if exists __account_open_dt;
	drop table if exists __account_user_dt;
	drop table if exists _house;

end;
$_$;
