DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering parametr.new_param()...';END$$;
CREATE OR REPLACE FUNCTION parametr.new_param()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
declare 
		_pl_table		varchar(255);
		_pl_query		text;
		_p_table		varchar(255);
		_parent_table	varchar(50);
		_type			int;
		_parametr_id	int;
		_catalog_id		int;
		_value			int;
		_date_begin		date;
		_default_value	varchar(200);
		_p_table_id		varchar(100);
		_short_name		varchar(15);
		_len			smallint;
		_precision		int2;
		_sql 			text = '';
		_type_name 		varchar(15);
		_capacity 		text = '';	
begin
	
	if not exists(select * from inserted) 
		then
			return null;
	end if;

	_parametr_id = (select max(pl.ID) from parametr.list pl);
	_date_begin = (select pl.date_begin from "period".list pl where pl.is_working = true);

	select pd.pl_table, pd.p_table, pd.parent_table, pl.catalog_id, pl.type_id, pl.default_value, pd.p_table_id, pl.short_name, pl.len, pl."preision"
	into _pl_table, _p_table, _parent_table, _catalog_id, _type, _default_value, _p_table_id, _short_name, _len, _precision
	from parametr."catalog" pd
		inner join parametr.list pl on pd.id = pl.catalog_id and pl.id = _parametr_id
	where pl.catalog_id != 6;

	if (_pl_table is not null)
		then
			begin
				_pl_query = 'if not exists(select 1 from ' || _pl_table || ' where parametr_id = ' || _parametr_id || ')
							 insert into ' || _pl_table || ' values (' || _parametr_id || ')';
				
				execute(_pl_query);
			end;
	end if;

	if (_parent_table is not null and _p_table is not null and _p_table <> 'parametr.person')
		then
			begin
				_pl_query = 'if not exists(select 1 from ' || _p_table || ' where parametr_id = ' || _parametr_id || ')
								then
									insert into ' || _p_table || ' (' || _p_table_id || ', parametr_id, value, date_begin) 
									select id,'  
											|| _parametr_id || ','
											|| case when _default_value is null then 'null' else '''' || _default_value || ''''  end
											|| ',''' || _date_begin || '''
									from ' || _parent_table ||
									case when _parent_table = 'adress.account' then ' where parent_id is null limit 1' else '' end || ';
							end if;';
						
				execute(_pl_query);
			end;
	end if;

	if (_catalog_id = 9)
		then
			begin
				
				_capacity = case 
								when coalesce(_len, 0) != 0 
								then '(' || _len || case 
														when coalesce(_precision, 0) != 0 
														then ',' || _precision || ')' 
														else ')' 
													end 
								else ''
							end;
		
				_type_name = (select pt.system_type from parametr."type" pt where pt.id = _type);
		
				_sql = 'alter table calculation.sum_volume add ' 		|| _short_name || ' ' || _type_name || _capacity || '
						alter table recalculation.sum_volume add ' 		|| _short_name || ' ' || _type_name || _capacity || '
						alter table calculation.sum_volume_arch add '	|| _short_name || ' ' || _type_name || _capacity || ';';
					
				execute(_sql);
			end;
	end if;
end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating parametr.new_param()...';END$$;
COMMENT ON FUNCTION parametr.new_param() IS '=============================================
 Author:		Глещинский Д.В.
 Create date: 17.04.2014
 Description:	Триггер на добавление праметра и подстановки занчений в дочерние таблицы
 =============================================
 Modified Author:			Глещинский Д.В.
 Modified date:			26.09.2018
 Modified description:	Добавил автоматическое создание колонок в  [Calculation].[SumVolume], [Calculation].[SumVolumeArch]
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering parametr.is_calculation(text)...';END$$;
CREATE OR REPLACE PROCEDURE parametr.is_calculation(IN _formula text)
LANGUAGE plpgsql
AS $_$
declare 
	_parametr_added text = '';
	_table_alter 	text;
	_error_message 	text;
begin
	
	create temp table _parametr (parametr_id int, short_name varchar(20), catalog_id int not null, system_type varchar(50)); 
	create temp table _fill_parametr (object_id int, parametr_id int, value varchar(200), date_begin date);

	begin 
		
		insert into _parametr (parametr_id, short_name, catalog_id, system_type)
		select distinct 
			 pl.id as parametr_id
			,pl.short_name
			,pl.catalog_id
			,pt.system_type || 
				case 
					when pl.len is not null and pl."precision" is null then '(' || pl.len || ')'
					when pl.len is not null and pl."precision" is not null then '(' || pl.len || ',' || pl."precision" || ')'
					else ''
				end as system_type
		from regexp_split_to_table((' "' ||_formula || '" '), '\W+') p
			inner join parametr.list pl on lower(pl.short_name) = lower(p)
			inner join parametr."type" pt on pt.id = pl.type_id
		where pl.catalog_id <= 3 
			and pl.short_name not in 
									(
										select column_name /*, data_type, is_nullable*/
										from information_schema."columns"
										where lower(table_name) = 'parametr_transporate'
											and lower(table_schema) = 'calculation'
									)
		group by pl.id, pl.short_name, pl.catalog_id, pt.system_type, pl.len, pl."precision", pl.type_id;
	
		update parametr.list pl
			set is_calculation = true
		from _parametr p 
		where p.parametr_id = pl.id;

		_parametr_added = (select _parametr_added || '"' || short_name || '" ' || system_type|| ' null, ' from _parametr pl);

		if (_parametr_added is not null and _parametr_added <> '') 
			then
				begin
					_parametr_added = substring(_parametr_added, 0, length(_parametr_added) - 0) || ';'; 
		
					_table_alter = '
					alter table calculation.parametr_transporate add ' || _parametr_added;
					execute(_table_alter);
				
					_table_alter = '
					alter table recalculation.parametr_transporate add ' || _parametr_added;
					execute(_table_alter);
				
					_table_alter = '
					alter table calculation.parametr_transporate_arch add ' || _parametr_added;
					execute(_table_alter);
		
					_table_alter = '';
					
					_table_alter = (
										select string_agg('
										update calculation.parametr_transporate cp 
											set
											' || p.short_name || ' = cast(value as ' || system_type || ')
										from  ' || pc.p_table || ' pa 
										where pa.' || p_table_id || ' = cp.' || p_table_id || '  
												and pa.parametr_id = ' || p.parametr_id || ' 
												and pa.date_begin = (
																		select max(l.date_begin) 
																		from ' || pc.p_table || ' as l 
																		where l.' || p_table_id || ' = pa.' || p_table_id || ' 
																			and l.parametr_id = pa.parametr_id
																	);'
															, '')				
										from _parametr p
											inner join parametr."catalog" pc on pc.id = p.catalog_id
									);
		
					execute(_table_alter);
				end;
		end if;
	
	exception when others 
		then 
			get stacked diagnostics
				_error_message = pg_exception_context;
	
			raise exception '%', _error_message;
	end; 
	
	drop table if exists _parametr; 
	drop table if exists  _fill_parametr;
			
end
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating parametr.is_calculation(text)...';END$$;
COMMENT ON PROCEDURE parametr.is_calculation(text) IS '=============================================
 author:		глещинский д.в.
 create date: 10.08.2015
 description:	обновление is_calculation в parametr.list
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering parametr.insert_house_parametr_transporate()...';END$$;
CREATE OR REPLACE FUNCTION parametr.insert_house_parametr_transporate()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
declare 
	_sql		text = '';
	_date_end	date;
begin  
			
	if not exists (select * from inserted) 
		then 
			return null;
	end if;
		
	create temp table _parametr (house_id int, parametr_id int, short_name text, value text);
									
	_date_end = (select date_end from period.list where is_working = true);
	
	with cte as 
	(
		select 
			ph.id,
			ph.house_id, 
			ph.parametr_id, 
			ph.date_end,
		 	(lead(ph.date_begin, 1, null) over (partition by ph.house_id, ph.parametr_id order by ph.house_id, ph.parametr_id, ph.date_begin)) - 1 as new_date_end
		from parametr.house ph
		where ph.parametr_id in (select parametr_id from inserted)
			and house_id in (select house_id from inserted)
	)
	update parametr.house ph
		set date_end = ct.new_date_end
	from cte ct
	where ph.id = ct.id and ((ct.date_end is null or ct.date_end <> ct.new_date_end) or new_date_end is null); 

	insert into _parametr
	select 
		 i.house_id
		,i.parametr_id
		,pl.short_name
		,i.value
	from inserted i
		inner join parametr.list pl on pl.id = i.parametr_id
	where is_calculation = true
		and i.date_end is null;

	if not exists(select 1 from _parametr) 
		then 
			return null;
	end if;

	_sql =  _sql || (select string_agg( p,'
		')
					from (
					 select '
		update calculation.parametr_transporate as cp 
			set 
				' || p.short_name || ' = cast(p.value as ' || pt.system_type || 
																case 
																	when pl.len is not null and pl."precision" is null then '(' || cast(pl.len as varchar(10)) || ')'
																	when pl.len is not null and pl."precision" is not null then '(' || cast(pl.len as varchar(10)) || ',' || cast(pl."precision" as varchar(3)) || ')'
																	else ''
																end || ')
		from _parametr p 
		where p.house_id = cp.house_id and p.parametr_id = ' || cast(p.parametr_id as varchar(10)) || ';' as p
	from _parametr p
		inner join parametr.list pl on pl.id = p.parametr_id
		inner join parametr."type" pt on pt.id = pl.type_id
	group by p.short_name, p.parametr_id, pt.system_type, pl.len, pl."precision" )as d)  ;
	
	execute (_sql);

	drop table if exists _parametr;	

	return null;
		
end;
$_$;


