DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering parametr.delete_house_parametr_transporate()...';END$$;
CREATE OR REPLACE FUNCTION parametr.delete_house_parametr_transporate()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
begin 
	
	with cte as 
	(
		select  pf.house_id,
				pf.parametr_id, 
				pf.date_end,
				(lead(pf.date_begin, 1, null) over (partition by pf.house_id, pf.parametr_id order by pf.house_id, pf.parametr_id, pf.date_begin)) - 1 as new_date_end,
				id
		from parametr.house pf 
		where pf.parametr_id in (select distinct parametr_id from deleted)
			and house_id in (select distinct house_id from deleted)
	)	
	update parametr.house ph
	set 
		date_end = ct.new_date_end
	from cte ct
	where ct.id = ph.id and ((ct.date_end is null or ct.date_end <> ct.new_date_end) or ct.new_date_end is null);

	return null;	

end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering parametr.delete_flat_parametr_transporate()...';END$$;
CREATE OR REPLACE FUNCTION parametr.delete_flat_parametr_transporate()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
begin

	set session_replication_role = replica;
	
	with cte as 
	(
		select 
			pf.id,
			pf.flat_id,
			pf.parametr_id, 
			pf.date_end,
			(lead(pf.date_begin, 1, null) over (partition by pf.flat_id, pf.parametr_id order by pf.flat_id, pf.parametr_id, pf.date_begin) - interval '1 day') as new_date_end
	from parametr.flat pf 
	where pf.parametr_id in (select distinct d.parametr_id from deleted d)
		and flat_id in (select distinct d.flat_id from deleted d)
	)

	update parametr.flat pf 
		set date_end = ct.new_date_end
	from cte ct
	where ct.id = pf.id and 
		((ct.date_end is null or ct.date_end <> new_date_end) 
				or ct.new_date_end is null );

	set session_replication_role = default;	

	return null;
		
end;
$_$;


