 create date: <create date,,>
 description:	актуализация данных
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating fine.calc_legal(jsonb)...';END$$;
CREATE PROCEDURE fine.calc_legal(IN _account jsonb)
LANGUAGE plpgsql
AS $_$
declare 
	_date_begin		date;
	_date_end		date;
	_period_id		int;
	_parametr_id	int;
	_active_period 	int;
	_type_fine 		int;
begin
	
	drop table if exists  _calendar;
    create temp table _calendar ("date" date);

	_active_period = (select id from "period".list where is_active = true);
	_type_fine = (select id from fine.list where lower(name) = 'предприятия');

	select id, date_begin, date_end 
	into _period_id, _date_begin, _date_end
	from "period".list 
	where is_working = true;
	
	drop table if exists _fine_table;
	create temp table _fine_table (account_id int not null primary key, free_days int, part numeric (5,0), account_parent_id int);	

	insert into _fine_table
	select fa.account_id, fr.free_days - 1 as free_days, fr.part_refinancing_rate31, al.parent_id
	from fine.account fa
		inner join fine.rate fr on fr.list_id = fa.fine_id
		inner join adress.account al on al.id = fa.account_id
		inner join jsonb_populate_recordset(null::account.list, _account) a on a.account_id = al.parent_id
	where fa.fine_id = _type_fine;
	
	drop table if exists _fine_history;
	create temp table _fine_history (account_id int not null, date_begin date, date_end date, rate numeric (4,2), account_parent_id int);

	insert into _fine_history
	select 
		fa.account_id, 
		case when fh.date_begin < _date_begin then _date_begin else fh.date_begin end as date_begin,
		case when coalesce(fh.date_end, _date_end) >= _date_end then _date_end else fh.date_end end as date_end,
		fh.refinancing_rate, 
		al.parent_id
	from fine.account fa
		inner join fine.rate fr on fr.list_id = fa.fine_id
		inner join adress.account al on al.id = fa.account_id
		inner join fine.history fh on fh.date_begin <= _date_end and coalesce(fh.date_end, _date_end) >= _date_begin
		inner join jsonb_populate_recordset(null::account.list, _account) a on a.account_id = al.parent_id
	where fa.fine_id = _type_fine and fr.refinancing_rate > 0;

	drop table if exists _old_payment;
	create temp table _old_payment (account_id int, pay numeric(8,2));
		
	insert into _old_payment
	select pd.account_id, sum (pd.sum) as sum
	from payment.list pl 
		inner join payment.detal pd on pd.payment_id = pl.id
	where pl.period_id = _period_id and pl.date < _date_begin
	group by pd.account_id;	

	if exists (select * from _fine_table)
		then 
			begin 
	
				delete from fine.calculation
				where period_id = _period_id and account_id in (select account_id from _fine_table);
			
				with recursive calendar as 
				(
					select _date_begin as t_date
					union all
					select (t_date + 1) as t_date
					from calendar
					where (t_date + 1) <= _date_end
				) 
				insert into _calendar
				select t_date 
				from calendar;
			
				with cte
				as
				(			
				select 
					pb.account_id
					,b.period_id
					,case   
						when  (pb.in_balance - coalesce (op.pay,0)) - sum (b.calc) over (partition by b.account_id order by b.period_id desc, ord asc ) > 0
							then b.calc
						when (b.calc) - (sum (b.calc) over (partition by b.account_id order by b.period_id desc, ord asc ) - (pb.in_balance - coalesce (op.pay,0))) > 0 
							then  (b.calc) - (sum (b.calc) over (partition by b.account_id order by b.period_id desc, ord asc) - (pb.in_balance - coalesce (op.pay,0)))
						else 0.0
					end sum_for_fine
				from (select
						account_id
						,sum(in_balance) as in_balance
					from payment.balance
					where period_id = _period_id and sublist_id <> 7
					group by account_id
					) pb
					inner join 	(select 
										sum(current_calculate) + sum (re_calculate) as calc
										,pb.account_id
										,period_id
										,1 as ord
								 from  payment.balance pb
								 where period_id < _period_id and sublist_id <> 7 
								 group by pb.period_id,pb.account_id
				  				 union all
								 select 
									case when sum (in_balance) > 0.0 then sum(in_balance) else 0.0 end 
									,account_id
									,_active_period - 1
									,2
								 from payment.balance
								 where period_id = _active_period and sublist_id <> 7
								 group by account_id
								 ) b on pb.account_id = b.account_id
				left join _old_payment op on op.account_id = pb.account_id				
				)		
				,cte2	as
				(
				select 
					c.account_id
					,date
					,sum (case when (date - cast ((date_end-ft.free_days) as date)) >= 1 then sum_for_fine else 0 end) sum_for_fine
					,ft.part
					,ft.rate
					,ft.free_days
					,ft.account_parent_id
				from cte c
					inner join _fine_table ft on ft.account_id = c.account_id
					inner join (select id, date_end	from "period".list) pr on pr.id = c.period_id
					cross join _calendar
				group by c.account_id, date, ft.free_days, ft.part, ft.account_parent_id
				)			
				,cte3 as
				(
				select 
					c.*
					,coalesce (sum (p.sum) over (partition by c.account_id order by c.date),0.0) pay
					,case  
						when sum_for_fine - coalesce(sum (p.sum) over ( partition by c.account_id order by c.date),0.0) > 0.0
						then sum_for_fine - coalesce(sum (p.sum) over ( partition by c.account_id order by c.date),0.0)
						else 0.0
					end as sum_fine
				from cte2 c
					left join (select pd.account_id, sum(pd.sum) as "sum", (pl.date + 1) as "date"
		 						from payment.detal pd
									inner join payment.list pl on pl.id = pd.payment_id
								where pl.period_id = _period_id and pl.date >= _date_begin
								group by pd.account_id, pl.date) p on c.account_id = p.account_id and c.date = p.date 
				)
			
			
				insert into fine.calculation
				select distinct
					c.account_id
					,_period_id as period_id
					,min(c.date) over (partition by c.account_id,c.pay, c.sum_fine order by c.account_id) as date_begin 
					,max(c.date) over (partition by c.account_id, c.pay, c.sum_fine order by c.account_id) as date_end
					,c.rate
					,c.sum_fine as sum_fine
					,0.0
					,0.0
					,cast((round(c.rate/part,8)) as numeric (9,8)) as fine_rate
					,0.0
					,0.0
					,((max(c.date) over (partition by c.account_id,c.pay,c.sum_fine order by c.account_id))
						-(min(c.date) over (partition by c.account_id,c.pay,c.sum_fine order by c.account_id))) + 1 as days
					,account_parent_id
				from cte3 c
					inner join _fine_history fh on fh.account_id = c.account_id and c.date between fh.date_begin and fh.date_end
				order by 1,2,3;
		
			end;
	end if;

	drop table if exists _calendar;	
	drop table if exists _fine_table;	
	drop table if exists _old_payment;
	drop table if exists _fine_history; 

end
$_$;
ALTER PROCEDURE fine.calc_legal(IN _account jsonb) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating fine.calc_legal(jsonb)...';END$$;
COMMENT ON PROCEDURE fine.calc_legal(jsonb) IS '=============================================
 Author:		Поляков Павел
 Create date: 17.08.2016
 Description:	Начисления пени для предприятий. Если РСО поставляет для конечных не жилых потребителей. Тогда Пени расчитывается как 1/130 с 1 дня
 Modify: 27.09.2022 (Юркин Е.Ю.) - опять добавил что ставки на все даты в месяце попадают
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating fine.calc(jsonb)...';END$$;
CREATE PROCEDURE fine.calc(IN _account jsonb)
LANGUAGE plpgsql
AS $_$
declare 
	_date_begin		date;
	_date_end		date;
	_period_id		int;
	_parametr_id	int;
	_active_period	int;
begin

	drop table if exists _fine_table; 
	create temp table _fine_table (account_id int not null primary key, free_days int, account_parent_id int);
	alter table _fine_table 
	add constraint _temp_fine_table unique (account_id) include (free_days, account_parent_id);

	drop table if exists _old_payment; 
	create temp table _old_payment  (account_id int, pay numeric (8,2));
	alter table _old_payment 
	add constraint _temp_old_payment unique (account_id, pay); 

	drop table if exists _calendar; 
	create temp table _calendar  ("date" date);
	alter table _calendar 
	add constraint _temp_calendar unique ("date"); 

	drop table if exists _cte1; 
	create temp table _cte1  (account_id int, period_id int , date_end date, free_days int, sum_for_fine numeric(10,2));
	alter table _cte1
	add constraint _temp_cte1 unique (account_id, period_id) include (sum_for_fine, date_end);

	drop table if exists _cte2; 
	create temp table _cte2 (account_id int, date_begin date, date_end date, sum_for_fine31 numeric(9,2), sum_for_fine60 numeric(9,2), sum_for_fine91 numeric(9,2), pay numeric(9,2));
	create index _temp_cte2 on _cte2 (account_id) ;

	drop table if exists _fine_history; 
	create temp table _fine_history (account_id int not null, date_begin date not null, date_end date not null, fine31 numeric (9,8), fine60 numeric(9,8), fine91 numeric(9,8), rate numeric (4,2), account_parent_id int);
	create index _temp_fine_history on _fine_history (account_id, date_begin desc, date_end) include (fine31, fine60, fine91, rate, account_parent_id);

	_active_period = (select id from "period".list where is_active = true);

	select id, date_begin, date_end
	into  _period_id, _date_begin, _date_end
	from "period".list 
	where is_working = true;

	insert into _fine_table(account_id, free_days, account_parent_id)
	select fa.account_id, fr.free_days - 1 as free_days, al.parent_id
	from fine.account fa
		inner join fine.rate fr on fr.list_id = fa.fine_id
		inner join adress.account al on al.id = fa.account_id
		inner join jsonb_populate_recordset(null::account.list, _account) a on a.account_id = al.parent_id;
	
	---- с историей ключевой ставки
	insert into _fine_history (account_id, date_begin, date_end, fine31, fine60, fine91, rate, account_parent_id)
	select 
		fa.account_id, 
		case when fh.date_begin < _date_begin then _date_begin else fh.date_begin end as date_begin,
		case when coalesce(fh.date_end, _date_end) >= _date_end then _date_end else fh.date_end end as date_end,
		round(fh.refinancing_rate / fr.part_refinancing_rate31, 8) as fine31, 
		round(fh.refinancing_rate / fr.part_refinancing_rate60, 8) as fine60, 
		round(fh.refinancing_rate / fr.part_refinancing_rate91, 8) as fine91, 
		fh.refinancing_rate, 
		al.parent_id
	from fine.account fa
		inner join fine.rate fr on fr.list_id = fa.fine_id
		inner join adress.account al on al.id = fa.account_id
		inner join fine.history fh on fh.date_begin <= _date_end and coalesce(fh.date_end, _date_end) >= _date_begin
		inner join jsonb_populate_recordset(null::account.list, _account) a on a.account_id = al.parent_id
	where fr.refinancing_rate > 0;
	
----------------  удаление предыдущего начисления пени --------------------
	delete 
	from fine.calculation fc
	using _fine_table ft
	where ft.account_id = fc.account_id and fc.period_id = _period_id;
	
	insert into _old_payment
	select pd.account_id, sum(pd."sum") as sum
	from payment.list pl 
		inner join payment.detal pd on pd.payment_id = pl.id
	where pl.period_id = _period_id and pl."date" < _date_begin
	group by pd.account_id;
	
	with recursive calendar as (
	select _date_begin as t_date
	union all
	select (t_date + 1) as t_date
	from calendar
	where (t_date + 1) <= _date_end
	) 
	insert into _calendar
	select t_date 
	from calendar;
	
	insert into _cte1 (account_id, period_id, date_end, free_days, sum_for_fine)
	select t.account_id, t.period_id, pl.date_end, ft.free_days, t.sum_for_fine
	from (select pb.account_id, 
				b.period_id,
				case   
					when  ((pb.in_balance - coalesce (op.pay, 0)) - sum (b.calc) over (partition by b.account_id order by b.period_id desc, ord asc )) > 0 
						then b.calc				
					when ((b.calc) - (sum (b.calc) over (partition by b.account_id order by b.period_id desc, ord asc ) - (pb.in_balance - coalesce (op.pay, 0)))) > 0 
						then  ((b.calc) - (sum (b.calc) over (partition by b.account_id order by b.period_id desc, ord asc) - (pb.in_balance - coalesce (op.pay, 0))))
					else 0.0
				end sum_for_fine
			from (select account_id, sum(in_balance) as in_balance
				  from payment.balance
				  where period_id = _period_id and (sublist_id <> 7 or in_balance < 0.0)
				  group by account_id
				  ) pb
					inner join 	(select abs(sum(current_calculate) + sum (recalculate)) as calc, pb.account_id, period_id, 1 as ord
								 from  payment.balance pb
								 where period_id <_period_id and (sublist_id <> 7 or current_calculate + recalculate < 0.0)
								 group by pb.period_id,pb.account_id
								 having abs(sum(current_calculate) + sum (recalculate)) <> 0.0
					  			 	union all
								 select sum(in_balance), account_id, _active_period - 1, 2
								 from payment.balance
								 where period_id = _active_period and (sublist_id <> 7 or in_balance < 0.0)
								 group by account_id
								 having sum (in_balance) > 0.0
								) b on pb.account_id = b.account_id
					left join _old_payment op on op.account_id = pb.account_id
			) t
		inner join "period".list pl on pl.id = t.period_id 
		inner join _fine_table ft on ft.account_id = t.account_id
	where sum_for_fine <>  0.0 and t.period_id <> _period_id - 1;
		
	with cte as	
	(
	select 
		c.account_id
		,cc."date"
		,sum (case when (cc."date" - (date_end + c.free_days)) between 31  and 60 then sum_for_fine else 0 end) sum_for_fine31
		,sum (case when (cc."date" - (date_end + c.free_days)) between 61  and 90 then sum_for_fine else 0 end) sum_for_fine60
		,sum (case when (cc."date" - (date_end + c.free_days)) >= 91 then sum_for_fine else 0 end) sum_for_fine91
		,coalesce (sum (p."sum") over (partition by c.account_id order by cc."date"), 0.0) as pay
	from _cte1 c
		cross join _calendar cc
		left join (select pd.account_id, sum(pd."sum") as "sum", (pl."date" + 1) as "date"
	 			   from payment.detal pd
				   		inner join payment.list pl on pl.id = pd.payment_id
				   where pl.period_id = _period_id and pl."date" >= _date_begin
				   group by pd.account_id, pl."date"
				  ) p on c.account_id = p.account_id and cc."date" = p."date"
	group by c.account_id, cc."date", p."sum" 
	)
	
	insert into _cte2
	select account_id, min("date") as date_begin, max("date") as date_end, sum_for_fine31, sum_for_fine60, sum_for_fine91, pay
	from cte c
	group by account_id, sum_for_fine31, sum_for_fine60, sum_for_fine91,pay;

	insert into fine.calculation (account_id, period_id, date_begin, date_end, ref_rate, sum_for_fine31, sum_for_fine60, sum_for_fine91, rate31, rate60, rate91, count_day, account_parent_id)
	select 
		c.account_id
		,_period_id as period_id
		,case when c.date_begin < fh.date_begin then fh.date_begin else c.date_begin end as date_begin
		,case when c.date_end > fh.date_end then fh.date_end else c.date_end end as date_end
		,fh.rate
		,case
			when sum_for_fine60 + sum_for_fine91 -  c.pay  < 0.0
			then 
				case
					when sum_for_fine31 + sum_for_fine60 + sum_for_fine91 - c.pay > 0.0 
					then sum_for_fine31 + sum_for_fine60 + sum_for_fine91 - c.pay
					else  0.0
				end
			else sum_for_fine31
		end as sum_fine31
		,case
			when sum_for_fine91 - c.pay < 0.0
			then 
				case
					when sum_for_fine60 + sum_for_fine91 - c.pay > 0.0
					then sum_for_fine60  + sum_for_fine91 - c.pay 
					else 0.0
				 end
			else sum_for_fine60
		end as sum_fine60	
		,case  
			when sum_for_fine91 - c.pay > 0.0
			then sum_for_fine91 - c.pay
			else 0.0
		end as sum_fine91
		,fh.fine31
		,fh.fine60
		,fh.fine91
		,(((case when c.date_end > fh.date_end then fh.date_end else c.date_end end) - (case when c.date_begin < fh.date_begin then fh.date_begin else c.date_begin end)) + 1) as days
		,fh.account_parent_id
	from _cte2 c
		inner join _fine_history fh on c.account_id = fh.account_id
				and (c.date_begin between fh.date_begin and fh.date_end or c.date_end between fh.date_begin and fh.date_end)
	order by 1,2,3;
	
	
--------- процедура произведения начисления для предприятий. рсо=> коммерчиские предприятия
	if exists (	select *
				from fine.account fa 
					inner join adress.account aa on aa.id = fa.account_id
					inner join jsonb_populate_recordset(null::account.list, _account) a on a.account_id = aa.parent_id
				where fa.fine_id = (select id from fine.list where lower(name) = 'предприятия')
				fetch first 1 rows only)
		then 
			call fine.calc_legal (_account);
	end if;

	drop table if exists _fine_table; 
	drop table if exists _old_payment; 
	drop table if exists _calendar; 
	drop table if exists _cte1; 
	drop table if exists _cte2; 
	drop table if exists _fine_history; 
			
end
$_$;
ALTER PROCEDURE fine.calc(IN _account jsonb) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating fine.calc(jsonb)...';END$$;
COMMENT ON PROCEDURE fine.calc(jsonb) IS '=============================================
 Author:		Поляков П.Г.
 Create date: 14,05,2015.
 Изменено 17.08.2016. Добавлен интервал 30-60 дней для потребителей "Управялющая компания". РСО => УК. Тагже в конце происходи вызов процедуры начислений для предприятий
 Изменено 10.12.2021.(Сурин) Добавлена отрицательная пеня в расчет. 
 Modify: 27.09.2022 (Юркин Е.Ю.) - опять добавил что ставки на все даты в месяце попадают
 Description:	Процедура начисления пени. 
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating recalculation.save(integer, integer, boolean, integer, jsonb, jsonb, integer)...';END$$;
CREATE PROCEDURE recalculation.save(IN _period_start integer, IN _period_end integer, IN _odn boolean, IN _root_id integer, IN _account jsonb, IN _sublist jsonb, IN _session_id integer)
LANGUAGE plpgsql
AS $_$
declare 
	_period_id 	int;
	_date_begin date;
	_date_end 	date;
	_type 		int;
	_diff 		numeric(5,2);
begin
	begin

		select pl.id, date_begin, date_end 
		into _period_id, _date_begin, _date_end  
		from "period".list pl
			inner join recalculation.root rr on rr.period_id = pl.id 
		where rr.id = _root_id;

		_type = (select "type" from recalculation.root where id = _root_id);
	
		_diff = case when _type in (0,5) then 0.0 else 0.04 end;
		
		if not exists(select 1 from jsonb_populate_recordset(null::account.list, _account) as s limit 1)
			then 
				delete from recalculation."result" where root_id = _root_id;
			else 
				begin
					delete 
					from recalculation."result" rr				
					where rr.root_id = _root_id and exists (select 1 from jsonb_populate_recordset(null::account.list, _account) as a where rr.account_parent_id = a.account_id);
				end;
		end if;

		insert into recalculation."result" (root_id, period_id, house_id, flat_id, account_id, sublist_id, date_begin, date_end, "day", calc_tarif, recalc_tarif, diff_tarif, calc_volume, recalc_volume, diff_volume, calc_result, recalc_result, diff_result, account_parent_id)
		with cte as
		(
			
			select 
				 t.root_id
				,t.period_id
				,t.house_id
				,t.flat_id
				,t.account_id
				,t.sublist_id
				,t.date_begin
				,t.date_end
				,t."day"
				,t.tarif_value as recalc_tarif
				,case when _type = 5 then 0.0 else  coalesce(p.tarif, 0) end calc_tarif
				,case when _type = 5 then 0.0 else  coalesce(t.tarif_value, 0) - coalesce (p.tarif, 0) end diff_tarif
				,case when _type = 5 then coalesce(t.volume_value,0) else  coalesce(t.volume_value,0) end as recalc_volume
				,case when _type = 5 then 0.0 else  coalesce(p.volume, 0) end calc_volume
				,case when _type = 5 then 0.0 else  coalesce(t.volume_value, 0) - coalesce(p.volume, 0) end diff_volume
				,(coalesce(t."result", 0)) recalc_result
				,case when _type = 5 then 0.0 else  (coalesce(p.current_calculate, 0)) end calc_result
				,case when _type = 5 then 0.0 else  sum(coalesce(p.volume,0)) over (partition by t.root_id, t.period_id, t.house_id, t.flat_id, t.account_id, t.sublist_id) - sum(coalesce(t.volume_value, 0)) over (partition by t.root_id, t.period_id, t.house_id, t.flat_id, t.account_id, t.sublist_id) end as sum_volume
				,sum(coalesce(p.current_calculate, 0)) over (partition by t.root_id, t.period_id, t.house_id, t.flat_id, t.account_id, t.sublist_id) - sum(coalesce(t."result",0)) over (partition by t.root_id, t.period_id, t.house_id, t.flat_id, t.account_id, t.sublist_id) as sum_result
				,t.account_parent_id
			from  recalculation.list_preview t
				left join (
							select pb.*, pl.date_begin, pl.date_end
							from payment.balance pb
								inner join "period".list pl on pl.id = pb.period_id
						) p on t.period_id = p.period_id
							and t.account_id = p.account_id 
							and t.sublist_id = p.sublist_id 
							and t.date_begin = p.date_begin
			where root_id = _root_id and t.session_id = _session_id
		) 

		select distinct 
			 root_id::int4
			,period_id::int4
			,house_id::int4
			,flat_id::int4
			,c.account_id::int4
			,c.sublist_id::int4
			,c.date_begin::date
			,c.date_end::date
			,"day"::int4
			,calc_tarif::numeric(9, 2)
			,recalc_tarif::numeric(9, 2)
			,diff_tarif::numeric(9, 2)
			,calc_volume::numeric(11, 5)
			,recalc_volume::numeric(11, 5)
			,diff_volume::numeric(11, 5)
			,calc_result::numeric(9, 2)
			,recalc_result::numeric(9, 2)
			,(recalc_result - calc_result)::numeric(9, 2) as diff_result
			,c.account_parent_id::int4
		from cte c
			inner join jsonb_populate_recordset(null::account.list, _account) a on a.account_id = c.account_parent_id
			inner join jsonb_populate_recordset(null::report.sublist, _sublist) s on s.sublist_id = c.sublist_id
			inner join utility.sublist us on us.id = s.sublist_id
		where ((sum_result not between -_diff and _diff) 
				and s.sublist_id <> 7)
			or (abs(sum_volume) > 0.00001 and us."type" = 1) ;

		delete from recalculation.list_preview where root_id = _root_id and t.session_id = _session_id;
	
		exception 
			when others
				then 
					raise exception 'Ошибка, обратитесь в тех. поддержку.';
	end;		

end
$_$;
ALTER PROCEDURE recalculation.save(IN _period_start integer, IN _period_end integer, IN _odn boolean, IN _root_id integer, IN _account jsonb, IN _sublist jsonb, IN _session_id integer) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating recalculation.parametr_change(boolean, integer, integer)...';END$$;
CREATE PROCEDURE recalculation.parametr_change(IN _type_arh boolean, IN _root_id integer, IN _session_id integer)
LANGUAGE plpgsql
AS $_$
declare 
		_pivot_p		text = '';
		_update 		text = 'set';
		_column			text = '';
		_i_column		text = '';
		_date_begin		date;
		_date_end		date;
		_period_id		int;
		_period_min		int;
		_period_max		int;
		_sql 			text = '';
		_parametr 		text = '';
		_cp_parametr 	text = '';
		_parametr_house	text = '';

begin

	_period_id = (	
					select id 
					from "period".list 
					where id = (select period_id from recalculation.root where id = _root_id)
				);

	delete from parametr.recalculation 				where root_id = _root_id;
	delete from recalculation.parametr_transporate 	where root_id = _root_id;
	delete from recalculation.tarif 				where root_id = _root_id;
	delete from recalculation.normativ 				where root_id = _root_id;
	delete from recalculation.volume 				where root_id = _root_id;
	delete from recalculation.sum_volume 			where root_id = _root_id;

	_pivot_p = '
	with cte
	as
	(
	select 
		rc.account_id
		,rc.period_id
		,rc.date_begin
		,rc.date_end
	';
		
	select _pivot_p ||string_agg(a,'') as a, _update ||string_agg(b ,'') as b
	into _pivot_p, _update
	from (
			select 
				',max(case when short_name = ''' || short_name || ''' then value end) as ' || short_name || '
				' ||
				' ,coalesce(max(case when short_name = ''' || short_name || ''' then is_up end),0) as ' || short_name || '_up 
				' as a
				,' ,' || short_name || ' = case when c.' || short_name || '_up = 1 then c.' || short_name || '::'|| ic.data_type || case 
							when data_type = 'varchar' then '(' || numeric_precision || ')' 
							when data_type = 'numeric' then '(' || numeric_precision || ', ' || numeric_scale || ')' 
							else '' 
						end||' 				else cp.' || short_name || '::' || ic.data_type || case 
							when data_type = 'varchar' then '(' || numeric_precision || ')' 
							when data_type = 'numeric' then '(' || numeric_precision || ', ' || numeric_scale || ')' 
							else '' 
						end || ' end
				' as b
			from recalculation.parametr_for_change rc
				inner join information_schema.columns ic on ic.column_name = rc.short_name  
			where table_name = 'parametr_transporate' and table_schema = 'recalculation'
			group by rc.short_name, data_type, numeric_precision, numeric_scale
		) as rp;
	
	_pivot_p = _pivot_p || '
	from _recalc_period_new rc
		inner join period.list pl on pl.id = rc.period_id
		left join lateral (
								select * , 1 as is_up 
						   		from recalculation.parametr_for_change rp
								where rc.account_id = rp.account_id and ((rc.date_begin  = rp.date_begin and rc.date_end <= rp.date_end) 
												or (rc.date_end = rp.date_end and rp.date_begin <= rc.date_begin) 
												or (rc.date_begin >= rp.date_begin and rc.date_end <= rp.date_end))) r on true  
	' ||  case when _type_arh = true then '' else  'where rc.date_end <> pl.date_end ' end ||
	'group by rc.account_id, rc.period_id, rc.date_begin, rc.date_end)
	
	update recalculation.parametr_transporate as cp
	';

	_update = replace(_update, 'set ,', 'set ');

	_pivot_p = _pivot_p || _update;

	_pivot_p = _pivot_p || 
	'from cte c		
	where cp.account_id = c.account_id and cp.date_begin = c.date_begin and cp.root_id = ' || _root_id;

	select _column || a, _i_column || b
	into _column, _i_column
	from (
			select 
				 string_agg('"' || column_name || '" ' || data_type || 
					case 
						when data_type = 'varchar' then '(' || numeric_precision || ')' 
						when data_type = 'numeric' then '(' || numeric_precision || ', ' || numeric_scale || ')' 
						else '' 
					end , ',') as a
				, string_agg( '"' || column_name || '" ', ',') as b
			from information_schema.columns 
			where table_name = 'parametr_transporate'
				and table_schema = 'recalculation'
				and column_name not in ('date_begin','date_end')
		) d;

/*
	получение списков периодов, в которых изменяется параметр
	и поиск промежутка дат, которые добавятся в данном периоде
*/
	drop table if exists _recalc_period_new; 

	create temp table _recalc_period_new (period_id int, account_id int, date_begin date, date_end date);

	alter table _recalc_period_new
	add constraint un__recalc_period_new unique (account_id, date_begin);

	with cte
	as
	(
		select account_id, date_begin as "date"
		from recalculation.parametr_for_change
		union 
		select account_id, date_end + 1
		from recalculation.parametr_for_change
		union 
		select rp.account_id, pl.date_begin
		from "period".list pl 
		inner join (
						select account_id, date_begin, date_end
						from recalculation.parametr_for_change
						group by account_id, date_begin, date_end
					) rp on  pl.date_begin between rp.date_begin and rp.date_end
						or pl.date_end between rp.date_begin and rp.date_end 
						or rp.date_begin between pl.date_begin and pl.date_end
		union 
		select account_parent_id, date_begin
		from calculation.account_sublist_for_change
		where period_id = _period_id
		union
		select account_parent_id, date_end + 1
		from calculation.account_sublist_for_change
		where period_id = _period_id
	)

	insert into _recalc_period_new
	select
			pl.id
			,t.account_id
			,"date"
			,lead(t."date" - 1, 1, pl.date_end) over (partition by t.account_id order by t.account_id, t."date")
	from cte t
		inner join recalculation.account ra on ra.account_id = t.account_id
		inner join "period".list pl on t."date" between pl.date_begin and pl.date_end
	where ra.session_id = _session_id;

	cluster _recalc_period_new using un__recalc_period_new;	

	select min(period_id), max(period_id)
	into _period_min, _period_max
	from _recalc_period_new;

	_parametr_house = (
						select string_agg(case when pl.catalog_id = 3 then ', ' || column_name else '' end,'')
						from information_schema.columns i
							inner join parametr.list pl on pl.short_name = i.column_name
						where table_name = 'parametr_transporate' and table_schema = 'calculation'
					);
				
	select a,b
	into _parametr,_cp_parametr
	from (	
			select string_agg(case when table_name = 'parametr_transporate' then _parametr || ', ' || column_name else _parametr end,'') as a
					, string_agg(case when table_name = 'parametr_transporate' then _cp_parametr || '
					,cp.' || column_name else _cp_parametr end,'') as b
			from information_schema.columns i
			where table_schema = 'calculation' 
				and i.column_name not in ('id', 'house_id', 'flat_id', 'account_id', 'territory_id')
				and table_name = ('parametr_transporate')
		) d ;

	insert into recalculation.normativ(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
	select _root_id, aa.house_id, aa.flat_id, aa.id, rp.period_id, rp.date_begin, rp.date_end
	from _recalc_period_new rp
		inner join adress.account aa on aa.id = rp.account_id;
	
	insert into recalculation.volume(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
	select _root_id, aa.house_id, aa.flat_id, rp.account_id, rp.period_id, rp.date_begin, rp.date_end
	from _recalc_period_new rp
		inner join adress.account aa on aa.id = rp.account_id;
			
	insert into recalculation.tarif(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
	select _root_id, aa.house_id, aa.flat_id, rp.account_id, rp.period_id, rp.date_begin, rp.date_end
	from _recalc_period_new rp
		inner join adress.account aa on aa.id = rp.account_id;
	
	insert into recalculation.sum_volume(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
	select _root_id, aa.house_id, aa.flat_id, rp.account_id, rp.period_id, rp.date_begin, rp.date_end
	from _recalc_period_new rp
		inner join adress.account aa on aa.id = rp.account_id;
	
	_sql = '
			insert into recalculation.parametr_transporate (root_id, house_id, flat_id, account_id, territory_id, period_id, date_begin, date_end, is_closed_end' || _parametr || ')
			select 
				' || _root_id || '
				,cp.house_id
				,cp.flat_id
				,cp.account_id
				,cp.territory_id
				,rp.period_id
				,rp.date_begin
				,rp.date_end
				,case when cp.is_closed = 1 then true else false end' || _cp_parametr || '
			from calculation.parametr_transporate' || case when _type_arh = true then '_arch ' else '' end || ' as cp 
				inner join _recalc_period_new rp on ' || case when _type_arh = true then 'rp.period_id = cp.period_id and rp.account_id = cp.account_id' 
																					else 'rp.account_id = cp.account_id' end 
			|| case when _type_arh = true then ' where cp.period_id between '|| _period_min || ' and ' || _period_max else '' end;
		
		execute(_sql);

		if nullif(_pivot_p,'')<>'' 
			then 
				execute(_pivot_p);
		end if;

		drop table if exists __account_period;
		
		create temp table __account_period (house_id int, flat_id int, account_id int, period_id int, new_account_id int, date_begin date, date_end date);
	
		with cte as 
		(
			select ai.house_id, ai.flat_id, ra.account_id
			from recalculation.account ra
				inner join adress.info ai on ai.account_id = ra.account_id
			where not exists(select 1 from recalculation.parametr_transporate where account_id = ra.account_id and root_id = _root_id and ra.session_id = _session_id)
				and ra.session_id = _session_id
		)
		
		insert into __account_period
		select 
			 al.house_id as house_id
			,min(al.flat_id) as flat_id
			,min(al.id) as account_id
			,pl.id as period_id
			,c.account_id as new_account_id
			,pl.date_begin
			,pl.date_end
		from cte c
			inner join adress.account al on c.account_id = al.id
			inner join "period".list pl on 1 = 1 and pl.is_open = true
		where pl.id  between _period_min and _period_max
		group by al.house_id, pl.id, c.account_id, pl.date_begin, pl.date_end;

		create index idx_account_periodtemp on __account_period (account_id, period_id) include (house_id, flat_id, new_account_id, date_begin, date_end);

		_sql = '';
		
		if exists((	select 1 
					from recalculation.account ra 
					where not exists(	select 1 
										from recalculation.parametr_transporate 
										where account_id = ra.account_id and root_id = _root_id
									)
						and ra.session_id = _session_id
				))
		then			
			begin
			
			_sql = '
				insert into recalculation.parametr_transporate (root_id, house_id, flat_id, account_id, territory_id, period_id, date_begin, date_end, is_closed_end' || _parametr || ')';
					
			if _type_arh = false
			then 
				begin
					_sql = _sql || '
						select  
							' || _root_id || '
							,cp.house_id
							,a.flat_id
							,a.new_account_id
							,cp.territory_id
							,a.period_id
							,a.date_begin
							,a.date_end
							,case when cp.is_closed = 1 then true else false end
							' ||  _cp_parametr || '
						from calculation.parametr_transporate cp
							inner join __account_period a on cp.account_id = a.account_id
						';

					insert into recalculation.normativ(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
					select _root_id, rp.house_id, rp.flat_id, a.new_account_id, a.period_id, a.date_begin, a.date_end
					from calculation.normativ rp
					inner join __account_period a on a.account_id = rp.account_id;
	
					insert into recalculation.volume(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
					select _root_id, rp.house_id, rp.flat_id, a.new_account_id, a.period_id, a.date_begin, a.date_end
					from calculation.volume rp
						inner join __account_period a on a.account_id = rp.account_id;
	
					insert into recalculation.tarif(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
					select _root_id, rp.house_id, rp.flat_id, a.new_account_id, a.period_id, a.date_begin, a.date_end
					from calculation.tarif rp
						inner join __account_period a on a.account_id = rp.account_id;
	
					insert into recalculation.sum_volume(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
					select _root_id, rp.house_id, rp.flat_id, a.new_account_id, a.period_id, a.date_begin, a.date_end
					from calculation.sum_volume rp
						inner join __account_period a on a.account_id = rp.account_id;

				end;
			end if;
		end;
		else 
			begin
				
				_sql = '
				insert into recalculation.parametr_transporate (root_id, house_id, flat_id, account_id, territory_id, period_id, date_begin, date_end, is_closed_end' || _parametr || ')';

				_sql = _sql || '
					select  
						' || _root_id || '
						,cp.house_id
						,a.flat_id
						,a.new_account_id
						,cp.territory_id
						,a.period_id
						,a.date_begin
						,a.date_end
						,case when cp.is_closed = 1 then true else false end
						' ||  _cp_parametr || '
					from calculation.parametr_transporate_arch cp
						inner join __account_period a on cp.account_id = a.account_id and cp.period_id = a.period_id
						';

				insert into recalculation.normativ(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
				select _root_id, rp.house_id, rp.flat_id, a.new_account_id, a.period_id, a.date_begin, a.date_end
				from calculation.normativ_arch rp
					inner join __account_period a on a.account_id = rp.account_id and rp.period_id = a.period_id;
	
				insert into recalculation.volume(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
				select _root_id, rp.house_id, rp.flat_id, a.new_account_id, a.period_id, a.date_begin, a.date_end
				from calculation.volume_arch rp
					inner join __account_period a on a.account_id = rp.account_id and rp.period_id = a.period_id;
	
				insert into recalculation.tarif(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
				select _root_id, rp.house_id, rp.flat_id, a.new_account_id, a.period_id, a.date_begin, a.date_end
				from calculation.tarif_arch rp
					inner join __account_period a on a.account_id = rp.account_id and rp.period_id = a.period_id;
	
				insert into recalculation.sum_volume(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
				select _root_id, rp.house_id, rp.flat_id, a.new_account_id, a.period_id, a.date_begin, a.date_end
				from calculation.sum_volume_arch rp
					inner join __account_period a on a.account_id = rp.account_id and rp.period_id = a.period_id;

			end;
		
		execute(_sql);
	
		drop table if exists __account_period;

		end if;

		insert into parametr.recalculation (root_id, parametr_id, value, date_begin, date_end)
		select _root_id, parametr_id, value, date_begin, date_end 
		from recalculation.parametr_for_change 
		group by parametr_id, value, date_begin, date_end;

		with cte as 
		(
			select open_day,
					sum(case when is_closed = 1 then  coalesce (date_end, _date_end) - coalesce(date_begin, _date_begin) + 1 end) over (partition by account_id, period_id)  as work_days
			from recalculation.parametr_transporate 
			where root_id = _root_id
		)
	
		update recalculation.parametr_transporate rp
		set open_day = ct.work_days
		from cte ct
		where rp.root_id = _root_id;
	
end
$_$;
ALTER PROCEDURE recalculation.parametr_change(IN _type_arh boolean, IN _root_id integer, IN _session_id integer) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating recalculation.fill_parametr(jsonb, date, date, integer)...';END$$;
CREATE PROCEDURE recalculation.fill_parametr(IN _account jsonb, IN _date_begin date, IN _date_end date, IN _session_id integer)
LANGUAGE plpgsql
AS $_$
begin
	
	create temp table _house (house_id int);

	insert into _house (house_id)
	select distinct al.house_id
	from adress.light_info al
		inner join jsonb_populate_recordset(null::account.list, _account) a on a.account_id = al.account_id;

	create temp table _parametr (parametr_id int, short_name varchar(50));

	insert into _parametr (parametr_id, short_name)
	select pl.id, pl.short_name 
	from parametr.list pl
	where pl.is_calculation = true and not exists(select * from parametr.sublist ps where ps.parametr_id = pl.id);

	delete from recalculation.account where session_id = _session_id;
	delete from recalculation.parametr_for_change;

	insert into recalculation.account
	select a.account_id, _session_id
	from jsonb_populate_recordset(null::account.list, _account) a;

	insert into recalculation.parametr_for_change (house_id, flat_id, account_id, parametr_id, short_name, value, date_begin, date_end)
	select ph.house_id, null::int, null::int, ph.parametr_id, p.short_name, ph.value, _date_begin, _date_end
	from parametr.house ph
		inner join _parametr p on p.parametr_id = ph.parametr_id
		inner join _house h on h.house_id = ph.house_id
	where date_end is null;

	insert into recalculation.parametr_for_change (house_id, flat_id, account_id, parametr_id, short_name, value, date_begin, date_end)
	select null::int, pf.flat_id, null::int, pf.parametr_id, p.short_name, pf.value, _date_begin, _date_end
	from parametr.flat pf
		inner join adress.account aa on aa.flat_id = pf.flat_id
		inner join jsonb_populate_recordset(null::account.list, _account) a on a.account_id = aa.id
		inner join _parametr p on p.parametr_id = pf.parametr_id 
	where date_end is null;

	insert into recalculation.parametr_for_change (house_id, flat_id, account_id, parametr_id, short_name, value, date_begin, date_end)
	select null::int, null::int, pa.account_id, pa.parametr_id, p.short_name, pa.value, _date_begin, _date_end
	from parametr.account pa
		inner join jsonb_populate_recordset(null::account.list, _account) a on a.account_id = pa.account_id
		inner join _parametr p on p.parametr_id = pa.parametr_id 
	where date_end is null;
	
	drop table if exists _house;
	drop table if exists _parametr;
	
end
$_$;
ALTER PROCEDURE recalculation.fill_parametr(IN _account jsonb, IN _date_begin date, IN _date_end date, IN _session_id integer) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating recalculation.create_calc(integer, integer, smallint, integer, integer, jsonb, integer, numeric, text, text)...';END$$;
CREATE PROCEDURE recalculation.create_calc(IN _period_start integer, IN _period_end integer, IN _rules_calculation smallint, IN _re_create_rules integer, IN _root_id integer, IN _sublist jsonb, IN _session_id integer, IN _decimal_value numeric DEFAULT NULL::numeric, IN _numerator text DEFAULT NULL::text, IN _denominator text DEFAULT NULL::text)
LANGUAGE plpgsql
AS $_$
declare
	_period_id				int;
	_date_begin				date;
	_date_end				date;
	_is_input				bool;
	_input_calc_parametr	text = '';
	_sublist_filter			text = '';
	_batch_period_count		int  = 3;
	_existing_group			bool = false;
	_calc_column 			text = '';
	_calc_column_with_type 	text = '';
	_calc_formula 			text = '';
	_number_batch 			int  = 1;
	_sql					text = '';
	_normativ				text = '';
	_rate					text = '';
	_tarif					text = '';
	_volume					text = '';
	_normativ_odn			text = '';
	_tarif_odn				text = '';
	_volume_odn				text = '';
	_period_day				int;
	_tarif_balance			text = '';
	_volume_balance			text = '';
	_normativ_balance		text = '';
	_rate_balance			text = '';
	_sublist_parametr 		text = '';
	_sublist_ot 			text = '';
begin

	create temp table _period  (period_id int, formula_period_id int, date_begin date, date_end date, day_in_month int);
	create temp table _formula_tarif (formula_id int, period_id int, short_name varchar(20), date_begin date, odn bool not null);
	create temp table _formula_normativ (formula_id int, period_id int, short_name varchar(20), date_begin date, odn bool not null);
	create temp table _formula_volume (formula_id int, period_id int, short_name varchar(20), date_begin date, odn bool not null);

	if exists (select * from adress.account where group_id is not null)
		then 
			_existing_group = 1;
	end if;

	select id, date_begin, date_end 
	into _period_id, _date_begin, _date_end 
	from "period".list 
	where is_working = true;
	
	_is_input = (select (case 
			 				when array_to_string(xpath('Root/UI/IsUseInput/text()', p.xml_data)::text[] , '') = '' 
			 				then false::bool 
			 				else array_to_string(xpath('Root/UI/IsUseInput/text()', p.xml_data)::text[], '')::bool 
			 			end)
		 		 from special.parametr p);	

	call recalculation.account_sublist_change (_root_id, _period_start, _period_end, _session_id);

	delete from recalculation.list_preview where root_id = _root_id and session_id = _session_id;

	create temp table _batch_table (period_id int, number_batch int);

	select input_calc_parametr, sublist_filter
	into _input_calc_parametr, _sublist_filter
	from (
			select 
				string_agg('
				"' || pl.short_name || '" = "new_' || pl.short_name || '"',',') as input_calc_parametr, 
				string_agg(SUBSTRING(formula, '([0-9]{1,2})'), ',') as sublist_filter
			from parametr.list pl
				inner join parametr.formula pf on pf.parametr_id = pl."id"
			where pl.catalog_id = 9 and pf.tag_id = 2 and pf.date_end is null
		) param;

		select calc_column, calc_column_with_type, calc_formula 
		into _calc_column, _calc_column_with_type, _calc_formula 
		from (
				select 
					 string_agg(',
					' || pl.short_name, '') as calc_column,
					string_agg(', ' || pl.short_name || ' numeric(' || cast(pl."len" as varchar(3)) || ', ' || cast(pl."precision" as varchar(3)) || ')', '') as calc_column_with_type ,
					string_agg(case when s.short_name is null then '
					,sum(case when cp.is_closed = 1 then ' || pf.formula || ' end)'
					else '
					,sum(case 
							when cp.is_closed_end = false and cp.accountopen = 0 then 0.0 
							else 
								case 
									when ' || s.short_name || ' is null 
									then case when cp.is_closed = 1 then ' || pf.formula || ' else 0.0 end 
									else ' || pf.formula || ' 
								end 
						end)'
					end 
					|| ' over (partition by cp.house_id, cp.period_id' 
					|| case when _is_input = true and il.sublist_id is not null then ', "i_' || cast(us.short_name as varchar(10)) || '"' else '' end 
					|| ' order by cp.house_id, cp.period_id' 
					|| case when _is_input = true and il.sublist_id is not null then ', "i_' || cast(us.short_name as varchar(10)) || '"' else '' end 
					|| ') as "new_' || pl.short_name || '"
					,"cs"."' || pl.short_name || '"','') as calc_formula
				from parametr.list pl
					inner join parametr.formula pf on pf.parametr_id = pl.id
					left join utility.sublist us on us.id = pf.sublist_id
					left join (
									select distinct sublist_id
									from "input".list
								) il on il.sublist_id = us.id
					left join (
									select lower(pl.short_name) as short_name, ps.sublist_id
									from parametr.sublist ps
										inner join parametr.list pl on pl.id = ps.parametr_id
										inner join utility.sublist us on us.id = ps.sublist_id
									where pl.catalog_id = 1 and us.list_id != 1021
									union all
									select distinct coalesce(pl.short_name, 'rasgv') as short_name, coalesce(ps.sublist_id, us.id) as sublist_id
									from utility.sublist us
										left join parametr.sublist ps on us.id = ps.sublist_id and ps.catalog_id = 1
										left join parametr.list pl on pl.id = ps.parametr_id and pl.catalog_id = ps.catalog_id
									where us.list_id = 1021 and us.is_counter = true
								) s on s.sublist_id = us.id
				where pl.catalog_id = 9 and pf.tag_id = 2 and pf.date_end is null 
			) as param;

	with recursive batch_cte as 
	(
		select _period_start as "period", 1 as number_batch, 1 as batch_count
		union all 
		select "period" + 1, case when batch_count = _batch_period_count then number_batch + 1 else number_batch end, case when batch_count = _batch_period_count then 1 else batch_count + 1 end 
		from batch_cte 
		where "period" < _period_end
	)

	insert into _batch_table(period_id, number_batch)
	select "period", number_batch
	from batch_cte;

	while exists(select * from _batch_table) loop
	begin 
		select min(period_id), max(period_id) 
		into _period_start, _period_end 
		from _batch_table 
		where number_batch = _number_batch;

		drop table if exists _period;
 
		create temp table _period  (period_id int, formula_period_id int, date_begin date, date_end date, day_in_month int);
	
		insert into _period (period_id, formula_period_id, date_begin, date_end, day_in_month)
		select id, 
			case when _rules_calculation in (1,3) then _period_id else id end, 
			case when _rules_calculation in (1,3) then _date_begin else date_begin end, 
			case when _rules_calculation in (1,3) then _date_end else date_end end, 
			case when _rules_calculation in (1,3) then (_date_end - _date_begin) + 1 else day_in_month end
		from "period".list where id between _period_start and _period_end;
	
		with cte as
		(
			select
			     f.sublist_id
				,f.period_id
				,f."type"
				,'
				 when cp.period_id = ' || cast(p.period_id as varchar(3)) || ' then ' || 
					case 
						when _decimal_value is not null and f.sublist_id in (select s.sublist_id from jsonb_populate_recordset(null::report.sublist, _sublist) as s) and "type" = 1
						then cast(_decimal_value as varchar(10)) 
							|| case 
									when _denominator is not null then '/nullif(' || _denominator || ', 0)'
									else ''
								end 
						else 
							case 
								when type = 3 
								then 
									case 
										when _numerator is not null and f.sublist_id in (select s.sublist_id from jsonb_populate_recordset(null::report.sublist, _sublist) as s)
										then _numerator  
										else f.formula 
									end 
								else f.formula 
							end
					end as formula
				,row_number() over (partition by f.sublist_id, f."type" order by f.period_id, f."type")  rn
				,count(*) over (partition by f.sublist_id, f."type" order by f.sublist_id, f."type")  cnt
				,p.day_in_month
			from utility.formula_result f
				inner join _period p on p.formula_period_id = f.period_id
			where p.period_id between _period_start and _period_end
		)
		
		select tarif, tarif_odn, normativ, volume, volume_odn
		into _tarif, _tarif_odn, _normativ, _volume, _volume_odn
		from (
				select 
					  string_agg(case 
							when c."type" = 1 and us.is_odn = false
							then 
								case 
									when cnt = 1 then '"t_' || us.short_name || '" = case ' || formula ||  ' end,'
									when cnt <> 1 and rn = 1 then '"t_' || us.short_name || '" = case ' || formula || ' '
									when cnt <> 1 and cnt = rn then formula || ' end, ' 
									else ' ' ||  formula || ' '
								end
							else ''
						end, '') as tarif,
					  string_agg(case 
									when c."type" = 1 and us.is_odn = true
									then 
										case 
											when cnt = 1 then '"t_' || us.short_name || '" = case ' || formula ||  ' end,'
											when cnt <> 1 and rn = 1 then '"t_' || us.short_name || '" = case ' || formula || ' '
											when cnt <> 1 and cnt = rn then formula || ' end, ' 
											else ' ' ||  formula || ' '
										end
									else ''
								end, '') as tarif_odn,
					string_agg(case 
									when c."type" = 2
									then 
										case 
											when cnt = 1 then '"n_' || us.short_name || '" = case ' || formula ||  ' end,'
											when cnt <> 1 and rn = 1 then '"n_' || us.short_name || '" = case ' || formula || ' '
											when cnt <> 1 and cnt = rn then formula || ' end,' 
											else ' ' ||  formula || ' '
										end
									else ''
								end, '') as normativ,
				 	string_agg(case 
									when c."type" = 3 and us.is_odn = false
									then 
										case 
											when cnt = 1 then '"v_' || us.short_name || '" = (case ' || formula ||  ' end) * ((cp.date_end - cp.date_begin) + 1) / pl.day_in_month,'
											when cnt <> 1 and rn = 1 then '"v_' || us.short_name || '" = (case ' || formula || ' '
											when cnt <> 1 and cnt = rn then formula || ' end) * ((cp.date_end - cp.date_begin) + 1) / pl.day_in_month,' 
											else ' ' ||  formula || ' '
										end
									else ''
								end, '') as volume,
					string_agg(case 
									when c."type" = 3 and us.is_odn = true
									then 
										case 
											when cnt = 1 then '"v_' || us.short_name || '" = (case ' || formula ||  ' end) * ((cp.date_end - cp.date_begin) + 1) / pl.day_in_month,'
											when cnt <> 1 and rn = 1 then '"v_' || us.short_name || '" = (case ' || formula || ' '
											when cnt <> 1 and cnt = rn then formula || ' end) / pl.day_in_month * ((cp.date_end - cp.date_begin) + 1),' 
											else ' ' ||  formula || ' '
										end
									else ''
								end,'') as volume_odn
				from cte c
					inner join utility.sublist us on us.id = c.sublist_id
			) as v;
	
		with cte as 
		(
			select 
				us.id as sublist_id,
				pl.period_id,
				coalesce(' when cp.period_id = ' || cast(pl.period_id as varchar(5)) || ' then case ' || 
				(
					select string_agg(' when cp.territory_id = ' || cast(nl.territory_id as varchar(5)) || ' then ' || cast(nl.rate as varchar(10)), '')
					from normativ.list nl
					where nl.sublist_id = us.id
						and pl.date_begin between nl.date_begin and coalesce(nl.date_end, pl.date_end)
						and exists(select * from adress.house where territory_id = nl.territory_id)
					group by nl.sublist_id, nl.rate, territory_id			
				) || ' end', '') as formula
			from _period pl
				inner join utility.sublist us on 1 = 1
			where pl.period_id between _period_start and _period_end 
				and exists (select * from normativ.list where sublist_id = us.id)
		), cte2 as 
		(
			select 
				sublist_id
				,formula
				,row_number() over (partition by c.sublist_id order by c.period_id)  rn
				,count(*) over (partition by c.sublist_id order by c.sublist_id)  cnt
			from cte c
			where formula != ''
		)
	
		select rate
		into _rate
		from (
				select 
					string_agg(case 
									when cnt = 1 
									then '
				"r_' || us.short_name || '" = 
					case 
						' || formula ||  ' 
					end,'
									when cnt <> 1 and rn = 1 then '
				"r_' || us.short_name || '" = 
					case ' || formula || ' '
									when cnt <> 1 and cnt = rn then formula || ' 
					end,' 
									else ' ' ||  formula || ' '
						end, '') as rate
				from cte2 c
					inner join utility.sublist us on us.id = c.sublist_id
			) as t;
	
		_tarif 			= case when _tarif 			= '' then '' else substring(_tarif, 1, length(_tarif) - 1) end;
		_tarif_odn 		= case when _tarif_odn 		= '' then '' else substring(_tarif_odn, 1, length(_tarif_odn) - 1) end;
		_normativ 		= case when _normativ		= '' then '' else substring(_normativ, 1, length(_normativ) - 1) end;
		_normativ_odn 	= case when _normativ_odn 	= '' then '' else substring(_normativ_odn, 1, length(_normativ_odn) - 1) end;
		_volume	 		= case when _volume 		= '' then '' else left(_volume, length(_volume) - 1) end;
		_volume_odn 	= case when _volume_odn 	= '' then '' else substring(_volume_odn, 1, length(_volume_odn) - 1) end;
		_rate 			= case when _rate 			= '' then '' else substring(_rate, 1, length(_rate) - 1) end;
	
		select tarif_balance, normativ_balance, rate_balance, volume_balance 
		into _tarif_balance, _normativ_balance, _rate_balance, _volume_balance
		from(
				select 
					 string_agg(case when fr."type" = 1 then  '
					 	 when ca.sublist_id = ' || cast(us.id as varchar(10)) || ' and cn.period_id = ' || cast(period_id as varchar(10)) || ' then coalesce("t_' || us.short_name || '", 0.0)' else '' end,'') as tarif_balance,
					 string_agg(case when fr."type" = 2 then  '
					 	 when ca.sublist_id = ' || cast(us.id as varchar(10)) || ' and cn.period_id = ' || cast(period_id as varchar(10)) || ' then coalesce("n_' || us.short_name || '", 0.0)' else '' end,'') as normativ_balance,
					 string_agg(case when fr."type" = 2 then case when us."type" = 1 or ut.parent_id = 1 then '
						 when ca.sublist_id = ' || cast(us.id as varchar(10)) || ' and cn.period_id = ' || cast(period_id as varchar(10)) || ' then "r_' || us.short_name || '"' else '' end else '' end,'') as rate_balance,
					string_agg(case when fr."type" = 3 then  '
						 when ca.sublist_id = ' || cast(us.id as varchar(10)) || ' and cn.period_id = ' || cast(period_id as varchar(10)) || ' then coalesce("v_' || us.short_name || '", 0.0)' else '' end,'') as volume_balance
				from utility.sublist us 
					inner join utility."type" ut on ut.id = us."type"
					inner join utility.formula_result fr on fr.sublist_id = us.id
				where fr.period_id between _period_start and _period_end
			) as balance;
		
		_tarif_balance = (case when _tarif_balance != '' then '
		,case' || _tarif_balance || ' 
			else 0.0
		end' else '
		,0.0' end);

		_normativ_balance = (case when _normativ_balance != '' then '
		,case' || _normativ_balance || ' 
			else 0.0
		end' else '
		,0.0' end);

		_rate_balance = (case when _rate_balance != '' then 'case' || _rate_balance || ' 
			else 0.0
		end' else '
		,0.0' end);

		_volume_balance = (case when _volume_balance != '' then '
		,case' || _volume_balance || ' 
			else 0.0
		end' else '
		,0.0' end);

		_sublist_parametr = (
								select string_agg(d,'')
								from (
										select 	'when t.sublist_id = ' || cast(us.id as varchar(4)) || ' and ' || pl.short_name || ' is not null and cp.is_closed = 1 
												then (volume * p.day_in_month / open_day)' as d
										from parametr.list pl
											inner join parametr.sublist ps on ps.parametr_id = pl.id
											inner join utility.sublist us on us.id = ps.sublist_id
										where pl.type_id = 1 and pl.catalog_id = 1 and pl.is_calculation = true and us.is_counter = true
										order by us.id, pl.id
									 ) f
							);

		_sublist_ot = (
							select string_agg(cast(us.id as varchar(4)), ',')
							from utility.sublist us
								inner join utility.formula uf on uf.sublist_id = us.id and uf.date_end is null and uf.formula_type = 3
							where us.list_id = 1022 and coalesce(us.is_odn,false) = false and us."type" = 1 and us.date_end is null and uf.formula ilike '%rasot%'
							group by us.id
						);

		_sublist_parametr = (
								select replace(
													_sublist_parametr, 
													'= 22 and rasxv is not null',
													'in (' || coalesce(
																		(
																			select string_agg(cast(id as varchar(4)), ',') 
																			from utility.sublist 
																			where id in (22,23) and "type" = 1
																		), '22'
																	  ) 
																|| ') and rasxv is not null'
												)
							);

		if exists (select sublist_id from utility.formula where sublist_id = 43 and date_end is null and formula_type = 3)
			then
				begin 
					_sublist_parametr = (
											select replace(
																_sublist_parametr,
																'= 24 and rasgv is not null',
																'in (' || coalesce(
																					(
																						select string_agg(cast(id as varchar(4)), ',') 
																						from utility.sublist 
																						where id in (43,24,41,61) and "type" = 1
																					), '24'
																					) 
																			|| ') and rasgv is not null'
															)
										);
				end; 
			else 
				begin
					_sublist_parametr = (
											select replace(
																_sublist_parametr,
																'= 24 and rasgv is not null',
																'in (' || coalesce(
																					(
																						select string_agg(cast(id as varchar(4)), ',') 
																						from utility.sublist 
																						where id in (23,24,41,61) and "type" = 1 
																					), '24'
																					) 
																				|| ') and rasgv is not null'
														)
										);
				end;
		end if;

		_sublist_parametr = (
								select replace(
												_sublist_parametr,
												'= 38 and rasot is not null',
												'in (' || coalesce(
																	case 
																		when _sublist_ot != '' 
																		then substring(_sublist_ot, 1, length(_sublist_ot) - 1) 
																	end,
																	'38'
																) 
												|| ') and coalesce(hcocall,0) > 0'
												)
							);
	
		_sublist_parametr = (
								select replace(
												_sublist_parametr,
												'= 27 and rasel is not null',
												'in (' || coalesce(
																	(
																		select string_agg(cast(id as varchar(4)), ',') 
																		from utility.sublist 
																		where id in (27,8,31,30) and list_id = 1028 and "type" = 1 
																	), '27'
																) 
															|| ') and rasel is not null'
												)
							);

		_sublist_parametr = (
								select replace(
												_sublist_parametr,
												'= 42 and raselday is not null',
												'in (' || coalesce(
																	(
																		select string_agg(cast(id as varchar(4)), ',') 
																		from utility.sublist 
																		where id in (42,9,33) and "type" = 1 
																	), '42'
																	) 
																|| ') and raselday is not null'
												)
							);

		_sublist_parametr = (
								select replace(
												_sublist_parametr,
												'= 28 and raselnight is not null',
												'in (' || coalesce(
																	(
																		select string_agg(cast(id as varchar(4)), ',') 		
																		from utility.sublist 
																		where id in (28,10,36) and "type" = 1 
																	), '28'
																	) 
																|| ') and raselnight is not null'
												)
							);

		_sublist_parametr = (select case when _sublist_parametr = '' then 'when 1 = 0 then 0.0' else _sublist_parametr end);

	_sql = ' 

create or replace procedure recalculation.calc 
(
	_root_id int,
	_sublist jsonb,
	_session_id int
)
language plpgsql
as $recalculation_calc$
begin
	drop table if exists _temp_balance;

	create temp table _temp_balance (period_id int, date_begin date, date_end date, house_id int not null, flat_id int not null, account_id int not null, 
									sublist_id int not null, is_day bool, account_parent_id int not null
									, tarif ' || case when nullif(_numerator, '') is not null then 'numeric(9,5)' else 'numeric(9,2)' end || ' not null, 
									volume numeric(14,8) not null, normativ numeric(9,5) not null);

	alter table _temp_balance
	add constraint un_temp_balance unique (account_id, sublist_id, period_id, date_begin);
	' ||
	case when _normativ != '' then '
	update recalculation.normativ as cn 
		set ' || _normativ || case when _rate = '' then '' else ',' || _rate end || '
	from recalculation.parametr_transporate cp
		inner join recalculation.account ra on ra.account_id = cp.account_id
	where cn.account_id = cp.account_id and cn.date_begin = cp.date_begin and cn.root_id = cp.root_id and cp.is_closed = 1 and cp.root_id = _root_id 
		and ra.session_id = ' || _session_id || ' and cp.period_id between ' || _period_start || ' and ' || _period_end || ';
	' else '' end || '

	update recalculation.volume as cv 
		set	' || _volume || '
	from recalculation.parametr_transporate cp
		inner join period.list pl on pl.id = cp.period_id
		inner join recalculation.account ra on ra.account_id = cp.account_id
		inner join recalculation.normativ cn on cn.account_id = cp.account_id
			and cn.date_begin = cp.date_begin
			and cn.root_id = cp.root_id			 
	where cv.account_id = cp.account_id	and cv.date_begin = cp.date_begin and cv.root_id = cp.root_id and ra.session_id = ' || _session_id || ' and cp.root_id = _root_id and cp.period_id between ' 
			|| _period_start || ' and ' || _period_end || ';
	';

	if (_calc_formula != '')
		then
			begin
				_sql = _sql || '
				with cte as 
				(
					select 
						 cv.date_begin
						,cv.root_id
						,cv.house_id 
						,cv.account_id' || _calc_formula || ' 
					from recalculation.parametr_transporate cp
						inner join period.list pl on pl.id = cp.period_id
						inner join recalculation.sum_volume cs on cp.account_id = cs.account_id
							and cs.date_begin = cp.date_begin
							and cs.root_id = cp.root_id
						inner join recalculation.volume cv on cp.account_id = cv.account_id
							and cv.date_begin = cp.date_begin
							and cv.root_id = cp.root_id
				';

				if (_is_input = true)
					then
						begin
							_sql = _sql || '
								left join (
									select 
										account_id';
					
							_sql = _sql || (select string_agg('
										,max(case when sublist_id = ' || us.id || ' then input_id end) as "i_' || us.short_name || '"','')
											from utility.sublist us
												inner join (
																select sublist_id
																from "input".list 
																group by sublist_id
															) i on i.sublist_id = us.id
											where is_on = true);
					
							_sql = _sql || '
									from "input".account 
									group by account_id
								) i on i.account_id = cp.account_id';
						end;
				end if;
		
				_sql = _sql || '
					where cp.root_id = _root_id and cp.period_id between ' || _period_start || ' and ' || _period_end || '
				)
				';
			end;
	end if;

	if (_input_calc_parametr != '')
		then
			begin
				_sql = _sql || '
				update recalculation.sum_volume as cv
					set ' || _input_calc_parametr ||  '
				from cte ct
				where cv.date_begin = ct.date_begin and cv.root_id = ct.root_id and cv.account_id = ct.account_id;';
			end;
	end if;
	
	_sql = _sql ||
	case 
		when _volume_odn != '' then '
	update recalculation.volume as cv set
		' || _volume_odn || '
	from recalculation.parametr_transporate cp
		inner join period.list pl on pl.id = cp.period_id
		inner join recalculation.normativ cn on cn.account_id = cp.account_id
			and cn.date_begin = cp.date_begin
			and cn.root_id = cp.root_id
		inner join recalculation.sum_volume sv on sv.account_id = cp.account_id
			and sv.date_begin = cp.date_begin
			and sv.root_id = cp.root_id
	where cv.account_id = cp.account_id and cv.date_begin = cp.date_begin and cv.root_id = cp.root_id and cp.root_id = _root_id and cp.is_closed = 1 and cp.period_id between ' 
		|| _period_start || ' and ' || _period_end || ';' else '' end || '

	update recalculation.tarif as ct 
	set
		' || replace(_tarif, 'house_id', 'cp.house_id') || '
		' || case when _tarif_odn != '' and _tarif != '' then ',' else '' end || replace(_tarif_odn, 'house_id', 'cp.house_id') || '
	from recalculation.parametr_transporate cp
		inner join recalculation.normativ cn on cn.account_id = cp.account_id
			and cn.date_begin = cp.date_begin
			and cn.root_id = cp.root_id
		inner join recalculation.volume cv on cv.account_id = cp.account_id	
			and cv.date_begin = cp.date_begin
			and cv.root_id = cp.root_id
		inner join recalculation.sum_volume c on c.account_id = cp.account_id
			and c.date_begin = cp.date_begin
			and c.root_id = cp.root_id
	where ct.account_id = cp.account_id	and ct.date_begin = cp.date_begin and ct.root_id = cp.root_id and cp.is_closed = 1 and cp.root_id = _root_id and cp.period_id between ' 
		|| _period_start || ' and ' || _period_end || ';

	/*  volume восстанавливаем из volumefact  */

	insert into _temp_balance (period_id, date_begin, date_end, house_id, flat_id, account_id, sublist_id, is_day, account_parent_id, tarif, volume, normativ)
	select 
		cn.period_id
		,cn.date_begin
		,cn.date_end
		,cn.house_id
		,cn.flat_id
		,ca.account_id
		,ca.sublist_id
		,us.is_day
		,cn.account_id
		' || _tarif_balance || _volume_balance || _normativ_balance || '
	from recalculation.normativ cn
		inner join recalculation.volume cv on cv.account_id = cn.account_id
			and cv.date_begin = cn.date_begin
			and cv.root_id = cn.root_id
		inner join recalculation.tarif ct on ct.account_id = cn.account_id
			and ct.date_begin = cn.date_begin
			and ct.root_id = cn.root_id
		inner join recalculation.account ra on ra.account_id = cn.account_id
		inner join calculation.account_sublist ca on ca.account_parent_id = cn.account_id
		inner join utility.sublist us on us.id = ca.sublist_id
	where ra.session_id = ' || _session_id || ' and us.is_on = true and cn.root_id = _root_id and cn.period_id between ' || _period_start || ' and ' || _period_end || ';

	insert into recalculation.list_preview (root_id, period_id, house_id, flat_id, account_id, sublist_id, date_begin, date_end, tarif_value,  volume_value, account_parent_id, session_id)
	select 
		_root_id
		,t.period_id
		,t.house_id
		,t.flat_id
		,t.account_id
		,t.sublist_id
		,t.date_begin
		,t.date_end
		,t.tarif
		,case ' || _sublist_parametr || '
			when t.is_day = true and cp.is_closed = 1 then (volume * p.day_in_month / open_day)
			else 
				case 
					when cp.is_closed = 1 then volume 
					else 0.0 
				end 
		end
		,t.account_parent_id
		,' || _session_id || '
	from _temp_balance t
		inner join recalculation.parametr_transporate cp on cp.account_id = t.account_parent_id
			and cp.date_begin = t.date_begin
		inner join jsonb_populate_recordset(null::report.sublist, _sublist) s on s.sublist_id = t.sublist_id
		inner join period.list p on p.id = cp.period_id
	where root_id = _root_id;

end
$recalculation_calc$;

comment on procedure recalculation.calc is
 ''=============================================
 author:		поляков п.г., глещинский д.в.
 create date: ' || (select current_date ) || '
 description:	процедура расчета
				!!!данная процедура создана автоматически!!!
 =============================================;''

';

		execute  (_sql);

		delete from _batch_table where number_batch = _number_batch;
		delete from _formula_tarif;
		delete from _formula_normativ;
		delete from _formula_volume;
		delete from _period;
		
		_number_batch = _number_batch + 1;
	
	end;	
	end loop;

		drop table if exists _batch_table;
		drop table if exists _formula_tarif;
		drop table if exists _formula_normativ;
		drop table if exists _formula_volume;
		drop table if exists _period;
	
end
$_$;
ALTER PROCEDURE recalculation.create_calc(IN _period_start integer, IN _period_end integer, IN _rules_calculation smallint, IN _re_create_rules integer, IN _root_id integer, IN _sublist jsonb, IN _session_id integer, IN _decimal_value numeric, IN _numerator text, IN _denominator text) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating recalculation.cp_transporate(integer, integer, integer, integer)...';END$$;
CREATE PROCEDURE recalculation.cp_transporate(IN _period_begin integer, IN _period_end integer, IN _root_id integer, IN _session_id integer)
LANGUAGE plpgsql
AS $_$
declare 			
		_column		text= '';
		_column_cp	text= '';
		_sql		text = '';
		_date_begin	date;
		_date_end	date;
		_is_odn		bool;
begin

	_is_odn = (
				select coalesce(odn, false) 
				from recalculation.root 
				where id = _root_id
			  );
	_column_cp = (
					select string_agg('cp.' || column_name, ',') 
	           		from information_schema.columns 
	           		where table_schema = 'calculation' and table_name = 'parametr_transporate_arch' and column_name <> 'id' and column_name <> 'period_id'
	           	 );
	_column = (
				select string_agg(column_name, ',') 
	           	from information_schema.columns 
	           	where table_schema = 'calculation' and table_name = 'parametr_transporate_arch' and column_name <> 'id' and column_name <> 'period_id'
	          );
	
	delete 
	from recalculation.parametr_transporate rp 
	using recalculation.account ra
	where rp.account_id = ra.account_id and root_id = _root_id and ra.session_id = _session_id;
	
	delete 
	from recalculation.tarif rp 
	using recalculation.account ra
	where rp.account_id = ra.account_id and root_id = _root_id and ra.session_id = _session_id;
	
	delete 
	from recalculation.normativ rp 
	using recalculation.account ra
	where rp.account_id = ra.account_id and root_id = _root_id and ra.session_id = _session_id;
	
	delete 
	from recalculation.volume rp 
	using recalculation.account ra
	where rp.account_id = ra.account_id and root_id = _root_id and ra.session_id = _session_id;
	
	delete 
	from recalculation.sum_volume rp 
	using recalculation.account ra
	where rp.account_id = ra.account_id and root_id = _root_id and ra.session_id = _session_id;
	
	_sql = ('
	create temp table _table (period_id int, date_begin date, date_end date);

	create temp table _house (house_id int);
	
	insert into _house
	select distinct house_id 
	from adress.account aa
		inner join recalculation.account ra on ra.account_id = aa.id
	where ra.session_id = ' || _session_id || ';

	insert into _table 
	select id, date_begin, date_end 
	from period.list 
	where id between ' || _period_begin || ' and ' || _period_end || ';

	insert into recalculation.parametr_transporate (' || _column || ', root_id, period_id, date_begin, date_end, open_day, is_closed_end)
	select ' || _column_cp || ', ' || _root_id || ', t.period_id, t.date_begin, t.date_end,  (t.date_end - t.date_begin) + 1, case when cp.is_closed = 1 then true else false end
	from calculation.parametr_transporate_arch cp 
		inner join _table t on t.period_id = cp.period_id' ||
		case when _is_odn = true then '
		inner join _house ai on ai.house_id = cp.house_id' else '
		inner join recalculation.account ra on ra.account_id = cp.account_id
	where ra.session_id = ' || _session_id || ';

	drop table if exists _house;
	drop table if exists _table;
		' end
			);

	insert into recalculation.tarif (root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
	select _root_id, house_id, flat_id, account_id, pl.id, pl.date_begin, pl.date_end
	from recalculation.account ra
		inner join adress.account aa on aa.id = ra.account_id
		inner join "period".list pl on 1 = 1
	where pl.id between _period_begin and _period_end and ra.session_id = _session_id;
	
	insert into recalculation.normativ(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
	select _root_id, house_id, flat_id, account_id, pl.id, pl.date_begin, pl.date_end
	from recalculation.account ra
		inner join adress.account aa on aa.id = ra.account_id
		inner join "period".list pl on 1 = 1
	where pl.id between _period_begin and _period_end and ra.session_id = _session_id;

	insert into recalculation.sum_volume(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
	select _root_id, house_id, flat_id, account_id, pl.id, pl.date_begin, pl.date_end
	from recalculation.account ra
		inner join adress.account aa on aa.id = ra.account_id
		inner join "period".list pl on 1 = 1
	where pl.id between _period_begin and _period_end and ra.session_id = _session_id;

	
	insert into recalculation.volume(root_id, house_id, flat_id, account_id, period_id, date_begin, date_end)
	select _root_id, house_id, flat_id, account_id, pl.id, pl.date_begin, pl.date_end
	from recalculation.account ra
		inner join adress.account aa on aa.id = ra.account_id
		inner join "period".list pl on 1 = 1
	where pl.id between _period_begin and _period_end and ra.session_id = _session_id;

	execute (_sql);
end
$_$;
ALTER PROCEDURE recalculation.cp_transporate(IN _period_begin integer, IN _period_end integer, IN _root_id integer, IN _session_id integer) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating recalculation.account_sublist_change(integer, integer, integer, integer)...';END$$;
CREATE PROCEDURE recalculation.account_sublist_change(IN _root_id integer, IN _period_start integer, IN _period_end integer, IN _session_id integer)
LANGUAGE plpgsql
AS $_$
declare 
		_date_begin	date;
		_date_end	date;
begin

	delete from recalculation.account_sublist where root_id = _root_id;

	if (_period_start != (select id from "period".list where is_working = true))
		then
			insert into recalculation.account_sublist (root_id, period_id, account_id, account_parent_id, sublist_id, value, date_begin, date_end)
			select _root_id, ca.period_id, ca.account_id, ca.account_parent_id, ca.sublist_id, ca.value, pl.date_begin, pl.date_end
			from calculation.account_sublist_arch ca
				inner join recalculation.account ra on ra.account_id = ca.account_parent_id
				inner join (
								select account_id, period_id, date_begin, date_end
								from recalculation.parametr_transporate
								where root_id = _root_id
								group by account_id, period_id, date_begin, date_end
							) pl on pl.account_id = ra.account_id and pl.period_id = ca.period_id
			where ca.period_id between _period_start and _period_end and ra.session_id = _session_id;
		else 
			begin
				select date_begin, date_end 
				into _date_begin, _date_end
				from "period".list 
				where id = _period_start;

				insert into recalculation.account_sublist (root_id, period_id, account_id, account_parent_id, sublist_id, value, date_begin, date_end)
				select _root_id, _period_start, ca.account_id, ca.account_parent_id, ca.sublist_id, ca.value, ca."date", _date_end
				from calculation.account_sublist ca
					inner join recalculation.account ra on ra.account_id = ca.account_parent_id
				where ra.session_id = _session_id
				union all
				select _root_id, _period_start, ca.account_id, ca.account_parent_id, ca.sublist_id, ca.value, ca.date_begin, coalesce(ca.date_end, _date_end)
				from calculation.account_sublist_for_change ca
					inner join recalculation.account ra on ra.account_id = ca.account_parent_id
				where ca.period_id = _period_start and ra.session_id = _session_id;
			end;
	end if;
		
end
$_$;
ALTER PROCEDURE recalculation.account_sublist_change(IN _root_id integer, IN _period_start integer, IN _period_end integer, IN _session_id integer) OWNER TO postgres;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering utility.sublist_house_edit(integer, integer, integer, date, jsonb)...';END$$;
CREATE OR REPLACE PROCEDURE utility.sublist_house_edit(IN _document_id integer, IN _period_begin integer, IN _period_end integer, IN _date_end date, IN _siblist_providers jsonb)
LANGUAGE plpgsql
AS $_$
begin

	if (_document_id is not null)
		then 
			begin

				delete 
				from utility.documents ud
				using jsonb_populate_recordset(null::special.objects, _siblist_providers) s, utility.sublist_provider us
				where us.sublist_id not in (32,34,37) 
						and us.id = s.object_id 
						and ud.sublist_provider_id = s.object_id;
		
				delete 
				from utility.documents ud
				using jsonb_populate_recordset(null::special.objects, _siblist_providers) s,utility.sublist_provider us, utility.sublist_provider sp
				where us.sublist_id in (22,24,27) 
					and us.id = s.object_id 
					and sp.sublist_id = us.sublist_id + 10 
					and sp.provider_id = us.provider_id 
					and sp.territory_id = us.territory_id 
					and sp.house_id = us.house_id 
					and sp.date_end is null
					and ud.sublist_provider_id = sp.id;
		
				delete 
				from utility.documents ud 
				using jsonb_populate_recordset(null::special.objects, _siblist_providers) s, utility.sublist_provider us, utility.sublist_provider sp
				where us.sublist_id in (32,34,37)
						and us.id = s.object_id
						and sp.sublist_id = us.sublist_id - 10 
						and sp.provider_id = us.provider_id 
						and sp.territory_id = us.territory_id 
						and sp.house_id = us.house_id 
						and sp.date_end is null
						and ud.sublist_provider_id = s.object_id;

				insert into utility.documents (sublist_provider_id, document_id, period_begin, period_end)
				select s.object_id, _document_id, _period_begin, _period_end
				from utility.sublist_provider us
					inner join jsonb_populate_recordset(null::special.objects, _siblist_providers) s on s.object_id = us.id
				where us.sublist_id not in (32,34,37);
		
				insert into utility.documents (sublist_provider_id, document_id, period_begin, period_end)
				select sp.id, _document_id, _period_begin, _period_end
				from utility.sublist_provider us
					inner join jsonb_populate_recordset(null::special.objects, _siblist_providers) s on s.object_id = us.id
					inner join utility.sublist_provider sp on sp.sublist_id = us.sublist_id+10 and sp.provider_id = us.provider_id and sp.territory_id = us.territory_id and sp.house_id = us.house_id and sp.date_end is null
				where us.sublist_id in (22,24,27);
				
				insert into utility.documents (sublist_provider_id, document_id, period_begin, period_end)
				select s.object_id, _document_id, _period_begin, _period_end
				from utility.sublist_provider us
					inner join jsonb_populate_recordset(null::special.objects, _siblist_providers) s on s.object_id = us.id
					inner join utility.sublist_provider sp on sp.sublist_id = us.sublist_id-10 and sp.provider_id = us.provider_id and sp.territory_id = us.territory_id and sp.house_id = us.house_id and sp.date_end is null
				where us.sublist_id in (32,34,37);

			end;
	end if;

	update utility.sublist_provider us 
		set	date_end = _date_end
	from jsonb_populate_recordset(null::special.objects, _siblist_providers) s
	where us.sublist_id not in (32,34,37) and s.object_id = us.id;

	update utility.sublist_provider sp 
		set	date_end = _date_end
	from utility.sublist_provider us
		inner join jsonb_populate_recordset(null::special.objects, _siblist_providers) s on s.object_id = us.id		
	where us.sublist_id in (22,24,27)
			and sp.sublist_id = us.sublist_id + 10 
			and sp.provider_id = us.provider_id 
			and sp.territory_id = us.territory_id 
			and sp.house_id = us.house_id 
			and sp.date_end is null;

	update utility.sublist_provider us 
		set	date_end = _date_end
	from jsonb_populate_recordset(null::special.objects, _siblist_providers) s
		inner join utility.sublist_provider sp on sp.date_end is null
	where us.sublist_id in (32,34,37) 
			and s.object_id = us.id
			and sp.sublist_id = us.sublist_id - 10
			and sp.provider_id = us.provider_id
			and sp.territory_id = us.territory_id 
			and sp.house_id = us.house_id;

	update utility.contragent_group_sublist uc
		set date_end = _date_end
	from jsonb_populate_recordset(null::special.objects, _siblist_providers) s
	where uc.sublist_id not in (32,34,37) 
		and s.object_id = uc.sublist_provider_id;

	update utility.contragent_group_sublist cg
		set date_end = _date_end
	from utility.contragent_group_sublist uc
		inner join jsonb_populate_recordset(null::special.objects, _siblist_providers) s on s.object_id = uc.sublist_provider_id
		inner join utility.sublist_provider us on us.id = s.object_id
		inner join utility.sublist_provider sp on sp.sublist_id = us.sublist_id + 10 and sp.provider_id = us.provider_id and sp.territory_id = us.territory_id and sp.house_id = us.house_id and sp.date_end is null
	where uc.sublist_id in (22,24,27) and cg.sublist_provider_id = sp.id;

	update utility.sublist_provider us
		set date_end = _date_end
	from utility.contragent_group_sublist uc
		inner join jsonb_populate_recordset(null::special.objects, _siblist_providers) s on s.object_id = uc.sublist_provider_id
		inner join utility.sublist_provider sp on sp.date_end is null
		inner join utility.contragent_group_sublist cg on cg.sublist_provider_id = sp.id
	where uc.sublist_id in (32,34,37)
			and us.id = s.object_id
			and sp.sublist_id = us.sublist_id - 10 
			and sp.provider_id = us.provider_id 
			and sp.territory_id = us.territory_id 
			and sp.house_id = us.house_id;

end;
$_$;


