DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering tarif.save(integer, character varying, integer, numeric, jsonb, date, boolean, boolean, date, boolean)...';END$$;
CREATE OR REPLACE PROCEDURE tarif.save(IN _tarif_id integer, IN _name character varying, IN _number integer, IN _value numeric, IN _house jsonb, IN _date_begin date, IN _is_update_date_begin boolean, IN _is_update_date_end boolean, IN _date_end date DEFAULT NULL::date, IN _is_update_number boolean DEFAULT false)
LANGUAGE plpgsql
AS $_$
declare 
		_old_value		numeric(10,2);
		_provider_id	int;
		_sublist_id		int;
		_document		varchar(200);
		_is_global		bool;
		_period_begin	date;
		_tarif_id_2 	int; 
		_name_2 		varchar(100);
begin

	_period_begin = (select pl.date_begin from "period".list pl where pl.is_working = true);
	_old_value = (select tl.value from tarif.list tl where tl.id = _tarif_id);
	_tarif_id_2 =(
					select ti.id
					from tarif.list tl 
						inner join tarif.house_tarif th on tl.id = th.tarif_id and coalesce(th.date_end,_period_begin) >= _period_begin
						inner join tarif.list ti on ti.sublist_id = tl.sublist_id+10 and coalesce(tl.document,'') = coalesce(ti.document,'') and coalesce(tl.is_global,false) = coalesce(ti.is_global,false) and tl.provider_id = ti.provider_id and tl.territory_id = ti.territory_id and tl.value = ti.value
						inner join tarif.house_tarif tt on ti.id = tt.tarif_id and coalesce(tt.date_end,_period_begin) >= _period_begin
					where tl.id = _tarif_id and tl.sublist_id in (22,24,27) and th.date_begin = tt.date_begin and th.number = tt.number
					limit 1
				  );

	_name_2 = _name || ' (превыш. платы)';

	if (_old_value != _value)
		then
			begin
				if ((select count(*) from tarif.house_tarif where tarif_id = _tarif_id) = (select count(*) from jsonb_populate_recordset(null::house.list, _house)))
					then
						begin
							update tarif.list 
							set name = _name,
								value = _value
							where id = _tarif_id;
				
							update tarif.house_tarif 
							set date_begin = case when _is_update_date_begin = true then _date_begin else date_begin end,
								date_end = case when _is_update_date_end = true then _date_end else date_end end
							where tarif_id = _tarif_id;
				
							update tarif.list 
							set name = _name_2,
								value = _value
							where id = _tarif_id_2;
		
							update tarif.house_tarif 
							set date_begin = case when _is_update_date_begin = true then _date_begin else date_begin end,
								date_end = case when _is_update_date_end = true then _date_end else date_end end
							where tarif_id = _tarif_id_2;
						end; 
					else
						begin
							select provider_id, sublist_id, "document"
							into _provider_id, _sublist_id, _document
							from tarif.list
							where id = _tarif_id;
				
							update tarif.house_tarif th
							set date_end = (_period_begin - 1)
							from jsonb_populate_recordset(null::house.list, _house) h
							where h.house_id = th.house_id and th.tarif_id = _tarif_id and th.date_end is null;
				
							delete 
							from tarif.house_tarif th
							using jsonb_populate_recordset(null::house.list, _house) h
							where h.house_id = th.house_id and th.tarif_id = _tarif_id and th.date_end < th.date_begin;
				
							update tarif.house_tarif th 
							set date_end = (_period_begin - 1)
							from jsonb_populate_recordset(null::house.list, _house) h
							where h.house_id = th.house_id and th.tarif_id = _tarif_id_2 and th.date_end is null;
				
							delete
							from tarif.house_tarif th
							using jsonb_populate_recordset(null::house.list, _house) h
							where h.house_id = th.house_id and th.tarif_id = _tarif_id_2 and th.date_end < th.date_begin;
				
							call tarif."insert" (_sublist_id, _provider_id, _house, _value, _date_begin, _document, _name, false, _date_end);
						end;
					end if;
			end; 
		else 
			begin
				update tarif.list 
				set name = _name
				where id = _tarif_id;
		
				update tarif.house_tarif th 
				set date_begin = case when _is_update_date_begin = true then _date_begin else date_begin end,
					date_end = case when _is_update_date_end = true then _date_end else date_end end,
					"number" = case when _is_update_number = true then _number else th.number end
				from jsonb_populate_recordset(null::house.list, _house) h
				where h.house_id = th.house_id
					and tarif_id = _tarif_id 
					and th.date_begin = (select max(date_begin) from tarif.house_tarif t where t.house_id = th.house_id and t.tarif_id = th.tarif_id);
		
				update tarif.list 
				set name = _name_2
				where id = _tarif_id_2;
		
				update tarif.house_tarif th 
				set date_begin = case when _is_update_date_begin = true then _date_begin else date_begin end,
					date_end = case when _is_update_date_end = true then _date_end else date_end end,
					number = case when _is_update_number = true then _number else th.number end
				from jsonb_populate_recordset(null::house.list, _house) h
				where h.house_id = th.house_id
					and tarif_id = _tarif_id_2 
					and th.date_begin = (select max(date_begin) from tarif.house_tarif t where t.house_id = th.house_id and t.tarif_id = th.tarif_id);
			end;
	end if;

end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating tarif.save(integer, character varying, integer, numeric, jsonb, date, boolean, boolean, date, boolean)...';END$$;
COMMENT ON PROCEDURE tarif.save(integer, character varying, integer, numeric, jsonb, date, boolean, boolean, date, boolean) IS '=============================================
 Author:		Глещинский Д.В.
 Create date: 29.07.2014
 Description:	Изменение тарифов
 Modify Author: Юркин Е.Ю.
 Modify date: 16.04.2024
 Modify description: Автоматическое изменение тарифов превышения платы
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering tarif.insert(integer, integer, jsonb, numeric, date, character varying, character varying, boolean, date)...';END$$;
CREATE OR REPLACE PROCEDURE tarif.insert(IN _sublist_id integer, IN _provider_id integer, IN _house jsonb, IN _value numeric, IN _date_begin date, IN _document character varying, IN _name character varying DEFAULT NULL::character varying, IN _is_closed_prev_tarif boolean DEFAULT false, IN _date_end date DEFAULT NULL::date)
LANGUAGE plpgsql
AS $_$
declare 
		_sql			text;
		_tarif_id		int;
		_is_global		bool;
		_period_end		date;
		_period_begin	date;
begin

	select date_begin, date_end
	into _period_begin, _period_end 
	from "period".list 
	where is_working = true;

	_is_global = (select up.is_global from utility.provider up where up.id = _provider_id);	

	drop table if exists __house;
	drop table if exists __house_territory;
	drop table if exists __tarifs;
	drop table if exists __tarif_house_id;
	drop table if exists __max_number;

	create temp table __house 			(house_id int not null primary key);
	create temp table __house_territory (house_id int not null primary key, territory_id int);
	create temp table __tarifs 			(tarif_id int not null primary key, territory_id int, sublist_id int);
	create temp table __tarif_house_id 	(id int not null primary key);
	create temp table __max_number 		(house_id int, sublist_id int, max_number int, constraint pk_max_number primary key (house_id, sublist_id));

	insert into __house
	select h.house_id 
	from jsonb_populate_recordset(null::house.list, _house) h;
		
	insert into __house_territory
	select ah.id, ah.territory_id 
	from adress.house ah
		inner join __house h on h.house_id = ah.id;
	
	with cte as
	(
		insert into tarif.list ("name", provider_id, sublist_id, territory_id, value, "document", is_global)
		select _name, _provider_id, _sublist_id, territory_id, _value, _document, _is_global 
		from __house_territory 
		group by territory_id
		union all
		select _name || ' (превыш. платы)', _provider_id, sp.sublist_id, ht.territory_id, _value, _document, _is_global 
		from __house_territory ht
			inner join utility.sublist_provider sp on sp.house_id = ht.house_id 
													and sp.territory_id = ht.territory_id 
													and sp.sublist_id = _sublist_id + 10 
													and sp.provider_id = _provider_id 
													and sp.date_end is null
		where _sublist_id in (22,24,27)
		group by sp.sublist_id, ht.territory_id
		on conflict (territory_id, sublist_id, provider_id, value)
		do update
			set value = excluded.value
		returning id, territory_id, sublist_id
	)
	
	insert into __tarifs
	select *
	from cte;

	if (_is_closed_prev_tarif = true)
		then
			begin
				update tarif.house_tarif th 
				set date_end = (_date_begin - 1)
				from tarif.list tl  
					inner join __house h on true 
				where tl.id = th.tarif_id 
					and h.house_id = th.house_id
					and th.date_end is null 
					and th.date_begin < _period_begin
					and (tl.sublist_id = _sublist_id or (tl.sublist_id = _sublist_id+10 and _sublist_id in (22,24,27)));
			end;
	end if;

	with cte as 
	(
		select tarif_id, territory_id, sublist_id, 
		row_number () over (partition by territory_id, sublist_id order by territory_id, sublist_id, tarif_id asc) rn 
		from __tarifs
	)
	
	delete 
	from __tarifs ts
	using cte ct
	where ct.rn > 1 
		and ct.tarif_id = ts.tarif_id 
		and ct.territory_id = ts.territory_id 
		and ct.sublist_id = ts.sublist_id;

	with cte as 
	(
		insert into tarif.house_tarif (house_id, tarif_id, date_begin, date_end)
		select h.house_id, t.tarif_id, _date_begin, _date_end
		from __house_territory h
			inner join __tarifs t on t.territory_id = h.territory_id
		returning id
	)
	insert into __tarif_house_id
	select *
	from cte;

	insert into __max_number
	select th.house_id, tl.sublist_id, max("number") as mn
	from tarif.list tl
		inner join tarif.house_tarif th on th.tarif_id = tl.id 
	where coalesce(date_end, _date_begin) >= _date_begin	
		and (tl.sublist_id = _sublist_id or (tl.sublist_id = _sublist_id + 10 and _sublist_id in (22,24,27)))
	group by th.house_id, tl.sublist_id;
		
	update tarif.house_tarif tht
	set "number" = coalesce(max_number, 0) + 1
	from __tarif_house_id i
		inner join tarif.list tl on true
		left join __max_number m on m.sublist_id = tl.sublist_id
	where tht.id = i.id	and tl.id = tht.tarif_id and m.house_id = tht.house_id;

	drop table if exists __max_number;
	drop table if exists __tarif_house_id;
	drop table if exists __tarifs;
	drop table if exists __house_territory;
	drop table if exists __house;

end
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating tarif.insert(integer, integer, jsonb, numeric, date, character varying, character varying, boolean, date)...';END$$;
COMMENT ON PROCEDURE tarif.insert(integer, integer, jsonb, numeric, date, character varying, character varying, boolean, date) IS '=============================================
 author:		глещинский д.в.
 create date: 29.07.2014
 description:	создание тарифа тарифов
 Modify Author: Юркин Е.Ю.
 Modify date: 16.04.2024
 Modify description: Автоматическое создание тарифов превышения платы
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering tarif.delete(jsonb)...';END$$;
CREATE OR REPLACE PROCEDURE tarif.delete(IN _house_tarif jsonb)
LANGUAGE plpgsql
AS $_$
declare 
	_period_id		int;
	_period_begin	date;
	_error_message	text;
begin

	select id, date_begin
	into _period_id, _period_begin
	from "period".list 
	where is_working = true;

delete 
from tarif.house_tarif tht
using jsonb_populate_recordset(null::house.tarif_list, _house_tarif) ht, tarif.house_tarif th, tarif.list tl, tarif.list li
where th.date_begin >= _period_begin 
		and tl.sublist_id in (22,24,27) 
		and tht.house_id = th.house_id 
		and tht.number = th.number 
		and tht.date_begin = th.date_begin
		and ht.house_id = th.house_id
		and ht.tarif_id = th.tarif_id
		and ht.number = th.number
		and ht.date_begin = th.date_begin
		and tl.id = ht.tarif_id
		and li.sublist_id = tl.sublist_id + 10 
		and li.value = tl.value 
		and li.provider_id = tl.provider_id 
		and li.territory_id = tl.territory_id 
		and coalesce(li.is_global, false) = coalesce(tl.is_global,false) 
		and coalesce(li.document,'') = coalesce(tl.document,'') 
		and tht.tarif_id = li.id;

	delete 
	from tarif.house_tarif th
	using jsonb_populate_recordset(null::house.tarif_list, _house_tarif) ht, tarif.list tl
	where th.date_begin >= _period_begin
		and ht.house_id = th.house_id
		and ht.tarif_id = th.tarif_id
		and ht.number = th.number
		and ht.date_begin = th.date_begin
		and tl.id = ht.tarif_id;
	
	delete 
	from tarif.list tl
	where not exists (select 1 from tarif.house_tarif th where th.tarif_id = tl.id);

	drop table if exists __tarif;
	create temp table __tarif (tarif_id int not null primary key, name varchar(100), value numeric(10, 2));
	
	insert into __tarif
	select tl.id, tl.name, tl.value
	from tarif.house_tarif th
		inner join jsonb_populate_recordset(null::house.tarif_list, _house_tarif) ht on ht.house_id = th.house_id 
			and ht.tarif_id = th.tarif_id
			and ht.number = th.number
			and ht.date_begin = th.date_begin
		inner join tarif.list tl on tl.id = ht.tarif_id
	where th.date_begin < _period_begin
	union all
	select li.id, li.name, li.value
	from jsonb_populate_recordset(null::house.tarif_list, _house_tarif) ht 
		inner join tarif.house_tarif th on ht.house_id = th.house_id
			and ht.tarif_id = th.tarif_id
			and ht.number = th.number
			and ht.date_begin = th.date_begin
		inner join tarif.house_tarif tht on tht.house_id = th.house_id 
			and tht.number = th.number 
			and tht.date_begin = th.date_begin
		inner join tarif.list tl on tl.id = ht.tarif_id
		inner join tarif.list li on li.sublist_id = tl.sublist_id + 10 
			and li.value = tl.value 
			and li.provider_id = tl.provider_id 
			and li.territory_id = tl.territory_id 
			and coalesce(li.is_global,false) = coalesce(tl.is_global,false) 
			and coalesce(li.document,'') = coalesce(tl.document,'') 
			and tht.tarif_id = li.id
	where th.date_begin < _period_begin and tl.sublist_id in (22,24,27);

	if exists(select * from __tarif)
		then 
			begin
				_error_message =(
									select string_agg(t.d, ', ')
									from (
											select --top 5
												('id: ' || tr.tarif_id || ', Наименование: ' || tr.name || ', Значение: ' || tr.value || chr(10)) as d
											from __tarif tr
											group by tarif_id, name, value
										 ) as t
								);
				
				_error_message = 'Невозможно удалить следующие тарифы:' || chr(10) || _error_message || 'т.к. они созданы в архивном периоде';
				raise notice '%',_error_message;
			end;
	end if;

	drop table if exists __Tarif;
	
end;
$_$;


