DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering recalculation.c_volume(integer, integer, integer, integer)...';END$$;
CREATE OR REPLACE FUNCTION recalculation.c_volume(IN _session_id integer, INOUT _period_start integer, INOUT _period_end integer, INOUT _root_id integer)
RETURNS record
LANGUAGE plpgsql
AS $_$
declare 
	_period_id			int;
	_date_begin			date;
	_date_end			date;
	_min_period			int;
	_min_calc_period_id int;
	_sql 				text = '';
begin
	
	_period_id = (select id from "period".list where is_working = true);
	
	_root_id = null; 
	_min_period = (select min(id) from "period".list where is_open = true);
	
	select date_begin, date_end
	into _date_begin, _date_end  
	from "period".list 
	where id = _period_id;
	
	_min_calc_period_id = (select  coalesce(min(period_id), _period_id) from calculation.parametr_transporate_arch);

	create temp table _counter (account_id int, counter_id int, sublist_id int, value numeric (13,5), c_value numeric (13,5), rate numeric (9,6));
	create temp table _volume_table (root_id int, account_id int, counter_id int, sublist_id int, value numeric(20,10), c_value numeric(20,10), period_id int, flow numeric(20,10), diff numeric(20,10));

--if exists(select 1 from counter.value where c_value <> 0 and [date] between _date_begin and _date_end)
	begin
		_root_id = (select id from recalculation.root where "type" = 2 and period_id = _period_id);
		
		if (_root_id is not null)
			then 
				begin
						delete  
						from recalculation.result rr
						using calculation.account ca
						where ca.account_id = rr.account_id and ca.session_id = _session_id and rr.root_id = _root_id;
						
						delete 
						from recalculation.account 
						where session_id = _session_id;
				end; 
			else
				begin
					insert into recalculation.root ("name", "date", period_id, "type", rules, odn, period_begin, period_end, session_id)
					select 'Корректировка показаний приборов учета', current_date, _period_id, 2, 0, false, _period_id, _period_id, _session_id;
		
					_root_id = (select max(id) from recalculation.root);
				end;
		end if;	

		insert into _counter
		select ca.account_id, ca.counter_id, cf.sublist_id, cf.value, cf.c_value, cf.rate
		from counter.flow cf
			inner join counter.account ca on ca.counter_id = cf.counter_id
			inner join calculation.account cat on cat.account_id = ca.account_id and cat.session_id = _session_id
		where c_value is not null and c_value <> 0.0 and cf.period_id = _period_id;
	
		insert into _volume_table
		select
			_root_id as root_id
			,account_id 
			,t.counter_id
			,c.sublist_id
			,value
			,c_value
			,period_id
			,flow 
			,case 
				when (c_value * c.rate) - sum(flow) over (partition by t.counter_id, t.sublist_id order by period_id desc) > 0 then flow
				when flow - (sum(flow) over (partition by t.counter_id, t.sublist_id order by period_id desc) - (c_value * c.rate)) > 0
					then flow - (sum(flow) over (partition by t.counter_id, t.sublist_id order by period_id desc) - (c_value * c.rate))
				else 0
			end as diff
		from _counter c 
			inner join (
							select cf.counter_id, period_id, flow, cf.sublist_id 
							from counter.flow cf
								inner join _counter c on c.counter_id = cf.counter_id
							where period_id <> _period_id and period_id >= _min_period
						) t on c.counter_id = t.counter_id and c.sublist_id = t.sublist_id;
	
		select min(period_id),max(period_id) 
		into _period_start, _period_end
		from _volume_table 
		where diff > 0.0;
	
		_period_start = (case when _period_start >= _min_calc_period_id then _period_start else _min_calc_period_id end);

		insert into recalculation.account
		select distinct account_id, _session_id 
		from _volume_table 
		where diff >0;
	
		call recalculation.cp_transporate (_period_start, _period_end, _root_id, _session_id); 

		delete 
		from recalculation.tarif as rc
		using recalculation.account ra
		where ra.account_id = rc.account_id
			and exists (	
						select 1
						from recalculation.tarif  rcp
							left join (select account_id, period_id
										from _volume_table 
										where diff > 0.0 
										group by account_id, period_id) v on v.account_id  = rcp.account_id and rcp.period_id = v.period_id
						where rcp.root_id = _root_id and v.account_id is null and rcp = rc
					 )
			and ra.session_id = _session_id;

		delete 
		from recalculation.normativ as rc
		using recalculation.account ra
		where ra.account_id = rc.account_id
			and exists (
						select 1
						from recalculation.normativ  rcp
							left join (select account_id, period_id
										from _volume_table 
										where diff > 0.0
										group by account_id, period_id) v on v.account_id  = rcp.account_id and rcp.period_id = v.period_id
						where rcp.root_id = _root_id and v.account_id is null and rcp = rc 
					 )
			and ra.session_id = _session_id;

		delete 
		from recalculation.volume as rc
		using recalculation.account ra
		where ra.account_id = rc.account_id
			and exists (
						select 1
						from recalculation.volume  rcp
							left join (select account_id, period_id
										from _volume_table 
										where diff > 0.0
										group by account_id, period_id) v on v.account_id  = rcp.account_id and rcp.period_id = v.period_id
						where rcp.root_id = _root_id and v.account_id is null and rcp = rc 
					 )
			and ra.session_id = _session_id;

		delete 
		from recalculation.sum_volume as rc
		using recalculation.account ra
		where ra.account_id = rc.account_id
			and exists (
						select 1
					  	from recalculation.sum_volume  rcp
							left join (select account_id, period_id
										from _volume_table 
										where diff > 0.0
										group by account_id, period_id) v on v.account_id  = rcp.account_id and rcp.period_id = v.period_id
						where rcp.root_id = _root_id and v.account_id is null and rcp = rc
					 )
			and ra.session_id = _session_id;

		delete 
		from recalculation.parametr_transporate as rc
		using recalculation.account ra
		where ra.account_id = rc.account_id
			and exists (
						select 1
					 	from recalculation.parametr_transporate  rcp
							left join (select account_id, period_id
										from _volume_table 
										where diff > 0.0
										group by account_id, period_id) v on v.account_id  = rcp.account_id and rcp.period_id = v.period_id
						where rcp.root_id = _root_id and v.account_id is null and rcp = rc
					 )
			and ra.session_id = _session_id;

		_sql = (select string_agg( '
					update recalculation.parametr_transporate as cp
						 set 
						"' || pl.short_name || '" = "' || pl.short_name || '" - vt.diff
					from (
							select period_id, sublist_id, account_id, root_id, sum(diff) as diff
							from _volume_table
							group by period_id, sublist_id, account_id, root_id) vt 
					where vt.root_id = cp.root_id 
						and vt.account_id = cp.account_id 
						and vt.period_id = cp.period_id 
						and vt.sublist_id = ' || us.id || ' 
						and cp.account_id = ' || t.account_id ,';
					')
				from utility.sublist us
					inner join parametr.sublist ps on ps.sublist_id = us.id
					inner join parametr.list pl on pl.id = ps.parametr_id
					inner join (
									select distinct sublist_id, account_id 
									from _volume_table 
								) t on t.sublist_id = ps.sublist_id
				where pl.catalog_id = 1 and us.is_counter  = true
				);
	
--		execute (_sql);

	end;

	drop table if exists _counter;
	drop table if exists _volume_table;
end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating recalculation.c_volume(integer, integer, integer, integer)...';END$$;
COMMENT ON FUNCTION recalculation.c_volume(integer, integer, integer, integer) IS '=============================================
 author:		поляков п.г., глещинский д.в.
 create date: 06.02.2015
 description:	учет корректировочных показаний в начислениях
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering recalculation.tool(integer, integer, smallint, smallint, jsonb, integer, numeric, text, text, integer)...';END$$;
CREATE OR REPLACE PROCEDURE recalculation.tool(IN _period_start integer, IN _period_end integer, IN _recalculation_type smallint, IN _rules_calculation smallint, IN _sublist jsonb, IN _session_id integer, IN _decimal_value numeric DEFAULT NULL::numeric, IN _numerator text DEFAULT NULL::text, IN _denominator text DEFAULT NULL::text, IN _re_create_rules integer DEFAULT NULL::integer)
LANGUAGE plpgsql
AS $_$
declare
	 _root_id 	int;
	 _period_id int; 
	 _type_arch bool = true;
	 _sublists	jsonb;
	 _account 	jsonb;
	 _time		time;
begin
	
	if exists (select 1
			   from pg_proc pg
					inner join pg_namespace ns on ns."oid" = pg.pronamespace 
				where lower(proname) = 'custom_tool' and lower(ns.nspname) = 'recalculation') 
		then 
			begin
				call recalculation.custom_tool (_period_start, _period_end, _recalculation_type, _rules_calculation, _sublist, _decimal_value, _numerator, _denominator, _re_create_rules, _session_id);
				return;
			end;
	end if;
	
	_period_id = (select id from "period".list where is_working = true);

	if (_period_start = _period_id or _period_end = _period_id) 
		then 
			_type_arch = false;
	end if;

	if (_recalculation_type = 4)
		then 
			_root_id = (select id 
						from recalculation.root 
						where "type" = 4 and _period_id = period_id);
		else 
			_root_id = (select max(id)
						from recalculation.root);
	end if;

	delete 
	from recalculation.account_sublist 
	where root_id = _root_id;

	if _recalculation_type = 0
		then 
			begin
				if exists(select distinct 1 from recalculation.parametr_for_change) 
					then				
						call recalculation.parametr_change (_type_arch, _root_id, _session_id);
					else 
						begin 
							call recalculation.cp_transporate   (_period_start, _period_end, _root_id, _session_id);
						end;
				end if;
			
				call recalculation.create_calc (_period_start, _period_end, _rules_calculation, _re_create_rules, _root_id, _sublist,  _session_id, _decimal_value);
				call recalculation.calc (_root_id, _sublist, _session_id);
			end;
	end if;

	if _recalculation_type = 1
		then 
			begin
				call recalculation.parametr_change  (true, _root_id, _session_id);
				call recalculation.create_calc (_period_start, _period_end, _rules_calculation, _re_create_rules, _root_id, _sublist, _session_id);
				call recalculation.calc (_root_id, _sublist, _session_id);
			end;
	end if;

	if _recalculation_type = 2
		then
			begin
				select c_volume._period_start, c_volume._period_end, c_volume._root_id
				into _period_start, _period_end, _root_id
				from recalculation.c_volume (_session_id, _period_start, _period_end, _root_id);
	
				if (_period_start is not null and _period_end is not null) 
					then
						begin
							
							drop table if exists tests;
							create temp table tests (period_start int, period_end int, rules_calculation smallint, re_create_rules int, root_id int, sublist jsonb);
							insert into tests
							select _period_start, _period_end, _rules_calculation, _re_create_rules, _root_id, _sublist;
							
							
							call recalculation.create_calc (_period_start, _period_end, _rules_calculation, _re_create_rules, _root_id, _sublist, _session_id);
							call recalculation.calc (_root_id, _sublist, _session_id);
						
							_account = (select jsonb_agg(jsonb_build_object('account_id', ra.account_id))
										from recalculation.account ra
										where ra.session_id = _session_id);
		  
							call recalculation.save (_period_start, _period_end, false, _root_id, _account, _sublist, _session_id);
						end;
					end if;
			end; 
	end if;

	if _recalculation_type = 3
		then
			begin
				call recalculation.create_calc (_period_start, _period_end, _rules_calculation, _re_create_rules, _root_id, _sublist, _session_id);
				call recalculation.calc (_root_id, _sublist, _session_id);
			end;
	end if;

	if _recalculation_type = 4
		then
			begin
				call recalculation.parametr_change (false, _root_id, _session_id);
				call recalculation.create_calc (_period_start, _period_end, _rules_calculation, _re_create_rules, _root_id, _sublist, _session_id);
				call recalculation.calc (_root_id, _sublist, _session_id);
			end;
	end if;

	if _recalculation_type = 5
		then
			begin
				if exists(select distinct 1 from recalculation.parametr_for_change) 
					then 
						call recalculation.parametr_change (_type_arch, _root_id, _session_id);
					else				
						call recalculation.cp_transporate (_period_start, _period_end, _root_id, _session_id);
				end if;			
				
				call recalculation.create_calc (_period_start, _period_end, _rules_calculation, _re_create_rules, _root_id, _sublist, _decimal_value, _numerator, _denominator, _session_id);
				call recalculation.calc (_root_id, _sublist, _session_id);
			
			end;
	end if; 

	if (_recalculation_type = 8)
		then 
			begin
				delete 
				from recalculation.account ra
				where ra.session_id = _session_id;

				insert into recalculation.account
				select distinct ca.account_id, _session_id
				from recalculation.contragent_reserve rc
					inner join contragent.account ca on ca.id = rc.contragent_account_id
				where rc.root_id = _root_id;
		
				_sublists = (select jsonb_agg(jsonb_build_object('sublist_id', us.id))
							from utility.sublist us
								inner join utility.type ut on ut.id = us.type
							where us.is_odn = false and (ut.id = 1 or ut.parent_id = 1));

				_account = (select jsonb_agg(jsonb_build_object('account_id', ra.account_id))
						 	from recalculation.account ra
							where ra.session_id = _session_id);

				call recalculation.contragent (_root_id);
				call recalculation.parametr_change (true, _root_id, _session_id);
				call recalculation.create_calc (_period_start, _period_end, _rules_calculation, _re_create_rules, _root_id, _sublists, _session_id);
				call recalculation.calc (_root_id, _sublists, _session_id);
				call recalculation.save (_period_start, _period_end, 0, _root_id, _account, _sublists, _session_id);

			end;
	end if;

end
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating recalculation.tool(integer, integer, smallint, smallint, jsonb, integer, numeric, text, text, integer)...';END$$;
COMMENT ON PROCEDURE recalculation.tool(integer, integer, smallint, smallint, jsonb, integer, numeric, text, text, integer) IS '=============================================
 author:		поляков п.г.
 create date: 10-03-2015
 description:	общая процедура перерасчетов
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering period.open(integer, integer)...';END$$;
CREATE OR REPLACE PROCEDURE period.open(IN _period_id integer, IN _session_id integer)
LANGUAGE plpgsql
AS $_$
declare 
		_period_is_working_id		int;
		_account					jsonb;
		_column						text = '';
		_sql						text;
		_date_begin					date; 
		_date_end					date;
		_normativ_column			text = '';
		_tarif_column				text = '';
		_volume_column				text = '';
		_sum_volume_column			text = '';
		_close_counter_if_overdue	bool; 
		_reset_parametr 			text = '';
		_update_entity 				text = '';
		_reset_column_tarif 		text = '';
		_reset_column_normativ 		text = '';
		_reset_column_volume 		text = '';
		_reset_column_sum_volume 	text = '';
begin
		
	select c.volume_column, c.tarif_column, c.normativ_column, c.sum_volume_column
	into _volume_column, _tarif_column, _normativ_column, _sum_volume_column
	from (
			select 
				 string_agg(case when lower(ic.table_name) = 'volume' then ', ' 	|| ic.column_name else '' end, '') as volume_column 
				,string_agg(case when lower(ic.table_name) = 'tarif' then ', ' 		|| ic.column_name else '' end, '') as tarif_column
				,string_agg(case when lower(ic.table_name) = 'normativ' then ', ' 	|| ic.column_name else '' end, '') as normativ_column
				,string_agg(case when lower(table_name) = 'sum_volume' then ', ' 	|| ic.column_name else '' end, '') as sum_volume_column
			from information_schema."columns" ic
			where lower(ic.table_schema) = 'calculation' and lower(ic.table_name) in ('volume', 'tarif', 'normativ', 'sum_volume')
		) as c;

	_column = (select string_agg(isc.column_name || ',', '') 
				from information_schema."columns" isc
				where lower(isc.table_schema) = 'calculation' and lower(isc.table_name) = 'parametr_transporate_arch' and lower(isc.column_name) <> 'period_id' and lower(isc.column_name) <> 'id');
	
	_sql = '
	insert into calculation.parametr_transporate_arch (' || _column || ' period_id)
		select ' || _column || ' ' || _period_id || ' from calculation.parametr_transporate;
			
	insert into calculation.normativ_arch(period_id' || _normativ_column || ')
		select ' || _period_id || _normativ_column || ' from calculation.normativ;

	insert into calculation.tarif_arch(period_id' || _tarif_column || ')
		select ' || _period_id || _tarif_column || ' from calculation.tarif;

	insert into calculation.volume_arch(period_id' || _volume_column || ')
		select ' || _period_id || _volume_column || ' from calculation.volume;

	insert into calculation.sum_volume_arch(period_id' || _sum_volume_column || ')
		select ' || _period_id || _sum_volume_column || ' from calculation.sum_volume;';

	execute(_sql);

	insert into calculation.account_sublist_arch (period_id, house_id, account_id, account_parent_id, sublist_id, value, "date")
	select _period_id, cas.house_id, cas.account_id, cas.account_parent_id, cas.sublist_id, cas.value, cas."date"
	from calculation.account_sublist cas;

	------- Закрытие тарифов по домам, которые закрыты 3 и более месяцев подряд.
	create temp table _house_tarif (house_id int, tarif_house int);

	insert into _house_tarif (house_id, tarif_house)
	select cp.house_id, th.id
	from calculation.parametr_transporate cp
		inner join "period".list pl on pl.is_working = true
		inner join calculation.parametr_transporate_arch ca on ca.account_id = cp.account_id 
		inner join tarif.house_tarif th on th.house_id = cp.house_id 
		inner join tarif.list tl on tl.id = th.tarif_id
	where ca.period_id between (pl.id - 3) and pl.id 
		and th.date_end is null 
		and th.date_begin < pl.date_end
	group by cp.house_id, th.id
	having max(cp.house_open) + max(ca.house_open) = 0 and count(distinct ca.period_id) >= 2;

	if exists (select * from _house_tarif)
		then
			begin
				
				update tarif.house_tarif th 
					set date_end = pl.date_end 
				from _house_tarif ht 
					inner join "period".list pl on pl.is_working = true
				where ht.house_id = th.house_id 
					and ht.tarif_house = th.id 
					and th.date_end is null 
					and th.date_begin < pl.date_end;
				
			end;
	end if;

	drop table if exists _house_tarif;

	_period_is_working_id = (select pl."id" from "period".list pl where pl.is_working = true);

	if _period_is_working_id is null   --находим первый период
		then
			_period_is_working_id = (select pl."id" from "period".list pl where pl.is_open = true order by pl."id" limit 1);
		else --обнуляем текущий и находим следующий период
			begin	
				_period_is_working_id = (select pl."id" from "period".list pl where pl.is_working = true);
			
				update "period".list 
					set is_working = false;
		
				_period_is_working_id = (select pl."id" from "period".list pl where pl."id" > _period_is_working_id order by pl.id limit 1);
			end;
	end if;

	update period.list pl
	set
		is_working = true,
		is_open = true,
		date_open = current_date
	where pl."id" = _period_is_working_id;

	_account=(select jsonb_agg(jsonb_build_object('account_id', aa.id)) 
				from adress.account aa
				where aa.parent_id is null);

	_date_begin = (select pl.date_begin from period.list pl where pl.id = _period_is_working_id);
	_date_end = (select cast (_date_begin + interval '1 month' as date));
		
	----- закрытие счетчиков у которых закрыты лс
	update counter.list cl 
		set active = false
			,date_end = _date_begin - 1
	from calculation.parametr_transporate cp
		inner join counter.account ca on ca.account_id = cp.account_id
	where cl.id = ca.counter_id and is_closed = 0 and cl.active = true;

	------ сдвиг даты поверки счетчиков, заканчивающихся в 2020 на 01.01.2021
	update counter.list cl
		set verification_date = cast(('2021-01-01'::date - interval '1 year'*cl.verification_interval) as date)
	where cl.date_end is null and cl.active = true and cl.verification_interval is not null and cl.verification_date is not null 
				and (verification_date+interval '1 year'*verification_interval) between '2020-01-01'::date and '2020-12-31'::date;

	-------- закрываем счетчики у которых вышла дата поверки более 3-х месяцев назад (кроме электроэнергии)
	create temp table _close_counter_id (counter_id int, verification_interval int, verification_date date, failure_date date, sublist_id int, account_id int, close_type varchar(50));

	insert into _close_counter_id
	select cl.id, cl.verification_interval, cl.verification_date, cl.failure_date, cl.sublist_id, ca.account_id, 'После трех месяцев с даты поверки' as close_type
	from counter.list cl
		inner join utility.sublist us on us.id = cl.sublist_id and us.list_id != 1028
		left join counter.account ca on ca.counter_id = cl.id
	where cl.active = true and cl.date_end is null
		and (cl.verification_date + interval '1 year'*cl.verification_interval) < _date_begin
		and (date_part('month' ,_date_begin) - date_part('month' ,(cl.verification_date + interval '1 year'*cl.verification_interval))) > 3;
	
	/* добавлены счетчики с проставленной датой выхода из строя */
	insert into _close_counter_id
	select cl.id, cl.verification_interval, cl.verification_date, cl.failure_date, cl.sublist_id, ca.account_id, 'После трех месяцев с даты выхода из строя' as close_type
	from counter.list cl
		inner join utility.sublist us on us.id = cl.sublist_id and us.list_id != 1028
		left join counter.account ca on ca.counter_id = cl.id
	where not exists (select * from _close_counter_id ci where ci.counter_id = cl.id)
		and cl.active = true and cl.date_end is null
		and (cl.failure_date + interval '3 month') < _date_begin;

 	_close_counter_if_overdue = (select (case 
						 					when array_to_string(xpath('Root/Calculation/CloseCounterIfOverdue/text()', p.xml_data)::text[] , '')='' 
						 					then 'true' 
						 					else array_to_string(xpath('Root/Calculation/CloseCounterIfOverdue/text()', p.xml_data)::text[], '') 
						 				end)::bool
					 			 from special.parametr p);
	
	if _close_counter_if_overdue = true
		then
			insert into _close_counter_id
			select cl.id, cc.verification_interval, cc.verification_date, cl.failure_date, cl.sublist_id, ca.account_id, 'Все счетчики по услуге если просрочен хотя бы один' as close_type
			from _close_counter_id cc
				inner join counter.account ca on ca.account_id = cc.account_id
				inner join counter.list cl on cl.sublist_id = cc.sublist_id and cl.id = ca.counter_id 
			where not exists (select * from _close_counter_id ci where ci.counter_id = cl.id) and cl.active = true and cl.date_end is null and cl.date_begin < _date_begin;
	end if;

	update counter.list cl
		set active = false,
			date_end = (_date_begin-1)
	from _close_counter_id c 
	where c.counter_id = cl.id;

	---- сохранение id и Period_ID закрытых счетчиков для отката

	merge into counter.closed_verification_date as target 
	using (
			select 
					 cc.counter_id 
					,_period_id as period_id
					,cc.verification_interval
					,cc.verification_date
					,cc.failure_date
					,cc.sublist_id
					,cc.account_id
					,cc.close_type
			from _close_counter_id cc
		)
	as source (counter_id, period_id, verification_interval, verification_date, failure_date, sublist_id, account_id, close_type)
	on (target.counter_id = source.counter_id)
	when matched then
		update set
			period_id = source.period_id,
			verification_interval = source.verification_interval,
			verification_date = source.verification_date,
			failure_date = source.failure_date,
			sublist_id = source.sublist_id,
			account_id = source.account_id,
			close_type = source.close_type
	when not matched then
		insert (counter_id, period_id, verification_interval, verification_date, failure_date, sublist_id, account_id, close_type)
		values (source.counter_id, source.period_id, source.verification_interval, source.verification_date, source.failure_date, source.sublist_id, source.account_id, source.close_type);
	
	_reset_parametr = (select string_agg('
						"' || pl.short_name || '" = null,','') 
					from parametr.sublist ps
						inner join parametr.list pl on pl.id = ps.parametr_id
					where pl.is_calculation = true);

	_reset_parametr = (select string_agg('
						"' || "name" || '" = null,','')
					from parametr.input_sublist);

	_reset_parametr = (select string_agg(coalesce('
							"' || short_name || '" = ' || 
								case 
									when type_id = 3 then case when default_value = null then 'null' else '' || default_value || '' end
									when type_id = 4 then case when default_value = null then 'null' else '' || default_value || '' end
									else coalesce(default_value, 'null')
								end || ',',''),'')
						from parametr.list
						where is_reset = true);

	if (coalesce(_reset_parametr, '') != '')
		then
			begin
				_reset_parametr = (select 'update calculation.parametr_transporate set ' || substring(_reset_parametr, 1, length(_reset_parametr) - 1));
				execute(_reset_parametr);
			end;
	end if;

	_update_entity = (select string_agg('
						insert into ' || pc.p_table || ' (parametr_id, ' || pc.p_table_id || ', value, date_begin) 
						select ' || pl.id || ', id, ' || 
							case 
								when coalesce(pl.default_value, '') = '' 
								then 'null' 
								else pl.default_value 
							end || ', ''' || _date_begin || ''' from ' || pc.parent_table  || case when pl.catalog_id != 1 then '' else ' where parent_id is null' end,';')
						from parametr.list pl
							inner join parametr.catalog pc on pc.id = pl.catalog_id
						where is_reset = true and not exists(select * from parametr.sublist s where s.parametr_id = pl.id));

	if (coalesce(_update_entity, '') <> '') 
		then
			execute(_update_entity);
	end if;

	insert into counter.flow (counter_id, period_id, prev_value, value, c_value, flow_type_id, sublist_id, rate, prev_date, date)
	select counter_id, _period_is_working_id, coalesce(value, prev_value), null, 0.0, 0, cf.sublist_id, cf.rate, coalesce(date, prev_date), null
	from counter.flow cf
		inner join counter.list cl on cf.counter_id = cl.id
	where period_id = _period_id and coalesce(cl.date_end, _date_end) >= _date_end;

	_reset_column_tarif = (select string_agg('
								"' || column_name || '" = null,' ,'')
							from information_schema.columns
							where lower(table_name) = 'tarif' and lower(table_schema) = 'calculation'
								and lower(is_nullable) = 'yes');

	_reset_column_normativ = (select string_agg('
								"' || column_name || '" = null,','') 
							from information_schema.columns
							where lower(table_name) = 'normativ' and lower(table_schema) = 'calculation'
								and lower(is_nullable) = 'yes');

	_reset_column_volume = (select string_agg('
								"' || column_name || '" = null,','') 
							from information_schema.columns
							where lower(table_name) = 'volume' and lower(table_schema) = 'calculation'
								and lower(is_nullable) = 'yes');

	_reset_column_sum_volume = (select string_agg('
									"' || column_name || '" = null,' ,'')
								from information_schema.columns
								where lower(table_name) = 'sum_volume' and lower(table_schema) = 'calculation'
									and lower(is_nullable) = 'yes');

	_reset_column_tarif = substring(_reset_column_tarif, 1, length(_reset_column_tarif) - 1);
	_reset_column_normativ = substring(_reset_column_normativ, 1, length(_reset_column_normativ) - 1);
	_reset_column_volume = substring(_reset_column_volume, 1, length(_reset_column_volume) - 1);
	_reset_column_sum_volume = substring(_reset_column_sum_volume, 1, length(_reset_column_sum_volume) - 1);

	_sql = '
			update calculation.tarif set ' || _reset_column_tarif || ';
			update calculation.normativ set ' || _reset_column_normativ || ';
			update calculation.volume set ' || _reset_column_volume || ';
			update calculation.sum_volume set ' || _reset_column_sum_volume||';';

	execute(_sql);

	call calculation.tool (true, _session_id, _account);


	insert into "1c".pko ("period_id","house_id","sublist_id","organization_guid","organization_name","customers_guid","customers_name","contract_guid","contract_name","cash_guid","cash_name","cash_flow_guid","cash_flow_name","cash_customer_guid","cash_customer_name","debt_guid","debt_name","type_pko","rs_guid","rs_name","is_active",nomenclature, nomenclature_guid)
	select _period_is_working_id,"house_id","sublist_id","organization_guid","organization_name","customers_guid","customers_name","contract_guid","contract_name","cash_guid","cash_name","cash_flow_guid","cash_flow_name","cash_customer_guid","cash_customer_name","debt_guid","debt_name","type_pko","rs_guid","rs_name","is_active",nomenclature, nomenclature_guid
	from "1c".pko
	where period_id = _period_id;

	update utility.sublist_group_a_detail 
		set period_id = null
	where period_id < _period_is_working_id;

	drop table if exists _close_counter_id;		
		
end
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating period.open(integer, integer)...';END$$;
COMMENT ON PROCEDURE period.open(integer, integer) IS '=============================================
 author:		ооо жилфондсервис
 create date: 24.07.2014
 description:	открытие нового периода
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering period.close(boolean)...';END$$;
CREATE OR REPLACE PROCEDURE period.close(IN _save_payments boolean DEFAULT true)
LANGUAGE plpgsql
AS $_$
declare 
	_period_id			int;
	_date_begin			date;
	_date_end			date;
	_sql				text = '';
	_parametr			text = '';
	_tarif_column		text = '';
	_volume_column		text = '';
	_sum_volume_column	text = '';
	_normativ_column	text = '';
begin
	
	create temp table _recalc	(root_id int);
	create temp table _document	(document_id int);
	create temp table _counter	(counter_id int);

	select volume_column, tarif_column, normativ_column, sum_volume_column
	into _volume_column, _tarif_column, _normativ_column, _sum_volume_column
	from (
			select 
				 string_agg(case when lower(ic.table_name) = 'volume' 		then ', ' || ic.column_name else '' end,'') as volume_column
				,string_agg(case when lower(ic.table_name) = 'tarif' 		then ', ' || ic.column_name else '' end,'') as tarif_column
				,string_agg(case when lower(ic.table_name) = 'normativ' 	then ', ' || ic.column_name else '' end,'') as normativ_column
				,string_agg(case when lower(ic.table_name) = 'sum_volume' 	then ', ' || ic.column_name else '' end,'') as sum_volume_column
			from information_schema."columns" ic
			where lower(ic.table_schema) = 'calculation' and lower(ic.table_name) in ('volume', 'tarif', 'normativ', 'sum_volume')
		) as _column;

	_volume_column 		= substring(_volume_column from 2);
	_tarif_column 		= substring(_tarif_column from 2);
	_normativ_column 	= substring(_normativ_column from 2);
	_sum_volume_column	= substring(_sum_volume_column from 2);

	select pl.id, pl.date_begin, pl.date_end 
	into _period_id, _date_begin, _date_end
	from "period".list pl 
	where pl.is_working = true;

	insert into _recalc
	select rr.id 
	from recalculation.root rr 
	where rr.period_id = _period_id;

	insert into _document
	select cod.id 
	from contragent.owner_documents cod 
	where cod.date_begin >= _date_begin;

	insert into _counter (counter_id)
	select cl.id 
	from counter.list cl 
	where cl.date_begin >= _date_begin;

	-------- открываем счетчики, после procedure [period].[open] у которых вышла дата поверки более 3-х месяцев назад
	update counter.list cl
	set active = true,
		date_end = null
	from  counter.closed_verification_date cvd 
	where cvd.counter_id = cl.id and cvd.period_id = _period_id;
	
	delete 
	from counter.closed_verification_date cd
	where cd.period_id = _period_id;

	--очистка документов
	delete 
	from contragent.owner_documents cod 
	where cod.id in (select d.document_id from _document d);

	--очистка перерасчетов
	delete from parametr.recalculation pr 				where pr.root_id in (select r.root_id from _recalc r);
	delete from recalculation.list_preview;
	delete from recalculation.parametr_transporate rpt	where rpt.root_id in (select r.root_id from _recalc r);
	delete from recalculation."result" rr 				where rr.root_id in (select r.root_id from _recalc r);
	delete from recalculation.normativ rn 				where rn.root_id in (select r.root_id from _recalc r);
	delete from recalculation.tarif rt 					where rt.root_id in (select r.root_id from _recalc r);
	delete from recalculation.volume rv 				where rv.root_id in (select r.root_id from _recalc r);
	delete from recalculation.sum_volume rsv 			where rsv.root_id in (select r.root_id from _recalc r);
	delete from recalculation.root rr 					where rr.id in (select r.root_id from _recalc r);
		
	--очистка параметров
	delete from parametr.house ph where ph.date_begin between _date_begin and _date_end;
	delete from parametr.flat pf where pf.date_begin between _date_begin and _date_end;
	delete from parametr.account pa where pa.date_begin between _date_begin and _date_end;
	delete from calculation.parametr_transporate;
	delete from calculation.tarif;
	delete from calculation.normativ;
	delete from calculation.volume;
	delete from calculation.sum_volume;
		
	update parametr.account pa 
	set date_end = null
	where pa.date_end between _date_begin and _date_end;

	update parametr.flat pf 
	set	date_end = null
	where pf.date_end between _date_begin and _date_end;

	update parametr.house ph 
	set	date_end = null
	where ph.date_end between _date_begin and _date_end;

	_parametr = (
					select string_agg(', ' || i.column_name, '') 
					from information_schema."columns" i
						inner join parametr.list pl on pl.short_name = i.column_name 
					where lower(i.table_schema) = 'calculation' and lower(i.table_name) = 'parametr_transporate'
				);

	--очитска счетчиков
	delete 
	from counter.verification_history cv
	using counter.list cl 
	where cl.id = cv.counter_id and cl.date_begin >= _date_begin;
			
	delete from counter.flow cf where cf.period_id = _period_id;
	delete from counter.flow cf where cf.counter_id in (select c.counter_id from _counter c);

	delete from counter.account ca where ca.counter_id in (select c.counter_id from _counter c);
	delete from counter.flat cf where cf.counter_id in (select c.counter_id from _counter c);
	delete from counter.house ch where ch.counter_id in (select c.counter_id from _counter c);

	delete from counter.list cl where cl.date_begin >= _date_begin;

	_sql= _sql ||('
					insert into calculation.parametr_transporate (house_id, flat_id, account_id, territory_id' || _parametr || ')
					select house_id, flat_id, account_id, territory_id' || _parametr ||' 
					from calculation.parametr_transporate_arch
					where period_id = ' || (_period_id - 1) || ';
						
							
					insert into calculation.normativ(' || _normativ_column || ')
						select ' || _normativ_column || ' from calculation.normativ_arch
						where period_id = ' || (_period_id - 1) || ';
				
					insert into calculation.tarif(' || _tarif_column || ')
						select ' || _tarif_column || ' from calculation.tarif_arch
						where period_id = ' || (_period_id - 1) || ';
				
					insert into calculation.volume(' || _volume_column || ')
						select ' || _volume_column || ' from calculation.volume_arch
						where period_id = ' || (_period_id - 1) || ';
				
					insert into calculation.sum_volume(' || _sum_volume_column || ')
						select ' || _sum_volume_column || ' from calculation.sum_volume_arch
						where period_id = ' || (_period_id - 1) 
					) || ';';

	execute(_sql);

	alter table calculation.account_sublist disable trigger insert_account_sublist_edit;

	delete from calculation.account_sublist;

	insert into calculation.account_sublist (account_id, house_id, account_parent_id, sublist_id, value, "date")
	select ca.account_id, ca.house_id, ca.account_parent_id, ca.sublist_id, ca.value, ca."date"
	from calculation.account_sublist_arch ca
	where ca.period_id = (_period_id - 1);

	alter table calculation.account_sublist enable trigger insert_account_sublist_edit;

	delete from calculation.parametr_transporate_arch cpa 	where cpa.period_id = (_period_id - 1);
	delete from calculation.normativ_arch cna 				where cna.period_id = (_period_id - 1);
	delete from calculation.volume_arch cva 				where cva.period_id = (_period_id - 1);
	delete from calculation.tarif_arch cta 					where cta.period_id = (_period_id - 1);
	delete from calculation.sum_volume_arch csva 			where csva.period_id = (_period_id - 1);
	delete from calculation.account_sublist_for_change cfc 	where cfc.period_id = (_period_id - 1);
	delete from calculation.account_sublist_arch csa 		where csa.period_id = (_period_id - 1);
		

	update "period".list pl 
		set is_working = false,
			is_open = false,
			date_open = null
	where pl.id = _period_id;

	update "period".list pl 
		set is_working = true,
			is_open = true
	where pl.id = _period_id - 1;

	--сохранение или очистка платежей
	if(_save_payments = true)
		then
			update "1c".pko pk
			set period_id = _period_id - 1
			where pk.period_id = _period_id;
		else
			begin
				delete from "1c".pko pk 			where pk.period_id = _period_id;
				delete from payment.detal pd 		where pd.payment_id in (select pl.id from payment.list pl where pl.period_id = _period_id);
				delete from payment.group_detal pg 	where pg.payment_id in (select pl.id from payment.list pl where pl.period_id = _period_id);
				delete from bank.registry_payment r where r.payment_id in (select pl.id from payment.list pl where pl.period_id = _period_id);
				delete from payment.list pl 		where pl.period_id = _period_id;
				delete from bank.registry_batch r 	where r.batch_id in (select pb.id from payment.batch pb where pb.period_id = _period_id);
				delete from payment.batch pb 		where pb.period_id = _period_id;
			end;
	end if;

	-- чистим баланс за закрываемый период
	delete 
	from payment.balance pb
	where pb.period_id = _period_id;
	
	drop table if exists _recalc;
	drop table if exists _document;
	drop table if exists _counter;
	
end
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating period.close(boolean)...';END$$;
COMMENT ON PROCEDURE period.close(boolean) IS '=============================================
 author:		глещинский д.в.
 create date: 05.02.2015
 modified:	02.04.2019 трофимов б.и. - сохранение платежей по запросу пользователя
 modified:	25.09.2019 трофимов б.и. - перенес расщепление платежей на клиент
 description:	закрытие периода
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Dropping recalculation.list_preview.result...';END$$;
ALTER TABLE recalculation.list_preview DROP COLUMN result;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Dropping recalculation.list_preview.day...';END$$;
ALTER TABLE recalculation.list_preview DROP COLUMN day;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering payment.split_payments()...';END$$;
CREATE OR REPLACE FUNCTION payment.split_payments()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
declare 
	_book_id 		int;
	_period_id 		int;
	_work_period_id int;
	_account		jsonb;
begin

	create temp table _days ("date" date);
	create temp table _batch (batch_id int);
	create temp table _new_batch (batch_id int, batch_date date, counting_id int, period_id int);

	_work_period_id = (select pl.id from "period".list pl where pl.is_working = true);

	_period_id =(	select max(pl.id)
					from inserted p
						inner join "period".list pl on p."date" between pl.date_begin and pl.date_end);

-- Собираем ЛС по которым нужно обработать платежи

	_account = (select to_jsonb(array_agg(aa.id))
				from adress.account aa
				inner join inserted p on p.account_name = aa."name"
				group by aa.id);

--- Проверяем наличние параметра пачки

	if exists (select * from parametr.book where parametr_id = 289 and lower("name") = 'Загружено из "1C"')
		then
			begin 
				_book_id = (select cast ("number" as int) from parametr.book where parametr_id = 289 and lower("name") = 'Загружено из "1C"');
			end;
		else
			begin 
				insert into parametr.book (parametr_id, "number",order_number, "name")
				select 289, max(cast ("number" as int)) + 1, max(cast ("number" as int)) + 1, 'Загружено из "1C"'
				from parametr.book 
				where parametr_id = 289;
				
				_book_id = (select cast ("number" as int) from parametr.book where parametr_id = 289 and lower("name") = 'Загружено из "1C"');
			end;
	end if;

---- Проверяем наличие ранее созданных пачек
	insert into _batch
	select b.id
	from inserted p
		inner join "period".list pl on p."date" between pl.date_begin and pl.date_end
		inner join organization.list  ol on ol.inn = p.inn
		inner join organization.counting oc on oc.list_id = ol.id 
		inner join (
						select pb."date", pb.counting_id, pb.id
						from  payment.batch pb 
						where pb.bank_id = _book_id 
					) b on b.counting_id = oc.id and b."date" = p."date"
	where pl.id = _period_id
	group by b.id;

--- Удаляем все пачки и ранее созданные платежи
	delete 
	from "1c".payment pc
		using payment.list pl, _batch b 
	where pl.id = pc.payment_id and b.batch_id = pl.batch_id;

	delete 
	from payment.detal pd
		using _batch b, payment.list pl 
	where pd.payment_id = pl.id	and pl.batch_id = b.batch_id;

	delete 
	from payment.list pl
		using _batch b
	where pl.batch_id = b.batch_id;

	delete 
	from payment.batch pb
		using _batch b
	where pb.id = b.batch_id;

	if (_work_period_id <> _period_id)
		then
			begin 
				call calculation.calc_in_balance (_period_id, _work_period_id, _account);
			end;
	end if;

---- Вставляем новые пачки  
	with cte as 
	(
		insert into payment.batch (period_id, counting_id, "date", "number", "sum", bank_id)
		select pl.id, oc.id as counting_id, p."date", 555 as "number", sum(p.pay_sum) as pay_sum, _book_id
		from inserted p
			inner join "period".list pl on p."date" between pl.date_begin and pl.date_end
			inner join organization.list  ol on ol.inn = p.inn
			inner join organization.counting oc on oc.list_id = ol.id
		where oc.rs = '00000000000000000000' and pl.id = _period_id
		group by pl.id, p."date", oc.id
		returning id, "date", counting_id, period_id 
	)

	insert into _new_batch
	select *
	from cte;

	insert into payment.list (batch_id, "date", "sum", account_id, is_print_check, type_id, payment_type, period_id, payment_period_id)
	select b.batch_id, p."date", p.pay_sum, aa.id, 0, 0, 0, b.period_id, null
	from inserted p
		inner join adress.account aa on aa."name" = p.account_name
		inner join organization.list  ol on ol.inn = p.inn
		inner join organization.counting oc on oc.list_id = ol.id
		inner join _new_batch b on b.counting_id = oc.id and b.batch_date = p."date"
	where b.period_id = _period_id;

	if (_work_period_id <> _period_id)
		then
			begin 
				call calculation.calc_in_balance (_period_id, _work_period_id, _account);
			end;
	end if;


	delete from payment.temp_payment_from_1c;
	drop table if exists _days;
	drop table if exists _batch;
	drop table if exists _new_batch;
	return null;
	
	
end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating payment.split_payments()...';END$$;
COMMENT ON FUNCTION payment.split_payments() IS '=============================================
 Author:		Поляков Павел
 Create date: 24.04.2017
 Description:	Расщепление и регистрация платежей принятых в 1С
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering parametr.change_parametr()...';END$$;
CREATE OR REPLACE FUNCTION parametr.change_parametr()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
declare		
	--	значения из таблицы deleted
		_old_short_name		varchar(15);
	--	значения из таблицы inserted
		_catalog_id			int;
		_new_short_name		varchar(15);
	--	проверочные переменные
		_parametr_id		int;
		_p_table			varchar(255); 
		_p_result			bool;			-- проверка существавания значений параметра
		_sql				text;
		_len				smallint;
		_precision			int2;
		_type_name			varchar(15);
		_error_message 		varchar(100);
		_capacity 			text = '';
begin
	
/*	Алгоритм триггера
	Если по изменяемому параметру имеются значения 
	и происходит попытка изменения принадлежности (Parametr.Directory) 
	или типа параметра (Parametr.Type) тогда откатываются все изменения
	иначе - сохраняются
	Если у параметра изменяется имя переменной и параметр учавствовал в расчетах, то
	изменения откатываются
*/
/*
	27.09.2018
	Сделал возможным редактирование колонок в 
	Calculation.SumVolume и Calculation.SumVolumeArch если они не учавствовали в начислениях
*/
	
	_old_short_name = old.short_name;
	
	select i.catalog_id, i.short_name, i.id, pt.system_type, i.len, i."precision"
	into _catalog_id, _new_short_name, _parametr_id, _type_name, _len, _precision
	from inserted i
		inner join parametr."type" pt on pt.id = i.type_id;

	if (lower(new.short_name) <> lower(old.short_name) and exists(select * from utility.formula_result where lower(formula) like '%' || lower(_old_short_name) || '%'))
		then 
			raise exception 'Невозможно переименовать параметр, т.к. он учавствует в начислениях';
			return null;
	end if;

	_p_table = (select lower(direct.p_table) 
				from parametr.list pl 
					inner join parametr."catalog" direct on direct.id = pl.catalog_id 
				where pl.id = _parametr_id);

	_sql = 'select
				case
					when exists(select 1 from ' || _p_table || ' where parametr_id = ' || _parametr_id || ' and value is not null)
					then $1 = true
					else $1 = false
				end';
	
	execute format(_sql)
	using _p_result;
	  
	begin 

		if (_p_result = true)
			then
				begin
					if (old.type_id <> new.type_id or new.catalog_id <> old.catalog_id or new.short_name <> old.short_name)
						then
							raise exception 'Невозможно переименовать параметр, т.к. он учавствует в начислениях';
							return null;
					end if;
				end;	
		end if;

		if (_catalog_id = 9 and (new.len <> old.len or new."precision" <> old."precision"))
			then
				begin
					_capacity = case 
									when coalesce(_len, 0) != 0 
									then '(' || _len || case 
															when coalesce(_precision, 0) != 0 
															then ',' || _precision || ')' 
															else ')' 
														end 
									else ''
								end;
				
					_sql = '
							alter table calculation.sum_volume 		alter column ' || _old_short_name || '' || _type_name || _capacity || ' null;
							alter table recalculation.sum_volume 	alter column ' || _old_short_name || '' || _type_name || _capacity || ' null;
							alter table calculation.sum_volume_arch alter column ' || _old_short_name || '' || _type_name || _capacity || ' null;';
				
					execute (_sql);
				end;
		end if;

		if (_catalog_id = 9 and old.short_name <> new.short_name)
			then
				begin
					
					alter table calculation.sum_volume rename column _old_short_name to _new_short_name; 
					alter table recalculation.sum_volume rename column _old_short_name to _new_short_name;
					alter table calculation.sum_volume_arch rename column _old_short_name to _new_short_name;
				
				end;
		end if;

		exception 
			when others 
				then 
					get stacked diagnostics 
						_error_message = message_text;
						raise exception '%', _error_message;
	
	end;	
	
	return null;

end;
$_$;


