DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering flat.ordering(jsonb)...';END$$;
CREATE OR REPLACE PROCEDURE flat.ordering(IN _houses jsonb)
LANGUAGE plpgsql
AS $_$
declare 
	_hf bool;
begin
	_hf = (case when exists(select 1 from jsonb_populate_recordset(null::house.list, _houses) h) then true else false end);

	with cte as 
	(
		select *,
			row_number() over (partition by house_id order by house_id, flat_book_id,
									cast(
											case 
												when "name" similar to '%[^0-9]%' 
													then substring(rtrim(ltrim(lower("name"))),1,strpos(rtrim(ltrim(lower("name"))),left(regexp_replace(rtrim(ltrim(lower("name"))),'[0-9]+',''),1) ) - 1) 
												else "name" 
											end as int), id) as ordering
		from adress.flat
		where _hf = true and house_id in (select h.house_id from jsonb_populate_recordset(null::house.list, _houses) h) or _hf = false
	)
	update adress.flat af 
	set
		order_id = ct."ordering"
	from cte ct 
	where ct.id = af.id and coalesce(af.order_id, 0) != ct."ordering";

end
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating flat.ordering(jsonb)...';END$$;
COMMENT ON PROCEDURE flat.ordering(jsonb) IS 'Author: Глещинский Д.В.
	CreationDate: 09.01.2017
	Modified: 25.03.2019 Трофимов Б.И.
	Description: Сортировка квартир';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering fine.fine_delete()...';END$$;
CREATE OR REPLACE FUNCTION fine.fine_delete()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
declare	
	_group_fine	int;
	_period_id	int;
begin

	_group_fine = (select (coalesce(nullif(array_to_string(xpath('root/groupfine/isgroupfine/text()', lower(xml_data::text)::xml)::text[], ''), ''),'false')::bool)::int from special.parametr);

	if (_group_fine = 1)
		then
			begin
				create temp table _account (account_id int);
			
				insert into _account
				select distinct account_parent_id 
				from deleted;
						
				_period_id = (select id 
							from "period".list 
							where is_working = true);
		
				delete 
				from recalculation."result" rr
					using recalculation.root r, _account d 
				where d.account_id = rr.account_parent_id 
					and r.id = rr.root_id 
					and r."type" = 7 
					and r.period_id = _period_id;
		
				delete 
				from recalculation.root r
				where not exists(select * from recalculation."result" rr where rr.root_id = r.id)
					and r.period_id = _period_id 
					and r."type" = 7;
		
				drop table if exists _account;
					
			end;
	end if;

	update payment.balance pb
		set current_calculate = (current_calculate - f.fine)
	from (	select d.account_id, d.period_id, sum(coalesce(d.fine,0)) as fine
			from deleted d
			group by d.account_id, d.period_id
		) as f 
	where pb.account_id = f.account_id 
		and f.period_id = pb.period_id 
		and pb.sublist_id = 7;

	return null;

end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating fine.fine_delete()...';END$$;
COMMENT ON FUNCTION fine.fine_delete() IS '=============================================
 Author:		Глещинский Д.В.
 Create date: 15.05.2015
 Description:	Сохранение при удалении данных о пени в Payment.Balance
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering fine.fine_calc()...';END$$;
CREATE OR REPLACE FUNCTION fine.fine_calc()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
declare	
	_group_id	int;
	_period_id	int; 
	_date		date; 
	_root_id	int; 
	_date_begin	date; 
	_date_end	date; 
	_day		int;
	_group_fine	bool;
begin

	update payment.balance pb
		set current_calculate = f.fine
	from (select account_id, period_id, sum(coalesce(fine,0)) as fine
		  from inserted
		  group by account_id, period_id) as f 
	where pb.account_id = f.account_id and f.period_id = pb.period_id and pb.sublist_id = 7;

	select 
		coalesce(nullif(array_to_string(xpath('root/groupfine/isgroupfine/text()', lower(xml_data::text)::xml)::text[], ''),'')::bool, false), 
		nullif(array_to_string(xpath('root/groupfine/group_id/text()', lower(xml_data::text)::xml)::text[], ''),'')::int
	into _group_fine, _group_id
	from special.parametr;

	if (_group_fine = true)
		then
			begin
				select id, current_date, date_begin, date_end, day_in_month 
				into _period_id, _date, _date_begin, _date_end, _day
				from "period".list 
				where is_working = true;
		
				if exists(select * from recalculation.root where period_id = _period_id and "type" = 7)
					then
						begin
							_root_id = (select id from recalculation.root where period_id = _period_id and "type" = 7);
						end ;
					else 
						begin
							insert into recalculation.root ("name", "date", period_id, "type", rules, odn, period_begin, period_end)
							values ('Группировка пени', _date, _period_id, 7, 0, 0, _period_id, _period_id);  
				
							_root_id = (select max(id) from recalculation.root);
						end;
				end if;
		
				/*	Списываем пени	*/
				insert into recalculation."result" (root_id, period_id, house_id, flat_id, account_id, sublist_id, date_begin, date_end, "day", re_calc_result, diff_result, account_parent_id)
				select _root_id, _period_id, aa.house_id, aa.flat_id, i.account_id, 7, _date_begin, _date_end, _day, -sum(fine), -sum(fine), aa.parent_id
				from inserted i
					inner join adress.account aa on aa.id = i.account_id
				where aa.group_id != _group_id
				group by i.account_id, aa.house_id, aa.flat_id, aa.parent_id;
		
				/*	Переносим пени на выбранную группу	*/
		
				insert into recalculation."result" (root_id, period_id, house_id, flat_id, account_id, sublist_id, date_begin, date_end, "day", re_calc_result, diff_result, account_parent_id)
				select _root_id, _period_id, aap.house_id, aap.flat_id, aap.id, 7, _date_begin, _date_end, _day, sum(fine), sum(fine), aap.parent_id
				from inserted fc
					inner join adress.account aa on aa.id = fc.account_id
					inner join adress.account aap on aap.parent_id = fc.account_parent_id
				where aa.group_id != _group_id and aap.group_id = _group_id
				group by aap.id, aap.house_id, aap.flat_id, aap.parent_id;
			
			end;
	end if;

	return null;
	
end;
$_$;


