DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering exchange.save_ftp_tool(character varying, character varying, character varying, boolean)...';END$$;
CREATE OR REPLACE PROCEDURE exchange.save_ftp_tool(IN _url_string character varying, IN _ftp_user_name character varying, IN _ftp_user_password character varying, IN _use_passive boolean)
LANGUAGE plpgsql
AS $_$
begin

	if exists(select * from exchange.ftp_tool) 
		then
			update exchange.ftp_tool 
				set
					use_passive 	= _use_passive,
					url_string 		= _url_string,
					user_password 	= _ftp_user_password,
					user_login 		= _ftp_user_name;			
		else 
			insert into exchange.ftp_tool (url_string, user_login, user_password, use_passive)
			values (_url_string, _ftp_user_name, _ftp_user_password, _use_passive);
	end if;

end
$_$;


