DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering counter.update_counter(jsonb, integer, smallint, integer, integer, character varying, integer, date, date, jsonb, boolean, integer, boolean, integer)...';END$$;
CREATE OR REPLACE PROCEDURE counter.update_counter(IN _house jsonb, IN _sublist_id integer, IN _number smallint, IN _catalog_id integer, IN _mark_id integer, IN _model character varying, IN _interval integer, IN _date_verf date, IN _date_install date, IN _flat_book jsonb, IN _is_export_to_gis boolean, IN _session_id integer, IN _remote_metering boolean DEFAULT NULL::boolean, IN _remote_metering_id integer DEFAULT NULL::integer)
LANGUAGE plpgsql
AS $_$
declare 
	_period_id 		int;
	_date_begin 	date;
	_date_end 		date default null::date;
	_active 		bool = true;
	_unit_id 		int;
	_count 			int;
	_period_begin 	date;
begin
		
	create temp table _history_temp_date (counter_id int, verification_date date);
	create temp table _history_temp_interval (counter_id int, verification_interval int);

	if _catalog_id = 1
		then 
			begin
				create temp table _account (account_id int);
				create temp table _counter (id int, date_begin date, date_end date, sublist_id int, active bool, "number" int2, rate numeric(9, 6), unit_id int, is_show_value bool);
				create temp table _counter_account (rownumber int, account_id int, counter_id int);
		
				create temp table _account_list (id int, account_id int);
				create temp table _counter_list (id int, counter_id int);

				select date_begin, date_begin, id 
				into _date_begin, _period_begin, _period_id
				from "period".list 
				where is_working = true;

				_unit_id = (select unit_id from utility.sublist where id = _sublist_id);

				insert into _account (account_id)
				select distinct ai.account_id
				from adress.light_info ai 
					inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = ai.house_id
				where ai.account_id in (
											select distinct ai.account_id
											from adress.light_info ai 
												inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = ai.house_id
												inner join jsonb_populate_recordset(null::special.objects, _flat_book) f on f.object_id = ai.flat_book_id
												inner join counter.account ca on ca.account_id = ai.account_id
												inner join counter.list cl on cl.id = ca.counter_id
											where cl.sublist_id = _sublist_id and cl."number" = _number
											group by ai.account_id
										);

				if exists(select * from _account)
					then
						begin
							if (_date_install is not null and exists(
																		select 1 
																		from counter.list cl
																			inner join counter.account c on c.counter_id = cl.id
																			inner join _account a on a.account_id = c.account_id 
																		where cl.active = true and cl.sublist_id = _sublist_id and cl."number" = _number and _date_install > cl.date_begin
																		fetch first 1 rows only
																	)
								)
								then 
									begin
										raise notice 'Не корректная дата установки (Должна быть больше даты ввода в эксплуатацию)' using errcode = '55000';
										drop table if exists _account;
										drop table if exists _counter;
										drop table if exists _counter_account;
										drop table if exists _account_list;
										drop table if exists _counter_list;
										return;
									end;
							end if;
					
							update counter.list cl
								set
									mark_id = coalesce(cl.mark_id, _mark_id),
									model = (case when cl.model is null or model = '' then _model else cl.model end), 
									verification_interval = coalesce(cl.verification_interval, _interval),
									verification_date = coalesce(cl.verification_date, _date_verf),
									remote_metering_mode = _remote_metering,
									remote_metering_info_id = coalesce(cl.remote_metering_info_id, _remote_metering_id),
									installation_date = coalesce(cl.installation_date, _date_install),
									is_export_to_gis = case when cl.unique_number is null then _is_export_to_gis else cl.is_export_to_gis end
							from counter.account c 
								inner join _account a on a.account_id = c.account_id 
							where c.counter_id = cl.id and cl.active = true and cl.sublist_id = _sublist_id and cl."number" = _number;
				
--							return query
--							select cl.*,c.account_id,c.counter_id  
--							from counter.list cl
--								inner join counter.account c on c.counter_id = cl.id
--								inner join _account a on a.account_id = c.account_id 
--							where cl.active = true and cl.sublist_id = _sublist_id and cl."number" = _number;	
							 	
							raise notice 'Успешно' using errcode = '55000';
						end; 
					else 
						begin					
							raise notice 'Счетчик(и) с такими параметрами уже существует' using errcode='55000';
						end;

				if(_date_verf is not null)
				then
					begin
						insert into _history_temp_date(counter_id, verification_date)
						select cl.id, _date_verf
						from counter.list cl
							inner join  counter.account c on c.counter_id = cl.id
							inner join _account a on a.account_id = c.account_id
						where cl.active = true 
							and cl.sublist_id = _sublist_id 
							and cl.number = _number
							and cl.verification_date is null;
					end;
				end if;

				if(_interval is not null)
				then
					begin
						insert into _history_temp_interval(counter_id, verification_interval)
						select cl.id, _interval
						from counter.list cl
							inner join counter.account c on c.counter_id = cl.id
							inner join _account a on a.account_id = c.account_id
						where cl.active = true 
							and cl.sublist_id = _sublist_id 
							and cl.number = _number
							and cl.verification_interval is null;
					end;
				end if;

				insert into counter.verification_history(counter_id, created_at, session_id, verification_date, verification_interval, resource)
				select coalesce(ht.counter_id, htt.counter_id), current_date, _session_id, coalesce(ht.verification_date, cl.verification_date), coalesce(htt.verification_interval, cl.verification_interval), 2
				from _history_temp_date ht
					full join _history_temp_interval htt on ht.counter_id = htt.counter_id
					inner join counter.list cl on cl.id = coalesce(ht.counter_id, htt.counter_id)
				where coalesce(ht.verification_date, cl.verification_date) is not null;
				end if;
	
				drop table if exists _account;
				drop table if exists _counter;
				drop table if exists _counter_account;
				drop table if exists _account_list;
				drop table if exists _counter_list;
	
			end;
		
		else
			begin
				
				create temp table _house (house_id int);
				create temp table _counter (id int, date_begin date, date_end date, sublist_id int, active bit, "number" int2, rate numeric(9, 6), unit_id int, is_show_value bit);
				create temp table _counter_house (rownumber int, house_id int, counter_id int);
		
				create temp table _account_list (id int, house_id int);
				create temp table _counter_list (id int, counter_id int);

				select date_begin, date_begin, id 
				into _date_begin, _period_begin, _period_id
				from "period".list 
				where is_working = true;

				_unit_id = (select unit_id from utility.sublist where id = _sublist_id);

				insert into _house (house_id)
				select distinct ai.house_id
				from adress.light_info ai 
					inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = ai.house_id
				where ai.house_id in (
											select distinct ai.house_id
											from adress.light_info ai 
												inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = ai.house_id
												inner join counter.house ca on ca.house_id= ai.house_id
												inner join counter.list cl on cl.id = ca.counter_id
											where cl.sublist_id = _sublist_id and cl."number" = _number
											group by ai.house_id
									);

				if exists(select h.* from jsonb_populate_recordset(null::house.list, _house) h)
					then
						begin
							if (_date_install is not null and exists(
																		select 1 
																		from counter.list cl
																			inner join counter.house c on c.counter_id = cl.id
																			inner join _house a on a.house_id = c.house_id 
																		where cl.active = true and cl.sublist_id = _sublist_id and cl."number" = _number and _date_install > cl.date_begin
																		fetch first 1 rows only
																	)
								)
								then 
									begin
										raise notice 'Не корректная дата установки (Должна быть больше даты ввода в эксплуатацию)' using errcode = '55000';
										drop table if exists _house;
										drop table if exists _counter;
										drop table if exists _counter_house;
										drop table if exists _account_list;
										drop table if exists _counter_list;
										return;
									end;
							end if;
					
							update counter.list cl
								set
									mark_id = coalesce(cl.mark_id, _mark_id),
									model = (case when cl.model is null or model = '' then _model else cl.model end), 
									verification_interval = coalesce(cl.verification_interval, _interval),
									verification_date = coalesce(cl.verification_date, _date_verf),
									remote_metering_mode = _remote_metering,
									remote_metering_info_id = coalesce(cl.remote_metering_info_id, _remote_metering_id),
									installation_date = coalesce(cl.installation_date, _date_install),
									is_export_to_gis = case when cl.unique_number is null then _is_export_to_gis else cl.is_export_to_gis end
							from counter.house c 
								inner join _house a on a.house_id = c.house_id 
							where c.counter_id = cl.id and cl.active = true and cl.sublist_id = _sublist_id and cl."number" = _number;
				
--							return query
--							select cl.*,c.account_id,c.counter_id  
--							from counter.list cl
--								inner join counter.account c on c.counter_id = cl.id
--								inner join _account a on a.account_id = c.account_id 
--							where cl.active = true and cl.sublist_id = _sublist_id and cl."number" = _number;	
							 	
							raise notice 'Успешно' using errcode = '55000';
						end; 
					else 
						begin					
							raise notice 'Счетчик(и) с такими параметрами уже существует' using errcode='55000';
						end;
				end if;

				if(_date_verf is not null)
				then
					begin
						insert into _history_temp_date(counter_id, verification_date)
						select cl.id, _date_verf
						from counter.list cl
							inner join counter.house c on c.counter_id = cl.id
							inner join _house a on a.house_id = c.house_id
						where cl.active = true 
							and cl.sublist_id = _sublist_id 
							and cl.number = _number
							and cl.verification_date is null;
					end;
				

				if(_interval is not null)
				then
					begin
						insert into _history_temp_interval(counter_id, verification_interval)
						select cl.id, _interval
						from counter.list cl
							inner join counter.house c on c.counter_id = cl.id
							inner join _house a on a.house_id = c.house_id
						where cl.active = true 
							and cl.sublist_id = _sublist_id 
							and cl.number = _number
							and cl.verification_interval is null;
					end;
				end if;

				insert into counter.verification_history(counter_id, created_at, session_id, verification_date, verification_interval, resource)
				select coalesce(ht.counter_id, htt.counter_id), current_date, _session_id, coalesce(ht.verification_date, cl.verification_date), coalesce(htt.verification_interval, cl.verification_interval), 2
				from _history_temp_date ht
					full join _history_temp_interval htt on ht.counter_id = htt.counter_id
					inner join counter.list cl on cl.id = coalesce(ht.counter_id, htt.counter_id)
				where coalesce(ht.verification_date, cl.verification_date) is not null;
				end if;
	
			


				drop table if exists _house;
				drop table if exists _counter;
				drop table if exists _counter_house;
				drop table if exists _account_list;
				drop table if exists _counter_list;
				
			end;
		
	end if;
			
	drop table _history_temp_date;
	drop table _history_temp_interval;

end
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating counter.update_counter(jsonb, integer, smallint, integer, integer, character varying, integer, date, date, jsonb, boolean, integer, boolean, integer)...';END$$;
COMMENT ON PROCEDURE counter.update_counter(jsonb, integer, smallint, integer, integer, character varying, integer, date, date, jsonb, boolean, integer, boolean, integer) IS '=============================================
 author:		ооо жилфондсервис
 create date: 25.10.2013
 description:	массовое добавление счетчиков
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering counter.new_counter(jsonb, integer, smallint, integer, numeric, integer, character varying, integer, date, date, date, jsonb, boolean, integer, boolean, integer)...';END$$;
CREATE OR REPLACE PROCEDURE counter.new_counter(IN _house jsonb, IN _sublist_id integer, IN _number smallint, IN _catalog_id integer, IN _rate numeric, IN _mark_id integer, IN _model character varying, IN _interval integer, IN _date_begin date, IN _date_verf date, IN _date_install date, IN _flat_book jsonb, IN _is_export_to_gis boolean, IN _session_id integer, IN _remote_metering boolean DEFAULT NULL::boolean, IN _remote_metering_id integer DEFAULT NULL::integer)
LANGUAGE plpgsql
AS $_$
declare 
	  _period_id 		int;
	  _date_end 		date = null::date;
	  _active 			bool = true;
	  _unit_id 			int;
	  _count 			int;
	  _period_begin 	date;	
	  _prev_date_end 	date;
begin
	
	if _catalog_id = 1
		then 
			begin
				create temp table _account (account_id int);
				create temp table _counter (id int, date_begin date, date_end date, sublist_id int, active bool, "number" int2, rate numeric(9, 6), unit_id int, is_show_value int2); 
				create temp table _counter_account (rownumber int, account_id int, counter_id int);
				create temp table _account_list (id int, account_id int);
				create temp table _counter_list (id int, counter_id int);

				select coalesce(_date_begin, date_begin), date_begin, id 
				into _date_begin, _period_begin, _period_id
				from "period".list 
				where is_working = true;

				if (_date_install > _date_begin and _date_install is not null)
					then				
						raise notice 'Не корректная дата установки (должна быть больше начальной даты рабочего периода)' using errcode='55000';
					return;
				end if;
	
				_unit_id = (select unit_id from utility.sublist where id = _sublist_id);

				insert into _account (account_id)
				select distinct ai.account_id
				from adress.light_info ai 
					inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = ai.house_id
					inner join jsonb_populate_recordset(null::special.objects, _flat_book) f on f.object_id = ai.flat_book_id
					inner join calculation.parametr_transporate cp on cp.account_id = ai.account_id
				where ai.account_id not in (
												select distinct ai.account_id
												from adress.light_info ai 
													inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = ai.house_id
													inner join counter.account ca on ca.account_id = ai.account_id
													inner join counter.list cl on cl.id = ca.counter_id			
												where cl.sublist_id = _sublist_id and cl."number" = _number and cl.active = true
												group by ai.account_id
											)  and cp.is_closed = 1::int2;

				if  exists(select * from _account)
					then 
						begin
							with cte as 
							(
								insert into counter.list (date_begin, date_end, sublist_id, active, "number", rate, unit_id, is_show_value, counter_type
									,mark_id, model, installation_date, verification_interval, verification_date, remote_metering_mode, remote_metering_info_id, is_export_to_gis)
								 select _date_begin, _date_end, _sublist_id, _active, _number, _rate, _unit_id, 1, 1, _mark_id, _model, _date_install
								 , _interval, _date_verf, _remote_metering, _remote_metering_id, _is_export_to_gis
								 from _account
								 returning id, date_begin, date_end, sublist_id, active, "number", rate, unit_id, is_show_value
							)
							insert into _counter
							select *
							from cte;
					
							_count = (select count(*) from _counter);	
		
							insert into _counter_list (id, counter_id)
							select row_number() over (order by id), id 
							from _counter;
		
							insert into _account_list(id, account_id)
							select row_number() over (order by account_id), account_id 
							from _account;
		
							insert into counter.account (account_id, counter_id)
							select account_id, counter_id 
							from _counter_list c
								inner join _account_list t on t.id = c.id ;
		
					 		_prev_date_end = (make_date(date_part('year', _date_begin)::int, date_part('month', _date_begin)::int, 1) - 1);
		
							insert into counter.flow (counter_id, period_id, prev_value, value, c_value, flow_type_id, sublist_id, rate, prev_date, "date")
							select *
							from (
									select id, _period_id - 1, 0.0, 0.0, 0.0, 5, _sublist_id, _rate, _prev_date_end, _prev_date_end
									from _counter
									union all
									select id, _period_id, 0.0, null, 0.0, 0, _sublist_id, _rate, _prev_date_end, null 
									from _counter
								) counter;
		 	
							raise notice 'Успешно создано % счетчик(ов)', _count using errcode='55000';
						end;
					else 
						begin
							raise notice 'Счетчик(и) с такими параметрами уже существует' using errcode='55000';
						end;	
				end if;	
			end;
		
				drop table if exists _account;
				drop table if exists _counter; 
				drop table if exists _counter_account;
				drop table if exists _account_list;
				drop table if exists _counter_list;
		else
			begin
				create temp table _house (house_id int);
				create temp table _counter (id int, date_begin date, date_end date, sublist_id int, active bool, "number" int2, rate numeric(9, 6), unit_id int, is_show_value int2); 
				create temp table _counter_house (rownumber int, house_id int, counter_id int);
				create temp table _account_list (id int, house_id int);
				create temp table _counter_list (id int, counter_id int);

				select coalesce(_date_begin, date_begin), date_begin, id 
				into _date_begin, _period_begin, _period_id
				from "period".list 
				where is_working = true;

				if (_date_install > _date_begin and _date_install is not null)
					then				
						raise notice 'Не корректная дата установки (должна быть больше начальной даты рабочего периода)' using errcode='55000';
					return;
				end if;
	
				_unit_id = (select unit_id from utility.sublist where id = _sublist_id);

				insert into _house (house_id)
				select distinct h.house_id
				from jsonb_populate_recordset(null::house.list, _house) h 
				where h.house_id not in (
											select distinct h.house_id
											from jsonb_populate_recordset(null::house.list, _house) h 
												inner join counter.house ca on ca.house_id = h.house_id
												inner join counter.list cl on cl.id = ca.counter_id			
											where cl.sublist_id = _sublist_id and cl."number" = _number and cl.active = true
											group by h.house_id
										);

				if  exists(select * from _house)
					then 
						begin
							with cte as 
							(
								insert into counter.list (date_begin, date_end, sublist_id, active, "number", rate, unit_id, is_show_value, counter_type
									,mark_id, model, installation_date, verification_interval, verification_date, remote_metering_mode, remote_metering_info_id, is_export_to_gis)
								select _date_begin, _date_end, _sublist_id, _active, _number, _rate, _unit_id, 1, 1, _mark_id, _model, _date_install, _interval
									, _date_verf, _remote_metering, _remote_metering_id , _is_export_to_gis
								from _house
								returning id, date_begin, date_end, sublist_id, active, "number", rate, unit_id, is_show_value
							)
							insert into _counter
							select *
							from cte;
					
							_count = (select count(*) from _counter);	
		
							insert into _counter_list (id, counter_id)
							select row_number() over (order by id), id 
							from _counter;
		
							insert into _house_list(id, house_id)
							select row_number() over (order by house_id), house_id 
							from _house;
		
							insert into counter.house (house_id, counter_id)
							select house_id, counter_id 
							from _counter_list c
								inner join _house_list t on t.id = c.id ;
		
					 		_prev_date_end = (make_date(date_part('year', _date_begin)::int, date_part('month', _date_begin)::int, 1) - 1);
		
							insert into counter.flow (counter_id, period_id, prev_value, value, c_value, flow_type_id, sublist_id, rate, prev_date, "date")
							select *
							from (
									select id, _period_id - 1, 0.0, 0.0, 0.0, 5, _sublist_id, _rate, _prev_date_end, _prev_date_end
									from _counter
									union all
									select id, _period_id, 0.0, null, 0.0, 0, _sublist_id, _rate, _prev_date_end, null 
									from _counter
								) counter;
		 	
							raise notice 'Успешно создано % счетчик(ов)',_count using errcode='55000';
						end;
					else 
						begin
							raise notice 'Счетчик(и) с такими параметрами уже существует' using errcode='55000';
						end;	
				end if;	

				if(_date_verf is not null)
				then
					begin
						insert into counter.verification_history(counter_id, created_at, session_id, verification_date, verification_interval, resource)
						select id, current_date, _session_id, _date_verf, _interval, 2
						from _counter;
					end;
				end if;

				drop table if exists _house;
				drop table if exists _counter; 
				drop table if exists _counter_house;
				drop table if exists _account_list;
				drop table if exists _counter_list;
			
			end;	
	end if;



end
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating counter.new_counter(jsonb, integer, smallint, integer, numeric, integer, character varying, integer, date, date, date, jsonb, boolean, integer, boolean, integer)...';END$$;
COMMENT ON PROCEDURE counter.new_counter(jsonb, integer, smallint, integer, numeric, integer, character varying, integer, date, date, date, jsonb, boolean, integer, boolean, integer) IS '=============================================
