DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating calculation.create_calc(boolean, boolean, jsonb)...';END$$;
COMMENT ON PROCEDURE calculation.create_calc(boolean, boolean, jsonb) IS '=============================================
 author:		глещинский д.в.
 create date: 28.05.2014
 description:	формирование процедуры расчетов
 _odn - проверяет, будет ли расчитываться одн --0 - нет, 1 - да
 _account - список лицевых счетов, по которым нужно прозвести перерасчет
 Modify Author: Юркин Е.Ю.
 Modify Description: всякая дичь про учет корректировочных объемов в суммарных
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering calculation.cp_transporate(jsonb)...';END$$;
CREATE OR REPLACE PROCEDURE calculation.cp_transporate(IN _house jsonb)
LANGUAGE plpgsql
AS $_$
declare 
	_qry 		text = '';
	_date_begin date; 
	_entity 	varchar(10) = '';
	_entity_id 	varchar(10) = '';
	_result		text = '';
	_i 			int = 1;
begin 
	
	_date_begin = (select date_begin from "period".list where is_working = true);




	drop table if exists _houses;
	drop table if exists _flats;
	drop table if exists _accounts;

	create temp table _houses (object_id int);
	create temp table _flats (object_id int);
	create temp table _accounts (object_id int);
	
	insert into _houses
	select h.house_id
	from jsonb_populate_recordset(null::house.list, _house) h;
	
	insert into _flats
	select af.id
	from adress.flat af
		inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = af.house_id;
		
	insert into _accounts
	select aa.id
	from adress.account aa
		inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = aa.house_id;

	while _i <= 3 loop

		_entity = (select case when _i = 1 then 'account' when _i = 2 then 'flat' when _i = 3 then 'house' end);
		_entity_id = (select case when _i = 1 then 'account_id' when _i = 2 then 'flat_id' when _i = 3 then 'house_id' end);

		_qry = (select  string_agg(
			(select 'select distinct ' || cast(pf.parametr_id as varchar(10)) || ', ' || _entity_id||',cast(' || pl.short_name || ' as varchar(200)), ''' || cast(_date_begin as varchar(10)) || '''::date
			from (' || pf.formula || ') t
			inner join _' || _entity || 's e on e.object_id = t.' || _entity_id || '
				'),'
		union all
		')
		from parametr.formula pf
			inner join parametr.list pl on pl.id = pf.parametr_id
		where pl.catalog_id = _i and pf.date_end is null);

		_qry='
		merge into parametr.' || _entity || ' as targets 
		using (' || _qry || ')';
		
		_qry = _qry||'
		as sources(parametr_id, ' || _entity_id || ', value, date_begin)
		on(targets.parametr_id = sources.parametr_id and targets.' || _entity_id || ' = sources.' || _entity_id || ' and coalesce(targets.date_begin, sources.date_begin) = sources.date_begin)
		when matched then
			update set
				value = sources.value,
				date_begin = sources.date_begin
		when not matched then
			insert(parametr_id, ' || _entity_id || ', value, date_begin)
			values(sources.parametr_id, sources.' || _entity_id || ', sources.value, sources.date_begin)
		;';

		_i = _i + 1;
		_result = _result||coalesce(_qry,'');
			

	end loop;

	execute (_result);	
	

	drop table if exists _houses;
	drop table if exists _flats;
	drop table if exists _accounts;

end
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating calculation.cp_transporate(jsonb)...';END$$;
COMMENT ON PROCEDURE calculation.cp_transporate(jsonb) IS '=============================================
 author:		глещинский д.в.
 create date: 26.05.214
 modified date: 23.04.2019, трофимов б.и., добавил фильтр по домам
 description:	формирование процедуры заполнения таблицы calculation.parametrtransporate
				_parametr - параметр, который указывает, нужно ли перерасчитывать расчетные параметры
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering calculation.contragent(jsonb)...';END$$;
CREATE OR REPLACE PROCEDURE calculation.contragent(IN _account jsonb)
LANGUAGE plpgsql
AS $_$
declare 
	_is_use_reserve bool;
	_date_begin 	date;
	_date_end 		date;
	_cpr 			int;
	_parametr 		jsonb;
begin

	_is_use_reserve = (select (case 
			 								when array_to_string(xpath('Root/Calculation/IsUseReserve/text()', p.xml_data)::text[] , '') = '' 
			 								then false 
			 								else array_to_string(xpath('Root/Calculation/IsUseReserve/text()', p.xml_data)::text[], '')::bool 
			 							end)::bool
		 						 from special.parametr p);
		 						
	if (_is_use_reserve = false) 
	then 
		return;
	end if;

	drop table if exists _date_range;
	drop table if exists _new_date_range;
	drop table if exists _parametr_data;

	create temp table _date_range(account_id int, type_id smallint, date_begin date, date_end date);
	create temp table _new_date_range(account_id int, date_begin date, date_end date);
	create temp table _parametr_data (object_id int, parametr_id int,value text,date_begin date);
	
	alter table _parametr_data
		add constraint un_parametr_data  unique (object_id, parametr_id);

	select date_begin, date_end 
		into _date_begin, _date_end 
	from period.list 
	where is_working = true;

	_cpr = (select id from parametr.list where lower(short_name) = 'cpr');

	/* 
		удаляем все значения по параметрам cpr, cbp, br1 
		дата начала у которых находится в рабочем периоде
	*/
	delete from parametr.account pa
	using jsonb_populate_recordset(null::account.list, _account) a, parametr.list pl
	where pa.account_id = a.account_id
		and lower(pl.short_name) in ('cpr', 'cbp', 'br1')
		and parametr_id = pl.parametr_id 
		and pa.date_begin between _date_begin and _date_end;

	insert into _date_range(account_id, type_id, date_begin, date_end)
	select 
		ca.account_id,
		cr.type_id,
		case when coalesce(cr.date_begin, _date_begin) <= _date_begin then _date_begin else cr.date_begin end as date_begin, 
		case when coalesce(cr.date_end, _date_end) >= _date_end then _date_end else cr.date_end end as date_end
	from contragent.account ca  
		inner join jsonb_populate_recordset(null::account.list, _account) a on a.account_id = ca.account_id
		inner join contragent.parametr cp on cp.contragent_account_id = ca.id
		left join lateral (select * 
							from contragent.reserve crr
							where coalesce(crr.date_end, _date_begin) >= _date_begin and ca.id = crr.contragent_account_id) cr on true 
	where _date_begin <= coalesce(cr.date_end, _date_end) and _date_end >= coalesce(cr.date_begin, _date_begin)	and cp.parametr_id = 1383;

	with cte as (
		select d1.account_id, d1.date_begin
		from _date_range d1
		union 
		select account_id, date_end + 1
		from _date_range
		where date_end != _date_end
	)
	
	insert into _new_date_range (account_id, date_begin, date_end)
	select 
		c.account_id
		,c.date_begin
		,lead((date_begin - 1), 1, _date_end) over (partition by account_id order by account_id, date_begin) as date_end
	from cte c;

	with cte as 
	(
		select ca.contragent_id, n.*
		,case 
			when type_id = 2 then 1
			when coalesce(pb.order_number, 2) != 2 and type_id is null then 1
			else 0
		end as pc
		from _new_date_range n
			inner join contragent.account ca on ca.account_id = n.account_id
			inner join jsonb_populate_recordset(null::account.list, _account) a on aaccount_id = ca.account_id
			inner join contragent.parametr cp on cp.contragent_account_id = ca.id
			left join parametr.book pb on pb.id = cp.book_id
			left join contragent.reserve cr on cr.contragent_account_id = ca.id
						and coalesce(cr.date_begin, _date_begin) <= n.date_end and coalesce(cr.date_end, _date_end) >= n.date_begin
		where cp.parametr_id = 1383
	)

	insert into _parametr_data (object_id, parametr_id, date_begin, value)
	select account_id, _cpr, date_begin, sum(pc)
	from cte 
	group by account_id, date_begin, date_end;

	merge into _parametr_data as targets
	using (select a.account_id as object_id, _cpr as parametr_id
			from _account a) 
	as sources (object_id, parametr_id)
	on (targets.object_id = sources.object_id and targets.parametr_id = sources.parametr_id)
	when not matched then
		insert(object_id, parametr_id, date_begin, value)
		values(sources.object_id, sources.parametr_id, _date_begin, null);

--	/*	дополняем параметрами cbp и br1 для об-null-ения значений предыдущего периода	*/
	insert into _parametr_data(object_id, parametr_id, date_begin, value)
	select a.account_id, pl.id, _date_begin, null
	from jsonb_populate_recordset(null::account.list, _account) a
		inner join parametr.list pl on 1 = 1
	where lower(pl.short_name) in ('cbp', 'br1');

	
	_parametr = (select jsonb_agg(jsonb_build_object('object_id',object_id,'parametr_id',parametr_id,'value',value,'date_begin',date_begin))
			     from _parametr_data);


	call parametr.save_value_account (_parametr);

	drop table if exists _date_range;
	drop table if exists _new_date_range;
	drop table if exists _parametr_data;


end
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating calculation.contragent(jsonb)...';END$$;
COMMENT ON PROCEDURE calculation.contragent(jsonb) IS '=============================================
 author:		глещинский д.в.
 create date: 13.12.2018
 description:	процедура автоматического расчета проживающих
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering calculation.changed_parametr(integer, jsonb, integer)...';END$$;
CREATE OR REPLACE PROCEDURE calculation.changed_parametr(IN _period_id integer, IN _account jsonb, IN _session_id integer)
LANGUAGE plpgsql
AS $_$
declare
		_date_begin date;
		_date_end	date;
begin	
	
	create temp table _house (house_id int);
	
	select date_begin, date_end 
		into _date_begin,_date_end   
	from "period".list 
	where id = _period_id;

	delete 
	from recalculation.account
	where session_id = _session_id;

	create temp table _date_end_account (parametr_id int, short_name varchar(15), account_id int, value varchar(200), date_begin date, date_end date);
	create temp table _date_end_flat (parametr_id int, short_name varchar(15), flat_id int, value varchar(200), date_begin date, date_end date);
	create temp table _date_end_house (parametr_id int, short_name varchar(15), house_id int, value varchar(200), date_begin date, date_end date);
		
	insert into _date_end_account
	select 
		pa.parametr_id
		,pl.short_name
		,pa.account_id
		,pa.value
		,case when pa.date_begin < _date_begin then _date_begin else pa.date_begin end as date_begin
		,pa.date_end
	from parametr.account pa
		inner join parametr.list  pl on pl.id = pa.parametr_id
	where date_end is not null and date_end between _date_begin and _date_end and pl.is_calculation = true;

	insert into _date_end_flat
	select 
		 pa.parametr_id
		,pl.short_name
		,pa.flat_id
		,pa.value
		,case when pa.date_begin < _date_begin then _date_begin else pa.date_begin end as date_begin
		,pa.date_end
	from parametr.flat pa
		inner join parametr.list  pl on pl.id = pa.parametr_id
	where date_end is not null and date_end between _date_begin and _date_end and pl.is_calculation = true;

	insert into _date_end_house
	select 
		pa.parametr_id
		,pl.short_name
		,pa.house_id
		,pa.value
		,case when pa.date_begin < _date_begin then _date_begin else pa.date_begin end as date_begin
		,pa.date_end
	from parametr.house pa
		inner join parametr.list  pl on pl.id = pa.parametr_id
	where date_end is not null and date_end between _date_begin and _date_end and is_calculation = true;

	insert into _house
	select distinct aa.house_id
	from adress.account aa
		inner join jsonb_populate_recordset(null::account.list, _account) a on a.account_id = aa.id
		inner join _date_end_account da on aa.id = da.account_id;

	insert into recalculation.account
	select aa.id, _session_id
	from adress.account aa 
		inner join _house h on h.house_id = aa.house_id
	where parent_id is null
	union
	select account_parent_id, _session_id
	from calculation.account_sublist_for_change
	where period_id = _period_id;

	delete from recalculation.parametr_for_change;
	
	insert into recalculation.parametr_for_change  (house_id, flat_id, account_id, parametr_id, short_name, value, date_begin, date_end)
	select null::int, null::int, d.account_id ,parametr_id, short_name, value, date_begin, date_end 
	from _date_end_account d
		union all
	select null::int, d.flat_id, null::int, parametr_id, short_name, value, date_begin, date_end 
	from _date_end_flat d 
		union all
	select d.house_id, null::int, null::int, parametr_id, short_name, value, date_begin, date_end 
	from _date_end_house d; 

	drop table if exists _date_end_account;
	drop table if exists _date_end_house;
	drop table if exists _date_end_flat;
	drop table if exists _house;

end
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating calculation.changed_parametr(integer, jsonb, integer)...';END$$;
COMMENT ON PROCEDURE calculation.changed_parametr(integer, jsonb, integer) IS '=============================================
 Author:	 Поляков Павел
 Create date: 03-04-2015
 Description:	Возвращает список измененных параметров в рабочем периоде и пишет в Recalculation для последующего перерасчета
   Сбор измненных параметров происходи не зависимо от лс по которым запущен расчет
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering calculation.change_account_sublist()...';END$$;
CREATE OR REPLACE FUNCTION calculation.change_account_sublist()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
declare 
	_period_id int;
begin

	_period_id = (select * from "period".get_work_period_id());

	with cte as 
	(
		select 
			 fc.date_end
			,(lead(date_begin, 1, (select (max(c.date_end)+ interval '1 day') from calculation.account_sublist_for_change c where c.period_id = fc.period_id and c.account_id = fc.account_id and c.sublist_id = fc.sublist_id)) over (partition by c.account_id, c.sublist_id order by c.account_id, c.sublist_id, c.date_begin))
				- interval '1 day' as new_date_end
			,fc.id 
		from calculation.account_sublist_for_change fc
		where fc.period_id = _period_id
			and fc.account_id in (select i.account_id from i.inserted)
			and fc.sublist_id in (select i.sublist_id from i.inserted)
	)
	
	update calculation.account_sublist_for_change asf
		set date_end = ct.new_date_end
	from cte ct
	where asf.id = ct.id;
	
end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating calculation.change_account_sublist()...';END$$;
COMMENT ON FUNCTION calculation.change_account_sublist() IS '=============================================
 Author:		<Author,,Name>
 Create date: <Create Date,,>
 Description:	<Description,,>
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering calculation.account_sublist_edit()...';END$$;
CREATE OR REPLACE FUNCTION calculation.account_sublist_edit()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
declare 
	_period_id int;
begin

	_period_id = (select "period".get_work_period_id());

	create temp table _temp (account_id int, account_parent_id int, sublist_id int, value bool, date_begin date, date_end date);

	set session_replication_role = replica;

	with upd as
	(
		update calculation.account_sublist as ca
			set value = i.value,
				date = i.date
		from (		select account_id, house_id, account_parent_id, sublist_id, value, date 
				  	from inserted) i 
			  inner join calculation.account_sublist caa on 1 = 1
		where ca.id  = caa.id 
			and ca.account_id = i.account_id 
			and ca.sublist_id = i.sublist_id
			and ca.value != i.value 
			and ca."date" <= i."date"
		returning caa.account_id, caa.account_parent_id, caa.sublist_id, caa.value, caa.date
	)
	,ins as
	(
		insert into calculation.account_sublist (account_id, house_id, account_parent_id, sublist_id, value, "date")
		select i.account_id, i.house_id, i.account_parent_id, i.sublist_id, i.value, i.date 
		from inserted i
			left join calculation.account_sublist cs on i.account_id = cs.account_id and i.sublist_id= cs.sublist_id
		where cs.id is null
	)
	
	insert into _temp
	select account_id, account_parent_id, sublist_id, value, date, case when account_id is null then null else date end
	from upd up;
		
	set session_replication_role = default;

	delete 
	from _temp
	where account_id is null or date_begin = date_end;
	
	insert into _temp
	select *
	from (
			select i.account_id, i.account_parent_id, i.sublist_id, i.value, i.date, null
			from inserted i
				inner join calculation.account_sublist ca on ca.account_id = i.account_id and i.sublist_id = ca.sublist_id
			where i.date < ca.date
			except
			select t.account_id, t.account_parent_id, t.sublist_id, t.value, t.date_begin, t.date_end
			from _temp t
		) as t;
		
	if exists (select * from _temp)
		then
			begin				
				insert into calculation.account_sublist_for_change (account_id, account_parent_id,sublist_id, value, date_begin,date_end, period_id)
				select t.account_id, t.account_parent_id, t.sublist_id, t.value, t.date_begin, (t.date_end - 1), _period_id
				from _temp t;
			end;
	end if;
	drop table if exists _temp;

	return null;
	
end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating calculation.account_sublist_edit()...';END$$;
COMMENT ON FUNCTION calculation.account_sublist_edit() IS '=============================================
 Author:		Поляков Павел
 Create date: 21.11.2017
 Description:	Обновлени действующих значений и запись измененных в отдельную таблицу
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering benefit.update_calc()...';END$$;
CREATE OR REPLACE FUNCTION benefit.update_calc()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
declare 
	_period_id 		int;
	_account_id 	int;
	_benefit_type 	int2;
begin
	
	_period_id = (select period_id from inserted limit 1);
	_account_id = (select account_id from inserted limit 1);

	_benefit_type = (select array_to_string(xpath('root/ui/usebenefit/text()', lower(p.xml_data::text)::xml)::text[], '')::int2
					 from special.parametr p);

	if _benefit_type = 2
		then
			begin
				
				update recalculation."result" rr
					set 
						diff_volume = i.volume_result, 
						diff_result = i.benefit_result, 
						recalc_result = i.benefit_result
				from recalculation.root r
					inner join (
								select bc.account_id, bc.period_id, bc.sublist_id, -sum(bc.volume_result) as volume_result, -sum (bc.benefit_result) as benefit_result 
								from benefit.calculation bc
								where bc.account_id = _account_id 
									and bc.period_id = _period_id 
								group by bc.account_id, bc.period_id, bc.sublist_id
								) i on 1 = 1
				where rr.root_id = r.id 
					and  i.account_id = rr.account_id 
					and i.sublist_id = rr.sublist_id 
					and r."type" = 6 
					and r.period_id = _period_id;
			
			end;
	end if;

return null;

end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating benefit.update_calc()...';END$$;
COMMENT ON FUNCTION benefit.update_calc() IS '=============================================
 Author:		Поляков Павел
 Create date: 02.05.2017
 Description:	Обновление данных о расчете льгот при ручном редактировании
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering benefit.insert_calc()...';END$$;
CREATE OR REPLACE FUNCTION benefit.insert_calc()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
declare 
	_root_id 		int;
	_period_id 		int; 
	_date_begin 	date; 
	_date_end	 	date;
	_days 			int2;
	_benefit_type 	int2;
begin

	_period_id = (select period_id from inserted limit 1);

	_benefit_type = (select array_to_string(xpath('root/ui/usebenefit/text()', lower(p.xml_data::text)::xml)::text[], '')::int2
					from special.parametr p);

	if _benefit_type = 2
		then
			begin
				
				select date_begin, date_end, day_in_month 
				into _date_begin, _date_end, _days
				from "period".list 
				where id = _period_id;
		
				if exists (select * from recalculation.root where "type" = 6 and period_id = _period_id)
					then
						begin
							_root_id = (select id from recalculation.root where "type" = 6 and period_id = _period_id);
						end;
					else 
						begin 
							insert into recalculation.root ("name", "date", period_id, "type", rules, odn, period_begin, period_end)
							values ('Расчет льгот', current_date, _period_id, 6, 0, false, _period_id, _period_id);
				
							_root_id = (select max(id) from recalculation.root);	
						end;
				end if;
			
		 		insert into recalculation."result" (root_id, period_id, house_id, flat_id, account_id, sublist_id, date_begin, date_end, "day", diff_volume, recalc_result, diff_result, account_parent_id)
				select 
					 _root_id
					,_period_id
					,i.house_id
					,i.flat_id
					,i.account_id
					,sublist_id
					,_date_begin
					,_date_end
					,_days
					,-sum(volume_result)
					,-sum(benefit_result)
					,-sum(benefit_result)
					,i.account_parent_id
				from inserted i
				group by i.house_id, i.flat_id, sublist_id, i.account_id, i.account_parent_id;
				
			end;
	end if;
				
return null;				

end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating benefit.insert_calc()...';END$$;
COMMENT ON FUNCTION benefit.insert_calc() IS '=============================================
 Author:		Поляков Павел
 Create date: 02.05.2017
 Description:	Триггер записи результатов расчета в Recalculation.Result
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering benefit.delete_calc()...';END$$;
CREATE OR REPLACE FUNCTION benefit.delete_calc()
RETURNS trigger
LANGUAGE plpgsql
AS $_$
declare 
	_period_id int;
	_benefit_type int2;
begin
	
	_period_id = (select period_id from deleted limit 1);

	_benefit_type = (	select array_to_string( xpath('root/ui/usebenefit/text()', lower(p.xml_data::text)::xml)::text[] , '')::int2
						from special.parametr p )::int;

	if _benefit_type = 2
		then
			begin
				delete 
				from recalculation.root rr 
					using recalculation."result" r, deleted d 
				where rr.id = r.root_id and d.period_id = r.period_id and d.account_id = r.account_id and d.sublist_id = r.sublist_id and rr.period_id = _period_id and rr."type" = 6;
			end;
	end if;

	return null;

end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating benefit.delete_calc()...';END$$;
COMMENT ON FUNCTION benefit.delete_calc() IS '=============================================
 Author:		Поляков Павел
 Create date: 02.05.2017
 Description:	Удаление расчета льгот 
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering benefit.calc(integer, jsonb)...';END$$;
CREATE OR REPLACE PROCEDURE benefit.calc(IN _period_id integer, IN _house jsonb)
LANGUAGE plpgsql
AS $_$
declare 
		_date_begin date;
		_date_end 	date;
		_days 		int;
		_sql 		text = '';
		_sql_volume text = '';
		_sql_tarif 	text = '';
begin
	
	delete 
	from benefit.calculation
	where period_id = _period_id and house_id in (select h.house_id from jsonb_populate_recordset(null::house.list, _house) h);

	select date_begin, date_end, day_in_month 
	into _date_begin, _date_end, _days 
	from "period".list 
	where id = _period_id;

	drop table if exists __result; 
	create temp table __result (account_id int, account_parent_id int, sublist_id int,person_id int, benefit_id int, "type" int2, percent_housing int2, percent_utility int, volume numeric(9,5),tarif numeric(9,5));
	alter table __result
		add constraint __temp_result unique (account_id, sublist_id)  include (volume,tarif);
	alter table __result
		add constraint __temp_result_type unique ("type") include (percent_housing, percent_utility);
	
	drop table if exists __el_volume; 
	create temp table __el_volume  (account_id int, volume numeric(9,5), sublist_id int);
	alter table __el_volume 
	add constraint __temp_el_volume unique (account_id, sublist_id) include (volume);

	drop table if exists __pb_old_volume; 
	create temp table __pb_old_volume  (account_id int, sublist_id int , volume numeric(9,5), tarif numeric (9,2));
	alter table __pb_old_volume
	add constraint __temp_pb_old unique (account_id, sublist_id) include (volume, tarif);

	insert into __pb_old_volume
	select 
		account_id,
		sublist_id,
		volume,
		tarif
	from payment.balance
	where period_id = _period_id - 1 and print = 1;

	insert into __el_volume
	select 
		pb.account_id
		,sum (volume) volume
		,case 
			when ep = 1 
			then 
				case	
					when sublist_id in (27,72,74)
					then 27
					else sublist_id
				end
			when coalesce (ep,0) = 0
			then 
				case	
					when sublist_id in (72,73,74)
					then 72
					else sublist_id
				end
			else sublist_id
		end as sublist_id
	from payment.balance pb
		inner join calculation.parametr_transporate cp on pb.account_parent_id = cp.account_id
	where period_id = _period_id and sublist_id in (27,28,42,72,73,74) and print = 1
	group by pb.account_id, case 
							when ep = 1 
							then 
								case	
									when sublist_id in (27,72,74)
									then 27
									else sublist_id
								end
							when coalesce(ep,0) = 0
							then 
								case	
									when sublist_id in (72,73,74)
									then 72
									else sublist_id
								end
							else sublist_id
						end
	having sum (volume) <> 0.0;

	_sql = _sql ||
	'
	insert into __result
	select
		 pb.account_id
		,pb.account_parent_id
		,pb.sublist_id
		,bp.contragent_id
		,bp.benefit_id
		,coalesce(ut.parent_id, ut.id) as type
		,bl.percent_housing
		,bl.percent_utility';

	select tmp.sql_volume, tmp.sql_tarif
	into _sql_volume, _sql_tarif 
	from (
			select 	
				  string_agg('
			when bn.sublist_id = ' || cast(sublist_id as varchar(5)) || ' and bp.benefit_id = ' || cast(bn.benefit_id as varchar(5))  || ' then ' || formula, '') as sql_volume,
				  string_agg(' when bn.sublist_id = ' || cast(sublist_id as varchar(5)) || ' and bp.benefit_id = ' || cast(bn.benefit_id as varchar(5))  || ' then ' || formula_tarif, '') as sql_tarif
			from  benefit.list bl 
				inner join benefit.sublist_calc bn on bl.id = bn.benefit_id
				inner join benefit."type" bt on bt.id = bn."type"
				inner join benefit.formula bf on bf.id = bn.formula_id
		) as tmp;

	_sql_volume = (',case ' || _sql_volume || ' end as lgot_volume');
	_sql_tarif = (',case ' || _sql_tarif || ' end as lgot_tarif');

	_sql = _sql ||  _sql_volume || _sql_tarif ||  '
	from calculation.parametr_transporate cp
			inner join benefit.people bp on bp.account_id = cp.account_id
			inner join benefit.list bl on bl.id = bp.benefit_id
			inner join benefit.sublist_calc bn on bl.id = bn.benefit_id
			inner join payment.balance pb on pb.account_parent_id = bp.account_id and pb.sublist_id = bn.sublist_id and pb.period_id = ' || cast(_period_id as varchar(5)) || '
			inner join utility.sublist us on us.id = pb.sublist_id
			inner join utility.type ut on ut.id = us.type
			left join (select account_id, volume from payment.balance where sublist_id = 24 and period_id = ' || cast(_period_id as varchar(5)) || ' ) gv_work  on gv_work.account_id = pb.account_id
			left join (select account_id, volume from payment.balance where sublist_id = 24 and period_id = ' || cast(_period_id -1 as varchar(5)) || ' ) gv  on gv.account_id = pb.account_id
			left join __pb_old_volume pb_old on pb_old.account_id = pb.account_id and pb_old.sublist_id = pb.sublist_id
			left join __el_volume el on el.account_id = pb.account_id and el.sublist_id = pb.sublist_id
	where (pb.print = 1 or pb_old.volume is not null) and (bp.date_end is null or bp.date_end > ''' || cast(_date_begin as varchar(10)) || ''')'; 

	if _sql is not null
		then
			execute (_sql);
	end if;

	insert into benefit.calculation (period_id, house_id, flat_id, account_id, sublist_id, contragent_id, benefit_id, date_begin, date_end, days, lgot_volume, volume_result, benefit_result, account_parent_id)
	select 
		_period_id as period_id
		,aa.house_id as house_id
		,aa.flat_id as flat_id
		,r.account_id as account_id
		,r.sublist_id as sublist_id
		,r.person_id
		,r.benefit_id
		,_date_begin as date_begin
		,_date_end as date_end
		,_days as days
		,coalesce(r.volume,0) as volume
		,coalesce(r.volume * (case when r."type" in (0,3) then r.percent_housing when r."type" = 1 then r.percent_utility end) /100,0) as volume_result
		,coalesce(r.volume * (case when r."type" in (0,3) then r.percent_housing when r."type" = 1 then r.percent_utility end) /100,0) * coalesce(r.tarif,0) as re_calc_result
		,r.account_parent_id
	from __result r
		inner join adress.account aa on aa.id = r.account_id
		inner join jsonb_populate_recordset(null::house.list, _house) h on h.house_id = aa.house_id;

	drop table __result;
	drop table __el_volume;
	drop table __pb_old_volume;

end
$_$;


