COMMENT ON FUNCTION account.registration(integer, integer) IS '=============================================
 author:		глещинский д.в.
 create date: 18.12.2015
 description:	список проживающих на лицевом счете
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering account.owner_1с(integer)...';END$$;
CREATE OR REPLACE FUNCTION account.owner_1с(IN _period_id integer)
RETURNS TABLE(period_id integer, account_name character varying, full_name text, customer_type boolean, customer_inn character varying, customer_kpp character varying, contract_inn character varying, contract_kpp character varying, contract_id integer, contract_number character varying, contract_begin date)
LANGUAGE plpgsql
AS $_$
declare 
	_date_end 	date;
	_date_begin date;
begin

	select date_begin, date_end 
	into _date_begin, _date_end
	from period.list 
	where id = _period_id;

	return query
	with cte as 
	(
		select row_number () over (partition by ac.account_id order by cc.date_begin, cc.number, cc.id) as rn
			,ac.account_id
			,cc.contragent_id
			,cc.id as contract_id
			,cc.number as contract_number
			,cc.date_begin as contract_begin							
		from contragent.contract cc 
			inner join contragent.contract_account ac on ac.contract_id = cc.id
		where cc.date_begin <= _date_begin and coalesce(cc.date_end,_date_end) >= _date_end
	)

	select 
		_period_id as period_id
		,ai.account_name
		,case when person_id is null or surname is null then 'собственник лс ' || ai.account_name else ltrim(rtrim(pc.full_name)) end as full_name
		,pc.customer_type
		,(case when trim(pc.inn) = '' then null else trim(pc.inn) end)::varchar(12) as customer_inn
		,(case when trim(pc.kpp) = '' then null else trim(pc.kpp) end)::varchar(9) as customer_kpp
		,(case when pc.contract_id is not null then case when trim(pc.inn) = '' then null else trim(pc.inn) end end)::varchar(12) as contract_inn
		,(case when pc.contract_id is not null then case when trim(pc.kpp) = '' then null else trim(pc.kpp) end end)::varchar(9) as contract_kpp
		,pc.contract_id
		,pc.contract_number
		,pc.contract_begin
	from adress.info ai 
		left join
		(select row_number () over (partition by aa.name order by coalesce(is_responsible,false) desc, cl.type, cl.id) as rn
			,cl.inn
			,cl.kpp
			,c.contract_id
			,c.contract_number
			,c.contract_begin
			,cl.surname
			,cl.name
			,cl.middlename
			,cl.type as customer_type
			,cl.full_name
			,ca.id as person_id
			,ca.account_id
		from contragent.account ca
			inner join adress.account aa on aa.id = ca.account_id
			inner join contragent.owner_documents od on od.contragent_account_id = ca.id
			inner join contragent.list cl on cl.id = ca.contragent_id
			left join cte c on c.account_id = ca.account_id and c.contragent_id = ca.contragent_id and c.rn = 1
		where od.date_begin <= _date_begin and coalesce(od.date_end,_date_end) >= _date_end
		) pc on pc.account_id = ai.account_id and pc.rn = 1
	where ai.account_parent_id is null;
	
end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating account.owner_1с(integer)...';END$$;
COMMENT ON FUNCTION account.owner_1с(integer) IS '=============================================
 Author:		Юркин Е.Ю
 Create date: 06.04.2025
 Description:	Отчет собственники для 1С
 =============================================';


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Altering account.owner(integer)...';END$$;
CREATE OR REPLACE FUNCTION account.owner(IN _account_id integer)
RETURNS TABLE(contragent_id integer, full_name character varying, date_birth date, series character varying, number character varying, date_begin date, date_end date, share character varying, reg_date_begin date, reg_date_end date, place_birth character varying, kind_name character varying, is_responsible boolean, is_active boolean, rs text, t_prop text, t_status text, t_reg text, el_lgot_type text)
LANGUAGE plpgsql
AS $_$
declare 
	_date_begin date;
begin
	_date_begin = (select pl.date_begin from "period".list pl where pl.is_working = true);

	return query
	select 
		 ca.contragent_id
		,cl.full_name
		,ci.date_birth
		,co.series
		,co."number"
		,co.date_begin
		,co.date_end
		,co."share"
		,ca.reg_date_begin
		,ca.reg_date_end
		,ci.place_birth
		,dk."name" as kind_name
		,ca.is_responsible
		,(case when coalesce(co.date_end, _date_begin ) >= _date_begin then true else false end) as is_active
		,max(case when cp.parametr_id = 358 then pb."name" end) as "rs"
		,max(case when cp.parametr_id = 1383 then pb."name" end) as "t_prop"
		,max(case when cp.parametr_id = 1452 then pb."name" end) as "t_status"
		,max(case when cp.parametr_id = 1451 then pb."name" end) as "t_reg"
		,max(case when cp.parametr_id = 1472 then pb."name" end) as "el_lgot_type"
	from contragent.list cl
		inner join contragent.account ca on ca.contragent_id = cl.id
		inner join contragent.info ci on ci.contragent_id = cl.id
		inner join contragent.owner_documents co on co.contragent_account_id = ca.id
		inner join documents.kind dk on dk.id = co.kind_id
		inner join contragent.parametr cp on cp.contragent_account_id = ca.id 
		left join parametr.book pb on  pb.id = cp.book_id
		left join 
		(
			select
			ca.id contragent_account_id,
			sum(case when lower(pl.short_name) = 't_prop' then case when (lower(pb.name) = 'не проживает' or pb.id is null) then 0 else 1 end else 0 end) as status,
			sum(case when lower(pl.short_name) = 't_reg' then case when (lower(pb.name) = 'не зарегистрирован' or pb.id is null) then 0 else 1 end else 0 end) as reg
			from contragent.account ca
				left join contragent.parametr cp on cp.contragent_account_id = ca.id
				left join parametr.list pl on pl.id = cp.parametr_id
				left join parametr.book pb on pb.id = cp.book_id
			group by ca.id
		) param on param.contragent_account_id = ca.id 
	where ca.account_id = _account_id 
			and 
				(
					(co.date_end is null or co.date_end >= _date_begin) or 
					(co.date_end < _date_begin and param.status = 0 and param.reg = 0) or
					(param.reg > 0 and ca.reg_date_end < _date_begin)
				)
	group by ca.contragent_id, cl.full_name, ca.is_responsible, ci.date_birth, co.date_begin, co.date_end, co.series, co."number", co."share", ca.reg_date_begin, ca.reg_date_end, ci.place_birth, dk."name";
end;
$_$;


DO LANGUAGE plpgsql $$BEGIN RAISE NOTICE 'Creating account.owner(integer)...';END$$;
COMMENT ON FUNCTION account.owner(integer) IS '=============================================
